    ('坚不可摧', '二十年闺阁，养成拘墟笃时之见，牢不可破，坚不可摧。'),
    ('所作所为', '二弟从前所作所为，我岂不知，只是我做哥哥的，焉能认真。'),
    ('前无古人', '二者皆句语雄峻，前无古人。'),
    ('相提并论', '二者相提并论，则陈张两公之捐躯殉难，均有所迫而然也。'),
    ('天真无邪', '于北蓓天真无邪的举动使我对那一夜的真实细节只留下模糊的记忆，却有一个刻骨铭心的温馨印象。'),
    ('兢兢业业', '于是宁府中人才知凤姐厉害，自此俱兢兢业业，不敢偷安。'),
    ('恩将仇报', '亏这官人救了性命，今反恩将仇报，天理何在！'),
    ('名存实亡', '五代兵革相继，礼法陵夷，顾惟考课之文祗拘州县之辈，黜陟既异，名存实亡。'),
    ('井底之蛙', '井底之蛙，所见不大；萤火之光，其亮不远。'),
    ('满不在乎', '交代了几句话，满不在乎地随苏沛霖到了朱家。'),
    ('高楼大厦', '亲戚同高楼大厦，朋友共肥马轻车。'),
    ('生死存亡', '亲承懿旨到西宫，生死存亡掌握中。'),
    ('形形色色', '人上一百，形形色色，难免良莠不一，何况是上千上万。'),
    ('天下太平', '人人好公，则天下太平；人人营私，则天下大乱。'),
    ('勇往直前', '人人惧摩拳擦掌，个个勇往直前。'),
    ('海阔天空', '人们总羡慕海阔天空，以为一片茫茫，无边无界，必然大有可观。'),
    ('恶性循环', '人们破坏生态环境，自然就造成生态的恶性循环。'),
    ('流连忘返', '人君之宴乐有常，未闻流连忘返。'),
    ('当仁不让', '人家骂小弟鱼肉乡愚，这句话仔细想来，在小弟却是当仁不让。'),
    ('装腔作势', '人民不喜欢假话，哪怕多么装腔作势，多么冠冕堂皇的假话都不会打动人民的心。'),
    ('一网打尽', '人民也会想到：使汉奸合法化的，自己就是汉奸，人民的决心是要一网打尽的。'),
    ('自给自足', '人民在党和政府的组织领导下，展开了自给自足的大生产运动。'),
    ('大有可为', '人民政协作为统一战线组织，任务是十分光荣的，工作是大有可为的。'),
    ('任重道远', '人民教师肩负着培养祖国建设接班人的重担，任重道远。'),
    ('海角天涯', '人民法庭早安排，海角天涯难逃避。'),
    ('一针一线', '人民解放军纪律严明，公买公卖，不许妄取民间一针一线。'),
    ('人生在世', '人生在世，吃喝两字。'),
    ('磕磕绊绊', '人生道路难免会有磕磕绊绊的。'),
    ('走下坡路', '人过了四十，身体就开始走下坡路了'),
    ('不厌其烦', '今之史学则异是，必致谨于闾阎日用之细，起居笑貌之琐，不厌其烦，不嫌其鄙。'),
    ('九品中正', '今天下四万万人之材性，长素岂尝为其九品中正而一切检察差第之乎？'),
    ('当务之急', '今学者当务之急，曰中国古今史，曰泰东西古近史。'),
    ('身不由主', '今既到此间，身不由主，拼着这条命吧。（清·钱彩《说岳全传》第六十六回）'),
    ('出其不意', '今日是年晚，此老必定在家，须乘此时调兵围住，出其不意，方无走失。'),
    ('死里逃生', '今日死里逃生，夫妻再合。'),
    ('闻所未闻', '今日见了紫菱姐姐飞来飞去，业已奇极；谁知还有海外这些异事，真是闻所未闻。'),
    ('投其所好', '今王志在报吴，必先投其所好，然后得制其命。'),
    ('后来居上', '今老矣，乐不预少年文酒之会，后来居上，又不知其为谁？'),
    ('冷暖自知', '今蒙指授入处，如人饮水，冷暖自知。今行者即是某人师也。'),
    ('万不得已', '今门之事，出于万不得已，并非有意为之。'),
    ('与众不同', '从他与众不同的解题思路中，看出他很聪明。'),
    ('游刃有余', '从前他们又要办厂，又要做公债，也居然稳渡了两次险恶的风波，现在他们全力来做公债，自然觉得游刃有余。'),
    ('一干二净', '从前学过的一点天文学知识，长期不用，早忘得一干二净。'),
    ('无所不能', '从小风流俊雅，无所不能。'),
    ('知行合一', '从晓庄师范到山海工学团，陶先生一以贯之的精神是‘知行合一’、‘教学做合一’，力求培养学生从整体上驾驭知识的能力。'),
    ('适可而止', '从来没有暴风雨能够持久的。果然持久了，我们也吃不消，所以我们要它适可而止。'),
    ('马马虎虎', '从此，我读什么书都不再马马虎虎了。'),
    ('老老实实', '从这个上面规定我们的方针，不是一般地反对游击主义，而是老老实实地承认红军的游击性。'),
    ('血肉模糊', '仔细看去，这条路上血肉模糊成了一片，没有一个干净的尸体。'),
    ('不知去向', '他一下子就不知去向。'),
    ('不怀好意', '他一向对弱小者都不怀好意。'),
    ('助人为乐', '他一向都是助人为乐。'),
    ('胆小怕事', '他一向都是胆小怕事。'),
    ('修修补补', '他一回家就修修补补。'),
    ('一字一句', '他一字一句地交代工作。'),
    ('骂骂咧咧', '他一路骂骂咧咧地数落没完。'),
    ('一门心思', '他一门心思搞技术革新。'),
    ('大吃大喝', '他上馆子，下酒铺，从不敢大吃大喝，大手大脚，颇为紧吃慢用，细水长流。'),
    ('半路出家', '他不理会内行的嗤笑，写啊改啊，改啊写啊，终于写出了好作品，成了一个颇有希望的半路出家的作家。'),
    ('漏网之鱼', '他两个忙忙如丧家之狗，急急似漏网之鱼。'),
    ('起早贪黑', '他为了早日完成他的软件编制工作起早贪黑，不辞辛劳。'),
    ('不动声色', '他也不动声色，勤勤慎慎办他的公事。'),
    ('指点江山', '他习惯于指点江山。'),
    ('飞蛾扑火', '他今日自来投到，岂不是飞蛾扑火，自讨死吃的。'),
    ('才华横溢', '他从小就流露出才华横溢的天资来。'),
    ('不甘示弱', '他从来都是不甘示弱的，总要超出别人一筹。'),
    ('你追我赶', '他们你追我赶，捷报频传。'),
    ('一见如故', '他们俩一见如故，谈得很投机。'),
    ('形影不离', '他们俩是一对形影不离的好朋友。'),
    ('好景不长', '他们匆匆结合，总是好景不长的。'),
    ('矫揉造作', '他们原是好好妇人，却要装作男人，可谓矫揉造作了。'),
    ('亲戚朋友', '他们又是直接联系群众的，亲戚朋友、各方面的人听到这些事，人心不安。'),
    ('阴阳怪气', '他们哪一个上想顺我的心？哪一个不是阴阳怪气。'),
    ('叽叽喳喳', '他们在那边叽叽喳喳没完。'),
    ('生离死别', '他们已有那样的情感，又遇着那些生离死别的事。'),
    ('日以继夜', '他们日以继夜，夜以继日，栖在小房子里。'),
    ('鸡毛蒜皮', '他们是为了报答你的恩情，才送给你；你倒说是鸡毛蒜皮。'),
    ('恭恭敬敬', '他们是准备投降的，所以恭恭敬敬地执行了日本人和汪精卫的命令，先把最坚决的抗日分子杀死。'),
    ('天生一对', '他们是天生一对活宝。'),
    ('落荒而逃', '他们根本不是对手，只好落荒而逃。'),
    ('贪生怕死', '他们没有一个贪生怕死而逃跑的，他们知道多一个人多一分力量。'),
    ('脚踏实地', '他们渐渐丢了那空架子，脚踏实地向前走去。'),
    ('为所欲为', '他们满以为有了如此强大精良的武器，就可以在别人的国土上横行霸道、为所欲为。'),
    ('密不可分', '他们的关系是密不可分的。'),
    ('难舍难分', '他们真是有点难舍难分的。'),
    ('不可理喻', '他们简直不可理喻，一定要进去，终于被我们的人赶出来了。'),
    ('无耻之徒', '他们简直就是无耻之徒。'),
    ('全力以赴', '他们缺乏一种主动的积极的高兴的欢迎的全力以赴的精神。（毛泽东《〈中国农村的社会主义高潮〉序言》）'),
    ('卷土重来', '他们要挣扎，他们要变天，他们要卷土重来。'),
    ('说说笑笑', '他们说说笑笑，闹到尽欢而散。'),
    ('坚定不移', '他们走得很慢，然而是坚定不移地向前走。'),
    ('生不如死', '他们过着生不如死的生活。'),
    ('点头称是', '他们都听得津津有味，点头称是。'),
    ('阴差阳错', '他们阴差阳错地把多年渴望见面的机会失掉了。'),
    ('恋恋不舍', '他们，农会主任和青妇队长在炮声隆隆中，恋恋不舍地把我们送出了很远很远。'),
    ('似懂非懂', '他似懂非懂的还没完全明白过来。'),
    ('金碧辉煌', '他便把门面装璜得金碧辉煌，把些光怪陆离的洋货，罗列在外。'),
    ('议论纷纷', '他俩现在越发脱离群众，每天下午跑到宝塔下谈天，群众议论纷纷。'),
    ('平民百姓', '他倚仗这两处势力，结交府县官员，欺负平民百姓，专一好酒贪花，见财起意。'),
    ('干净利落', '他做得很干净利落。'),
    ('方方正正', '他做得方方正正、规规矩矩的。'),
    ('一饮而尽', '他像一个英雄人物一样昂着头，敞开衣襟，端起酒杯，一饮而尽。'),
    ('多管闲事', '他先骂周炳不安分守己，又骂周炳爱多管闲事。'),
    ('心高气傲', '他到任之后，靠着自己内有奥援，总有点心高气傲。（清·李宝嘉《官场现形记》第四十二回）'),
    ('踏踏实实', '他办事一向都很踏踏实实。'),
    ('心力衰竭', '他劳累过度，死于心力衰竭'),
    ('身无分文', '他北上求职，却遭到扒手扒窃，身无分文，求告无门。'),
    ('苦不堪言', '他受的磨难真是苦不堪言。'),
    ('命中注定', '他命中注定要身败名裂的。'),
    ('花花公子', '他和小丑的不同，是不扮横行无忌的花花公子，也不扮一味仗势的宰相家丁。'),
    ('咬紧牙关', '他咬紧牙关，忍受剐心似的痛楚。'),
    ('暴跳如雷', '他哥哥知道了，气得暴跳如雷。叫了他去骂。'),
    ('谈笑风生', '他嘻嘻笑着，让酒让菜，谈笑风生，又谈起他的山林生活。'),
    ('惨不忍睹', '他在一场车祸中不幸遇难，那场景真是惨不忍睹。'),
    ('忍无可忍', '他在忍无可忍的情况下，终于出手还击。'),
    ('一声不响', '他坐在那里一声不响。'),
    ('众叛亲离', '他坚持与人民为敌，以至众叛亲离，死无葬身之地。'),
    ('精力充沛', '他始终都是精力充沛、斗志昂扬。'),
    ('安安稳稳', '他安安稳稳地坐在牛背上。'),
    ('模棱两可', '他害怕事情一旦变化，他将有不测大祸，所以跪在地上回答了一句模棱两可的话。'),
    ('入不敷出', '他家人口太多，收入少，常常入不敷出。'),
    ('寸步不离', '他家女孩儿韩爱姐，逐日上去答应老太太，寸步不离，要一奉十，拣口儿吃用，换套穿衣。'),
