    ('苦大仇深', '他对地主阶级是苦大仇深。'),
    ('只字不提', '他对此事只字不提。'),
    ('情有独钟', '他对电脑编程情有独钟。'),
    ('七上八下', '他就感觉得七上八下，心里老不自在。'),
    ('大大咧咧', '他就是大大咧咧的性格。'),
    ('体无完肤', '他就静悄悄地看下去，看到把各种责难都驳斥得体无完肤之后，他又低声念起来。'),
    ('望其项背', '他已窥破喜奎和小雀儿的深情密爱，万万不是本人所能望其项背。'),
    ('安安心心', '他已经安安心心过日子了。'),
    ('赞不绝口', '他常常在我面前把秋桐的文章捧上了天，赞不绝口。'),
    ('半夜三更', '他常常工作到半夜三更。'),
    ('年事已高', '他年事已高，不再适合担任这个职务了'),
    ('活灵活现', '他忽然把个乐正子又请出来，说的活灵活现，倒也有个意思。'),
    ('唯唯诺诺', '他思念父母面上，一体同气，听其教诲，唯唯诺诺，并不违拗。'),
    ('大喊大叫', '他急得大喊大叫。'),
    ('不懂装懂', '他总喜欢不懂装懂，瞎指挥。'),
    ('大打出手', '他总是动不动就大打出手。'),
    ('没完没了', '他总是没完没了地缠着我。'),
    ('大祸临头', '他感到大祸临头了。'),
    ('自相残杀', '他成日间叫我们自相残杀，要我们自家人都互相杀尽了，好叫他那些骚鞑子来占据我们的好土地。'),
    ('所到之处', '他所到之处都受到热烈的欢迎。'),
    ('打定主意', '他打定主意非把事情弄明白不可。'),
    ('一五一十', '他把事情发生的经过一五一十地向大家讲了一遍。'),
    ('简明扼要', '他把此事简明扼要作了汇报。'),
    ('得意忘形', '他把科长看成有天那么大，把他和科长连在一块，他没法不得意忘形。'),
    ('原封不动', '他把那个人送来的礼物原封不动地退了回去。'),
    ('早出晚归', '他按照早出晚归捕鱼撒网那股悠闲的心情撑着船，编算着使自己高兴也使别人高兴的事情。'),
    ('无拘无束', '他放开缰绳，任由枣红马无拘无束和驰骋。'),
    ('情有可原', '他既不是存心去参加，似乎情有可原。'),
    ('翻来覆去', '他早饭也没吃，把自己关在房里，翻来覆去考虑该怎么办，一时竟找不出主意。'),
    ('疑难杂症', '他是一个专攻疑难杂症的大夫'),
    ('罪该万死', '他是一个作恶多端，民愤极大，罪该万死的罪犯。'),
    ('有血有肉', '他是一个有血有肉的人。'),
    ('非同寻常', '他是一个非同寻常的人物。'),
    ('彻头彻尾', '他是个彻头彻尾的机会主义者。'),
    ('土生土长', '他是当地土生土长人。'),
    ('正儿八经', '他是正儿八经的庄稼人。'),
    ('大雅之堂', '他是难登大雅之堂的。'),
    ('负债累累', '他曾经为买书而负债累累。'),
    ('一无所获', '他最终还是一无所获。'),
    ('有钱有势', '他有一个有钱有势的老爸。'),
    ('神志不清', '他有些神志不清，少理会他。'),
    ('忽冷忽热', '他有忽冷忽热的毛病。'),
    ('突飞猛进', '他本期学习成绩突飞猛进。'),
    ('毫不留情', '他毫不留情地开除了她。'),
    ('大大方方', '他渐渐抛弃了这种虚荣或者说自卑，大大方方站在队列中取他的饭。'),
    ('热泪盈眶', '他激动得热泪盈眶。'),
    ('火冒三丈', '他爱发脾气，动辄火冒三丈。'),
