    ('浓墨重彩', '他用浓墨重彩，着重描写这次活动。'),
    ('合不拢嘴', '他的一个笑话逗得大家合不拢嘴。'),
    ('哑口无言', '他的一席话，使在场的人个个哑口无言。'),
    ('大起大落', '他的一生多次都是大起大落的。'),
    ('令人作呕', '他的下流动作真令人作呕'),
    ('若即若离', '他的书虽然和《了凡纲鉴》也有些相合，但大段又很不相同，若即若离，令人不知道讲起来应该怎样拉在一处。'),
    ('烟消云散', '他的兴致被突然传来的坏消息吹得烟消云散。'),
    ('雷打不动', '他的决心是雷打不动的。'),
    ('无缘无故', '他的力量，力气，一向使他自尊自傲，可是在过去的这些日子，无缘无故的他受尽了委曲与困苦。'),
    ('喜闻乐见', '他的卧薪尝胆的故事，两千多年来为人民所喜闻乐见。'),
    ('字正腔圆', '他的字正腔圆的唱功让人佩服。'),
    ('数一数二', '他的学习成绩在班里是数一数二的。'),
    ('天真烂漫', '他的性情又是那样天真烂漫，笃实敦厚。'),
    ('漏洞百出', '他的文章漏洞百出，自相矛盾。'),
    ('不知不觉', '他的残忍和狠毒，时而不知不觉地在老人面前显露出来。'),
    ('唠唠叨叨', '他的老婆老是唠唠叨叨个没完。'),
    ('无人不知', '他的臭事到了无人不知的地步。'),
    ('独到之处', '他的论文有他的独到之处，是别人始料不及的。'),
    ('强词夺理', '他的话简直就是强词夺理，你不要信他。'),
    ('经验之谈', '他的这番话是经验之谈，值得参考。'),
    ('富丽堂皇', '他的这篇文章，可谓是富丽堂皇。'),
    ('硬着头皮', '他硬着头皮去见老板。'),
    ('稀里糊涂', '他稀里糊涂地接受她的请求。'),
    ('尽如人意', '他稍稍感到天下事不能尽如人意了。'),
    ('精疲力竭', '他精疲力竭地倒在沙发靠背上，一口一口地喘着气。'),
    ('不负众望', '他终于不负众望，成为村里的第一个大学生。'),
    ('朝思暮想', '他终于回到了阔别多年、朝思暮想的故乡。'),
    ('如愿以偿', '他终于如愿以偿，考上的北京大学。'),
    ('浪子回头', '他终于浪子回头，改邪归正了。'),
    ('胡编乱造', '他胡编乱造出这些事来。'),
    ('坑坑洼洼', '他脸上坑坑洼洼的真难看。'),
    ('浑浑噩噩', '他自己在十六七岁时浑浑噩噩的，所以觉得十六岁的女孩子便那么练达人情世故，不是“寿相”。'),
    ('自说自话', '他自说自话道：没人能超过我的。'),
    ('下落不明', '他至今下落不明。'),
    ('惊魂未定', '他至今还惊魂未定。'),
    ('顺水推舟', '他若留我，乐得顺水推舟。'),
    ('鸡皮疙瘩', '他被吓得浑身长满了鸡皮疙瘩。'),
    ('拒之门外', '他被拒之门外，只好悻悻而归。'),
    ('风度翩翩', '他西装革履，风度翩翩。'),
    ('先见之明', '他觉得胆小的杜竹斋有时候实在颇具先见之明，因而也省了多少烦恼。'),
    ('没日没夜', '他让省里科研所请去了，正没日没夜地写书哪！'),
    ('语无伦次', '他语无伦次地向周围的人诉说自己的遭遇。'),
    ('举世无双', '他说善于玩把戏，空前绝后，举世无双，人们从来就没有看见过；一见之后，便即解烦释闷，天下太平。'),
    ('直截了当', '他说话、办事直截了当，认真干脆。'),
    ('一本正经', '他说话从来都是一本正经，不苟言笑。'),
    ('结结巴巴', '他说话总是结结巴巴的。'),
    ('贪得无厌', '他贪得无厌的性子，随着年岁的增长，更加残忍了。'),
    ('路见不平', '他赶快转过口又说道：‘我不过路见不平，说几句气话罢哩！’'),
    ('跌跌撞撞', '他跌跌撞撞地走了过来。'),
    ('无疾而终', '他身体一直很好，90岁才无疾而终。'),
    ('血海深仇', '他转回身来，面向着哀悼的人群，“我们要把悲痛变成力量，我们要誓死报这场血海深仇。”（曲波《林海雪原》十八）'),
    ('转眼之间', '他转眼之间就不见了。'),
    ('语重心长', '他这些语重心长的话，深深地打劫了我的心。'),
    ('沉不住气', '他这人就是沉不住气。'),
    ('自作自受', '他这会子不说保养着些，还要捉弄人；明儿病了，叫他自作自受。'),
    ('引人注目', '他这样做就是要引人注目。'),
    ('迫不得已', '他这样做，完全是迫不得已。'),
    ('飞黄腾达', '他进过种种培植新政人才的讲习班和训练班，虽然结果没有一项使他飞黄腾达。'),
    ('进进出出', '他进进出出的都不理众人。'),
    ('迫不及待', '他迫不及待地推开门，走进屋去。'),
    ('钻牛角尖', '他遇事爱钻牛角尖。'),
    ('风风火火', '他那风风火火的性格是很难改变的。'),
    ('众望所归', '他非去不可！众望所归，还有什么可说的呢？'),
    ('心狠手辣', '他颐指气使人，心狠手辣。'),
    ('昏昏欲睡', '以为诗能散人襟怀，顾览他人诗，昏昏欲睡又何也？（清·归庄《许更生诗序》）'),
    ('浑身解数', '以后的三年里，她如同狮子滚绣球一般，无一时不活动，无一时不是使出浑身解数的在活动。'),
    ('不相上下', '以愚观之，晋楚互为雌雄，不相上下。'),
    ('不败之地', '以求自立于不败之地，则谥之曰‘保守主义’。'),
    ('可见一斑', '以酗酒狎妓之微嫌，遂没其困苦艰难之功业，清朝之赏罚不均，可见一斑。'),
    ('仰天大笑', '仰天大笑出门去，我辈岂是蓬蒿人。'),
    ('一拥而上', '众人一拥而上，把小偷团团围住揪送派出所'),
    ('半信半疑', '众人听了，也都半信半疑。'),
    ('异口同声', '众人异口同声地叫着：“罚！罚！”'),
    ('悬崖峭壁', '众人打一看时，四面尽是高山，左右是悬崖峭壁。'),
    ('言之有理', '众卿言之有理，再上酒来。'),
    ('半斤八两', '众将看他两个本事，都是半斤八两的，打扮也差不多。'),
    ('势不可挡', '众将见西岐士马英雄，势不可挡，并无一筹可展，半策可施。'),
    ('劫富济贫', '会因南北统一，所谋未遂，乃想学王天纵的行为，劫富济贫，自张一帜。'),
    ('熟能生巧', '会而不难终要学，熟能生巧岂徒诗。'),
    ('意气风发', '伟大的中国人民正在意气风发地建设自己的祖国。'),
    ('伯仲之间', '伯仲之间见伊吕，指挥若定失萧曹。'),
    ('故弄玄虚', '似乎在故弄玄虚，不叫人懂，真使人纳闷。'),
    ('天灾人祸', '但仆生长危邦，年逾大衍，天灾人祸，所见多矣。'),
    ('毅然决然', '但似乎因为舍不得皮夹里仅存的六角钱，所以竟也毅然决然地走远了。'),
    ('自怨自艾', '但倘有不知道自怨自艾的人，想将这位先生“送进疯人院”去，我可要拚命反对，尽力呼冤的。'),
    ('无可救药', '但彼此内溃已久，无可救药，只能听之而已。'),
    ('废寝忘食', '但得个寄信传音，也省的人废寝忘食。'),
    ('根深蒂固', '但我总还想对于根深蒂固的所谓旧文明，施行袭击，令其动摇，冀将来有万一之希望。'),
    ('尽力而为', '但我看得目下决难挽回，丞相可去尽力而为。'),
    ('旁门左道', '但所谓“洞主，岛主”，只不过是一批既不属任何门派、又不隶什么帮会的旁门左道之士。'),
    ('得过且过', '但是吃烟人的脾气，总是得过且过，那一个是真心肯戒。'),
    ('归根到底', '但是归根到底它是细致的工作，精雕细刻的工作，很深入的工作，结果得益处大，兵就不跑。'),
    ('热热闹闹', '但是我们的群众路线，不是满足于那个热热闹闹，主要的是要做经常的、细致的工作，做人的工作。'),
    ('不可磨灭', '但是我又不知道这是不可磨灭的事实。'),
    ('纹丝不动', '但是由于调皮骡子长久没有摊上任务，求战心切，仍然纹丝不动地聚精会神地伏在草丛里。'),
    ('称心如意', '但是这个贵州，十分瘠苦，处万山之中，又是晴少雨多，吃的、用的、穿的，无一样能够称心如意。'),
    ('丧心病狂', '但是顽固派反对派对于进步文化机关的违法摧残其合法的事业，其丧心病狂，可谓已达极点。'),
    ('先天不足', '但是，剧本中若只出现几个店员，总显得有些先天不足。'),
    ('明明白白', '但须不设暗计，明明白白，有手段平空拿我，吾即拜降。'),
    ('按部就班', '但黄公俊的祖父，他开始读了书，象一般读书人似的，他按部就班的要将八股型的才学，“货与帝王家”。'),
    ('天旋地转', '低下头歇了一会，觉得天旋地转，忽忽悠悠，再也站不起来。 ◎梁斌《红旗谱》四五'),
    ('何去何从', '何去何从，罢龟策之臧否；自开自落，任天地之荣枯。'),
    ('急急忙忙', '何必急急忙忙地要来‘统一’这块巴掌大的边区呢？'),
    ('天马行空', '余于近日交游之诗，其心契者，曾弗人如天马行空，不可羁勒。'),
    ('来来去去', '余华《活着》：“他坐在坑道外的土墩上吸着烟，看着那些来来去去的黄皮大兵。”'),
    ('习以为常', '余大先生在虞府坐馆，早去晚归，习以为常。'),
    ('卸磨杀驴', '作为领导人千万不能卸磨杀驴，否则会失去人心的。'),
    ('无可厚非', '作者的动机无可厚非，但客观效果则不尽符合作者的动机。'),
    ('深信不疑', '你不能对他的话深信不疑。'),
    ('吊儿郎当', '你不能总是这样吊儿郎当的好不好？'),
    ('三天两头', '你不要三天两头往我这儿跑。'),
    ('天方夜谭', '你不要做天方夜谭的梦了。'),
    ('丢人现眼', '你不要在这里丢人现眼。'),
    ('没事找事', '你不要没事找事，挑起事端。'),
    ('蒸蒸日上', '你世兄又是槃槃大才，调度有方，还怕不蒸蒸日上吗？（清·李宝嘉《官场现形记》第五十二回）'),
    ('上上下下', '你们从下面上来，左邻右舍，上上下下，接触广泛，了解的人多。'),
    ('女流之辈', '你们女流之辈懂什么。'),
    ('四面八方', '你们瞧见了，然后连皮带骨，一概都化成一股灰，再化一股烟，一阵大风，吹的四面八方，都登时散了。'),
    ('轻轻松松', '你倒好意思，轻轻松松说不要了。'),
    ('一时三刻', '你出来不出来？一时三刻就把你烧成黑炭了！'),
    ('胡言乱语', '你则管哩便胡言乱语，将我厮花白。'),
    ('功成名就', '你则说做官的功成名就，我则说出家的延年益寿。'),
    ('吃吃喝喝', '你别整天只知道吃吃喝喝，干些实事吧。'),
    ('古色古香', '你可以从明亮的窗玻璃后面看到古色古香的字画、瓷器、铜鼎和小铜佛等等。'),
    ('多多少少', '你多多少少与此事有点牵连。'),
    ('感同身受', '你如果能给我解决三分之一，我真是感同身受呢！（叶圣陶《感同身受》）'),
    ('冰天雪地', '你就在这儿吧，冰天雪地的上哪儿去？'),
    ('评头论足', '你应该多干点实事，不要总评头论足。'),
    ('随波逐流', '你心胸开阔，气度那么从容！你不随波逐流，也不故步自封。'),
    ('纠缠不清', '你怎么老是跟他纠缠不清。'),
    ('包罗万象', '你怎言包罗万象，迟早飞升。'),
    ('长命百岁', '你怕死，你长命百岁的活着，好不好？（清·曹雪芹《红楼梦》第二十回）'),
    ('不言而喻', '你想他们这朋友之乐，尽可不言而喻了。'),
    ('可想而知', '你想日本人练陆军把东三省地图当作功课，其用心可想而知。'),
    ('慌慌张张', '你慌慌张张的是为什么？'),
    ('龙潭虎穴', '你父亲因他不是个诗书礼乐之门，一面推辞，便要离了这龙潭虎穴。'),
    ('真心真意', '你猜炳哥怎么说的？他说他从前真心真意爱过的，只有一个人。真心真意好过的，也只有一个人。'),
    ('只言片语', '你的只言片语对我也是一种安慰。'),
    ('狗屁不通', '你的文章尽管狗屁不通，有人争先恐后的请你做广告。'),
    ('站不住脚', '你的说法站不住脚。'),
    ('白手起家', '你看，他发了多少财，白手起家，靠的是谁？如今也忘了水源头了，墙上的草，两边倒着呢。'),
    ('两手空空', '你知道我做公债亏得一塌糊涂，差不多两手空空了。'),
    ('英雄好汉', '你算什么英雄好汉？'),
    ('用武之地', '你自己先把根基弄坏了，将来就有用武之地，也不能做个大英雄，岂不是自暴自弃？'),
    ('头破血流', '你若在继续顽抗下去，必定会碰得头破血流！。'),
    ('男女老少', '你要通知到村里的男女老少。'),
    ('立竿见影', '你说你莲花化身，清净无为，其如五行变化，立竿见影。'),
    ('添油加醋', '你说话要实事求是，不要添油加醋。'),
    ('令人满意', '你这样处理太难令人满意了。'),
    ('一家老小', '你问我借盘缠，我一天杀一个猪，还赚不到钱把银子，都给你去丢在水里，叫我一家老小喝西北风？'),
    ('无名之辈', '你问的这人，你既称到他是个豪杰，大约也不是甚么无名之辈，你说给我听听。'),
    ('拍案叫绝', '使人见之，一个个欢欣鼓舞，快意舒怀，不禁拍案叫绝。'),
    ('望而却步', '使你自然而然的望而却步。'),
    ('无能为力', '使兵饷顿竭，忠臣流涕顿足而叹，无能为力，惟有一死以报国，不亦大可哀乎？'),
    ('荡然无存', '使民国政制，荡然无存，澔澔新邦，悬为虚器。'),
    ('挖空心思', '例如问《十三经》是什么，文天祥是那朝人，全用不着自己来挖空心思做，一做，倒糟糕。'),
    ('焕然一新', '依中国法度，造作旗帜大纛，焕然一新。'),
    ('千辛万苦', '侨胞的金钱不是容易得到的，是由于他们胼手胝足，千辛万苦，省吃俭用，积累起来的。'),
    ('怨天尤人', '便是那愤懑不平之气，放诞无忌惮之言，心中口中，怨天尤人个不了。'),
    ('事在人为', '俗语说事在人为，只要你勤奋努力，一定能有所作为。'),
    ('口是心非', '俺哥哥原来是口是心非，不是好人了也。'),
    ('不可开交', '倘一加人为，一“办”，那就舆论沸腾，不可开交了。'),
    ('罪大恶极', '倘不如命地“帮忙”，当然，罪大恶极了。先将忘恩负义之罪，布告于天下。'),
    ('不堪设想', '倘使没有这个人来阻拦一下，那天的情形恐将不堪设想的了。'),
    ('万劫不复', '倘使连这一点反抗心都没有，岂不就成为万劫不复的奴才了？'),
    ('顾全大局', '倘若东林、复社两党的朋友，能够顾全大局，解除纠纷，也未尝不可一变士林的风气。'),
    ('如花似玉', '假如不幸我庄周死后，你这般如花似玉的年纪，难道捱得过三年五载？'),
    ('和蔼可亲', '假若有人愿意来看他，他是个顶和蔼可亲的人。'),
    ('后悔莫及', '做事要小心，万一出了什么意外就后悔莫及了。'),
    ('成千上万', '做假事骗得了几个人，骗不了成千上万的人。'),
    ('救死扶伤', '做外科医生的能够以肉补肉，以血补血，则救死扶伤，造福人群，岂不大哉！'),
    ('举手之劳', '做好这件事对我们来说是举手之劳的事。'),
    ('纵横天下', '健儿掷杯砍案曰：吾纵横天下三十年矣，未逢敌手，有能取我腰间物者，当叩首降之。'),
    ('楚楚可怜', '偶抱恙，抱闲泄子诊视，虽云鬓蓬松，而意态幽闲，大有楚楚可怜之致。'),
    ('感恩戴德', '偶有一个狡滑的民贼出来，略用些小恩小惠来抚弄他，他便欢天喜地感恩戴德。'),
    ('天花乱坠', '傅二棒锤索性张大其词，说得天花乱坠。'),
    ('死灰复燃', '儒家的理论，非等到董仲舒不能死灰复燃的。'),
    ('光宗耀祖', '儿子管他，也为的是光宗耀祖。'),
    ('各式各样', '儿童乐园里的玩具各式各样，真是好玩极了。'),
    ('眉清目秀', '元·无名氏《合同文学》第一折：“有个小孩唤做按住，今年三岁，生得眉清目秀，是好一个孩儿也。”'),
    ('大惊小怪', '兄弟，休要大惊小怪的，则他便是杨衙内，是个有权有势的的。'),
    ('呼风唤雨', '兄弟，你真是玛志尼一流人物，天生成呼风唤雨，搅得一国的原动力的了。'),
    ('痛不欲生', '先兄晴湖言：有王震升者，暮年丧爱子，痛不欲生。'),
    ('以此类推', '先生不信，拣几个岛名试试他，果然记得，那真没法难他了。以此类推，可见浅近的物理学，生理学等类，他都晓得。'),
    ('身体力行', '先生以致知格物为基阯（址），以身体力行为堂奥。'),
    ('顶天立地', '先生是楚国的栋梁，是顶天立地的柱石。'),
    ('天各一方', '先生此去，天各一方，未知相会却在何日。'),
    ('光阴似箭', '光阴似箭，日月如梭，不觉半年有余。'),
    ('埋头苦干', '克己奉公，埋头苦干的精神，才是可尊敬的。'),
    ('阴谋诡计', '党处于敌人和同盟者的阴谋诡计的包围中，但是没有警觉性。'),
    ('兴致勃勃', '全班同学早就集合好，兴致勃勃地向野游地进发了。'),
    ('欣喜若狂', '全班同学欣喜若狂，向取得第一名的同学庆祝。'),
    ('无恶不作', '八国联军侵略中国时，在北京杀人放火，无恶不作。'),
    ('举重若轻', '公听视机警，受大任举重若轻。上爱其才敏，倚若股肱。'),
    ('妙不可言', '公子侧会其意，一吸而尽，觉甘香快嗓，妙不可言。'),
    ('血气方刚', '公子杨干，乃悼公之同母弟，年方一十九岁，新拜中军戎御之职，血气方刚，未经战阵。'),
    ('称兄道弟', '公安局通缉的杀人犯，可以住在他公馆里不受法律制裁，公安局长跟他照样称兄道弟，'),
    ('不慌不忙', '公路在山上盘旋，车子不慌不忙地打着圈子。'),
    ('过目不忘', '公过目不忘，真天下奇才也！'),
    ('一触即发', '共产党主张成立联合政府，就为罅内战。现在蒋介石拒绝了这个主张，致使内战有一触即发之势。'),
    ('耀武扬威', '共涛、吞珪船到岛边，耀武扬威，统兵上岸。童威、童猛谨守寨栅，不与交战。'),
    ('措手不及', '关公赤兔马快，早已跑到面前，颜良措手不及，被云长手起一刀，刺于马下。'),
    ('势如破竹', '关胜等众，乘势长驱，势如破竹，又克大谷县。'),
    ('标新立异', '其中典礼集会之词，标新立异固不可，机械陈腐亦不可。'),
    ('平起平坐', '其中很有几个体面的人，平时也到过府里，同万太尊平起平坐的，如今却被差役们拉住了辫子。'),
    ('出谋划策', '其余的人，连老贺在内，也都出谋划策，各有贡献。'),
    ('眼花缭乱', '其余这些国王，除了我们到过的，内中许多奇形怪状，小弟看来看去，只觉眼花缭乱，辨不明白。'),
    ('无以复加', '其便捷之法，殆无以复加。'),
    ('突如其来', '其在前曰：真为素昧平生，突如其来，难怪妾之得罪。'),
    ('名利双收', '其实名利双收，三百六十行生意，再没有强如做官的了。'),
    ('齐天大圣', '其实是主考的车子一过了卢沟桥，就送关节的送关节，交条子的交条子，一个个齐天大圣，大圣齐天了。'),
    ('不能自拔', '其既入世也，又复受此感染焉。虽有贤智，亦不能自拔。'),
    ('如日中天', '兹学始盛于欧洲，仅一百五十年以来，今则磅礴烁烁，如日中天。（清·梁启超《生计学学说沿革小史》）'),
    ('淋漓尽致', '再就让我说，我也没姐姐说的这等透彻，这等淋漓尽致。'),
    ('头头是道', '再看他后面讲那汽机的做法用法，头头是道，语语内行。'),
    ('树大招风', '再者树大招风，土地、山峦多了容易显眼，惹人反对。'),
    ('舍本逐末', '写文章只追求形式而不注重内容，那是舍本逐末。'),
    ('轻描淡写', '写文章该详的地方要详，不可轻描淡写。'),
    ('半壁江山', '军声壮，阵法多，半壁江山全仗我。'),
    ('单枪匹马', '冯寡妇大骂那些女人是熊包，自己单枪匹马，趁人们在街上歇晌的当儿，故意在大街上向村西头走。'),
    ('赫赫有名', '况且他罗家也是著名的盐商，不过近年稍为疲了点罢了，在外面还是赫赫有名的，怕没人知道么？'),
    ('鬼哭狼嚎', '况且宝玉才好了些，连我们也不敢说话，你反打的人鬼哭狼嚎的！'),
    ('装模作样', '冷酒冷粉冷汤，着咱如何近傍，百般装模作样，讪笑寒酸魍魉。'),
    ('碌碌无为', '几十年来，虽然不能说完全碌碌无为，但是回忆起进城之前，见到那些老战士时心里曾经涌起的感情。'),
    ('水涨船高', '几回事情一来，他晓得人家有仰仗他的地方，顿时水涨船高，架子亦就慢慢的大了起来。'),
    ('自作主张', '凡事总得回过他，就是多用些，也无话说，但不可自作主张。'),
    ('有利有弊', '凡事有利有弊，我们只须多加防范弊害的发生，不必因噎废食。'),
    ('平易近人', '凡昌黎（韩愈）与东野（孟郊）联句，必字字争胜，与他人联句，则平易近人。'),
    ('怨声载道', '凡有些余利的，一概入了官中，那时里外怨声载道，岂不失了你们这样人家的大体？'),
    ('损人利己', '凡有损人利己之心的人，其结果都不妙。'),
    ('哼哼唧唧', '凤姐姐带病哼哼唧唧的说……。'),
    ('借刀杀人', '凤姐虽恨秋桐，且喜借他先可发脱二姐，用借刀杀人之法。'),
    ('大有人在', '出面的虽是章士钊，其实黑幕中大有人在。'),
    ('人云亦云', '刊物内容如果只是“人云亦云”，格式如果只是“亦步亦趋”，那是刊物的尾巴主义。'),
    ('异想天开', '刑部书吏得了他的贿赂，便异想天开的设出一法来。'),
    ('一言一行', '则夫一言一行，传其人之神，何以异是。'),
    ('欢天喜地', '刚才二奶奶从老太太屋里出来，不似往日欢天喜地的，叫了平儿，唧唧咕咕的不知说了些什么。'),
    ('抛砖引玉', '刚才婢子费了唇舌，说了许多书名，原是抛砖引玉，以为借此长长见识，不意竟是如此！'),
    ('不了了之', '刚才的争论就这样不了了之。'),
    ('一鼓作气', '初听这话，还是一鼓作气的。'),
    ('春秋笔法', '初意却不过贪图少写一个字，并非有什么春秋笔法。'),
    ('尽心尽力', '利所当兴，弊所当革，尽心尽力。'),
    ('强人所难', '别强人所难了，他不会答应的。'),
    ('登峰造极', '到了清末，梁启超先生的“新文体”可算登峰造极。'),
    ('炉火纯青', '到了现在，可已到了炉火纯青的气候，正是弟兄们各显身手的时期。'),
    ('心安理得', '到后来忘却了真,相信了谎,也就心安理得,天趣盎然了起来。'),
    ('前仆后继', '前仆后继人应在，如君不愧轩辕孙！'),
    ('无懈可击', '前后不过四五个钟头。却也办得细密周到，无懈可击。'),
    ('衣食住行', '前后相继约两个世纪，衣食住行相互影响，极为显著。'),
    ('不期而遇', '前在公主府内，也是我们姐妹三十三个先会面；今日不期而遇，又是如此。'),
    ('前车之鉴', '前车之鉴，请自三思。'),
    ('来日方长', '前途似海，来日方长。'),
    ('先发制人', '剑波没等这位警长开口，便理直气壮地来个先发制人。'),
    ('源远流长', '剥削阶级的幸福观，是源远流长，影响仍然是相当深广的。'),
    ('老生常谈', '功名富贵无凭据，费尽心机，总把流光误。浊酒三杯沉醉去，水流花谢知何处？这一首词，也是个老生常谈。'),
    ('灭顶之灾', '动员了全国的老百姓，就造成了陷敌于灭顶之灾的汪洋大海。'),
    ('浑水摸鱼', '助纣为虐，他是不干的。浑水摸鱼，此其时也。'),
    ('一气呵成', '北曲之介白者每折不过数言，即抹去宾白而止阅填词，亦皆一气呵成，无有断续。'),
    ('倾家荡产', '匪徒们眼瞪着他们的大锅盔，倾家荡产。'),
    ('柳暗花明', '十二月十三日之晨，我心酸肠断，以为从此要尝些人生失望与悲哀的滋味，谁知眼前有这种柳暗花明的美景。'),
    ('津津乐道', '十余年来，在不少出版物中我都看到这幅画，它为不少人所津津乐道。'),
    ('无时无刻', '半个月来，她老是偷偷地看着剑波，她的心无时无刻不在恋着剑波，就好像是生活中不可缺少的空气一样。'),
    ('华而不实', '华而不实，脆而不坚。'),
    ('旗鼓相当', '单说何孝先自办此事以来，居然别开生路，与申大善士一帮旗鼓相当，彼此各不相干。'),
    ('得意洋洋', '单道台得意洋洋的答道：“忙虽忙，然而并不觉得其苦。”'),
    ('妄自菲薄', '单靠这几个人办不出什么大事。但对于自己，荪甫从来不肯“妄自菲薄”。'),
    ('花天酒地', '南京秦淮河一带仍是花天酒地，听歌狎妓。'),
    ('甜言蜜语', '卞福坐在旁边，甜言蜜语，劝了一回。'),
    ('忠心耿耿', '卢永祥见一个忠心耿耿的陈乐山忽然变了样子，还不晓是何缘故，十分诧异。'),
    ('一朝一夕', '即如今日中倭之构难，究所由来，夫岂一朝一夕之故也哉！'),
    ('不痛不痒', '即如小弟幼时，忽从面上生一肉核，非疮非疣，不痛不痒。'),
    ('推波助澜', '即或漏吞舟之鱼，而已暴鳃断鳍，颓然老矣，尚何能为推波助澜之事哉！'),
    ('曲曲折折', '即所谓《对张杨的训词》，内容含含糊糊，曲曲折折，实为中国政治文献中一篇有趣的文章。'),
    ('寸草不生', '却有八百里火焰，四周围寸草不生。'),
    ('一目了然', '却说这中堂正对着那个围场，四扇大窗洞开，场上的事，一目了然。'),
    ('狂风暴雨', '却遇了一阵狂风暴雨。'),
    ('令人发指', '历年以来，不知害了我们多少同志，说来真真令人发指。'),
    ('青山绿水', '历遍了青山绿水，看不尽野草闲花。'),
    ('成家立业', '原来廉锦枫曾祖向居岭南，因避南北朝之乱，逃至海外，就在君子国成家立业。'),
    ('血盆大口', '原来身后有个山羊在那里吃草，却被大虫看见，扑了过去，抱住山羊，张开血盆大口，羊头吃在腹内。'),
    ('唯利是图', '原来这黄祸居乡，唯利是图，无恶不作。'),
    ('不计其数', '去州桥河内周围上下点灯，不计其数。'),
    ('名列前茅', '去年弟在京师，听说二公子中了秀才，且名列前茅，颇为学台赏识，实在可贺可贺。'),
    ('名不副实', '县、区、乡各级民众政权是普遍地组织了，但是名不副实。'),
    ('触目惊心', '又因他姓赤，惟恐厕内倘有赤痢血痔之类，也好教他触目惊心，时常打扫：因此把他派了。'),
    ('窃窃私语', '又故意与行酒侍儿，窃窃私语，羋氏两次问话，俱失应答。'),
    ('心如刀割', '又李听说，心如刀割，顾不得任公在坐，竟是放声大哭。'),
    ('惊涛骇浪', '又觉得身体动荡，仿佛在惊涛骇浪的小船里。'),
    ('大功告成', '及大功告成，天下已定，而后实行其共和主义之政策，恢复我完全之金瓯。'),
    ('后起之秀', '及浪游南北，与乡里阔疏，后起之秀，不乏其人。'),
    ('身临其境', '及至身临其境，只落得“原来如此”四个大字。'),
    ('天官赐福', '反正得有个天，“天官赐福”，字又太多了。'),
    ('含糊其辞', '发表时候，为了避免反动政府检查，有的地方故意含糊其辞，现在把它们弄明确了。'),
    ('再接再厉', '取得好成绩也不能自满，要再接再厉，不断进取。'),
    ('畅通无阻', '取消路卡收费，路面交通畅通无阻。'),
    ('不远万里', '受加拿大共产党和美国共产党的派遣，不远万里，来到中国。'),
    ('受宠若惊', '受宠若惊，居亢无悔。'),
    ('有声有色', '叙得头头是道，已经不易，叙得有声有色，更难。'),
    ('独来独往', '古怪，独来独往，爱抬杠，你说东来他偏西。'),
    ('真情实感', '古老的神话，未必没有真情实感。'),
    ('诡计多端', '只为他诡计多端，生相凶恶，大家送他绰号，叫做李“鬼子”。'),
    ('伤天害理', '只为过于要做官，且急于要做大官，所以伤天害理的做到这样。'),
    ('克敌制胜', '只今番克敌制胜，便见得先生妙法。'),
    ('惊心动魄', '只听跑上几个人去，把椤子往地下一摔，霍绰的一声，惊心动魄。'),
    ('同归于尽', '只图自己安逸，那管世事艰难，弄到后来，不是同归于尽吗？'),
    ('别出心裁', '只好别出心裁，鼓吹女人自杀。'),
    ('有生之年', '只好用今后有生之年的辛勤努力，来补偿过去的不足。'),
    ('物是人非', '只怕再来时物是人非，云英已赴裴航之梦矣。'),
    ('难分难舍', '只是在不久以前，他被调到工程局担任总工程师的时候，两人才难分难舍地分了手。'),
    ('生老病死', '只是在家受不得那爱欲牵缠，生老病死，世态炎凉，人情险恶。'),
    ('招摇撞骗', '只是奴才们在外头招摇撞骗，闹出事来，我就耽不起。'),
    ('恰到好处', '只是平心静气的说，紧要关头却不放松一步；真所谓恰到好处。'),
    ('火眼金睛', '只是风搅得烟来，把一双眼炒红了，弄做个老害眼病，故唤作火眼金睛。'),
    ('闭口不谈', '只有一样，周炳觉得奇怪的，就是就是一提起卖到广州三家巷去的小妹妹胡杏，他们全就闭口不谈。'),
    ('以偏概全', '只有分析地阅读，才能学得深透，不致囫囵吞枣，一知半解；只有综合地阅读，才能学得完整系统，不致断章取义，以偏概全'),
    ('切身体会', '只有切身体会的经验才是真实而深刻的。'),
    ('回头是岸', '只要他们认破迷津，那便回头是岸。'),
    ('不偏不倚', '只要办理得人，不偏不倚，合乎中庸，一以国粹为归宿，那是决无流弊的。'),
    ('一丁点儿', '只要她能给我一丁点儿爱，我就心满意足了。'),
    ('扬眉吐气', '只要将来做了八府巡按，妈也就可以扬眉吐气了。'),
    ('理直气壮', '只要我们理直气壮，怕他怎的！'),
    ('有利可图', '只要政局上起点风潮，公债市场就受影响，我们做公债的就此有利可图了。'),
    ('金字招牌', '只要敬爱他的人，多发挥这一点，不要七手八脚，专门把他拖进自己所好的油或泥里去做金字招牌就好了。'),
    ('水深火热', '只要能把国家从水深火热里救出来，他就是至高无上的英雄。'),
    ('迎刃而解', '只要这位教士到场，任你事情如何棘手，亦无不迎刃而解的。'),
    ('横冲直撞', '只见三妖全身甲胄，横冲直撞，左右厮杀。'),
    ('接连不断', '只见人烟辏集，作买作卖，接连不断。'),
    ('纷纷扬扬', '只见四下彤云密布，又见纷纷扬扬，飞来一天瑞雪来。'),
    ('一言不发', '只见她一言不发，回手拔出那把刀来。'),
    ('大汗淋漓', '只见明珠身后跟着二十来个大胡子军官，有的黑胡子，有的白胡子，有的花白胡子，个个尘沙被面，大汗淋漓。'),
    ('咬牙切齿', '只见水军头领早把张清解来。众多兄弟都被他打伤，咬牙切齿，尽要来杀张清。'),
    ('来来往往', '只见街坊上来来往往，许多人挤在间壁一个庵院门首，尉迟南问土人为着何事。'),
    ('了如指掌', '只这一相形之下，美丑高低，便了如指掌了。'),
    ('唾手可得', '只除教呼延灼将军赚开城门唾手可得！'),
    ('细枝末节', '只须使其符合于总的抗战国策，而不必作细枝末节的限制，更不能随时解散。'),
    ('反复无常', '叫我怎么能赦你这反复无常的罪呢！'),
    ('防不胜防', '叭儿之类，是不足惧的，最可怕的确是口是心非的所谓“战友”，因为防不胜防。'),
    ('不由分说', '可是人们不由分说，还是狠狠地打了他一顿，还用马刀把所有的布袋都砍破了，把车子也劈掉了。'),
    ('大可不必', '可是你打算特约人来投稿，我以为大可不必。'),
    ('屡试不爽', '可是只要一见尼姑，这一天就不用赌啦，赌甚么输甚么，当真屡试不爽。'),
    ('无论如何', '可是她知道有你在，便推托身子不好，无论如何不肯来了。'),
    ('深入人心', '可是总没有这位先生的讲说那样一句句深入人心。'),
    ('三心二意', '可是眼下大敌当前，后有追兵，你可千万不要三心二意，迟疑不决，误了大事。'),
    ('勉为其难', '可是，情况尚不分明，我怎样迎敌？好吧，勉为其难吧。'),
    ('混为一谈', '可见“言志”跟“缘情”到底两样，是不能混为一谈的。'),
    ('无关紧要', '可见字音一道，乃读书人不可忽略的。大贤学问渊博，故视为无关紧要；我们后学，却是不可少的。'),
    ('误入歧途', '台湾的真情实况如何，不少人是误入歧途的，需要教育挽救。'),
    ('花花世界', '史见满园青翠萦目，红紫迎人，真是锦绣乾坤，花花世界。'),
    ('美中不足', '叹人间，美中不足今方信，纵然是齐眉举案，到底意难平。'),
    ('大街小巷', '吃了早饭，摇个串玲上行走去了，大街小巷乱走一气。'),
    ('引经据典', '吃到这些臭东西，还要替他考证，你也忒爱引经据典了。'),
    ('量力而行', '各位同学呢，大家量力而行，能捐多少就捐多少。'),
    ('人满为患', '各地监狱，都有人满为患之苦。'),
    ('千军万马', '各方面竟如千军万马地围困拢来，实在说，我是有被这班箭手底乱箭所射死的可能性的。'),
    ('各有所爱', '各有所爱，我们不要强求他这样。'),
    ('各行各业', '各行各业都出现新气象。'),
    ('趋利避害', '同什么人都可以打交道，在打交道的过程中趋利避害。'),
    ('耿耿于怀', '同学之间应团结互助，绝不能因一点小事就耿耿于怀。'),
    ('似是而非', '同学们的讲解，有的似是而非，有的简直错得可笑。'),
    ('三六九等', '同是拉车的，为什么有三六九等呢？'),
    ('跋山涉水', '同样的青春，同样的年龄，有人跋山涉水，为改变祖国一穷二白的面貌而感到莫大的幸福。'),
    ('同病相怜', '同病相怜，缀河上之悲曲。'),
    ('东西南北', '后以奔走四方，东西南北，驰驱少暇。'),
    ('费尽心思', '后儒牵强附会，费尽心思，不知都是古今学不分明的缘故。'),
    ('一来二去', '后来一来二去，渐渐的熟识。（清·石玉昆《三侠五义》第二十一回）'),
    ('沸沸扬扬', '后来听得沸沸扬扬地说：“黄泥冈上一伙贩枣的客人把蒙汗药麻翻了人，劫了生辰冈去。”'),
    ('无病呻吟', '后来的叹老嗟卑也正是无病呻吟。'),
    ('似笑非笑', '后来见的次数多了，大家似笑非笑，用以代替招呼。'),
    ('四书五经', '君子是只读四书五经，做八股，非常规矩的。'),
    ('以众击寡', '君尝以寡击众，取胜如神，况以强击弱，以众击寡乎？'),
    ('悲天悯人', '君生平绝口弗谈政治，独其悲天悯人之怀，流露于不自觉，有如此者。'),
    ('甘拜下风', '君神人也，吾等甘拜下风矣。'),
    ('万里长城', '吞珪既丧，坏了万里长城，国中精锐已尽，如何是好？'),
    ('哭笑不得', '否则咬着了辣椒，哭笑不得的时候，我不能负责。'),
    ('有条不紊', '听上去倒也是原原本本，有条不紊。'),
    ('不以为然', '听他说洋人不是，口虽不言，心下却老大不以为然。'),
    ('夜深人静', '听到月高初更后，果然弦索齐鸣。恰喜禁垣，夜深人静，琤璁齐应。（清·洪昇《长生殿·偷曲》）'),
    ('泪流满面', '听完这个故事，他已经泪流满面。'),
    ('对症下药', '吴晗《多写一点杂文》：“抓住问题，对症下药，是能够改进工作，提高工作效果的。”'),
    ('变幻莫测', '吾“红水阵”内夺壬癸之精，藏天乙之妙，变幻莫测。'),
    ('始终如一', '吾观关胜义气凛然，始终如一，军师不必多疑。'),
    ('细水长流', '告诉老王说，要多吃野菜树皮，少吃米面，细水长流呀！'),
    ('呕心沥血', '呕心沥血，讴歌社会主义，受到群众的欢迎。'),
    ('一事无成', '员乃投镜于地，痛哭曰：“一事无成，双鬓已斑，天乎，天乎！”'),
    ('价值连城', '周先生，此乃府上之宝，价值连城。'),
    ('决一死战', '周天爵素称勇敢，所保臧纡青练勇可当一面，独不能与贼决一死战耶？'),
    ('勃然大怒', '周瑜听罢，勃然大怒。'),
    ('见死不救', '周金大哥死在国民党军阀、官僚手里，你们见死不救。'),
    ('锦上添花', '命穷时镇日价河头卖水，运来时一朝的锦上添花。'),
    ('良师益友', '和一位缔交半个多世纪的良师益友诀别，悲痛之情是难以尽述的。'),
    ('天南海北', '和他在一起，觉得很自在，很安详，可以天南海北，无拘无束的聊天。'),
    ('舒舒服服', '和风吹拂，我舒舒服服地躺在草地上，十分惬意。'),
    ('天南地北', '咫尺的天南地北，霎时间月缺花飞。'),
    ('无话不谈', '咱们军中的老人，都是生死一心，在你面前无话不谈。'),
    ('自圆其说', '哈哈，单于殿下，你自己都不能自圆其说了吧。'),
    ('不亦乐乎', '哎，那骂得可真也是不亦乐乎。'),
    ('哗众取宠', '哗众取宠的人，是不受人欢迎的。'),
    ('从天而降', '哥哥，你真是从天而降也！万乞救我一救。'),
    ('当机立断', '哥哥，国姓爷就在城下，你应该当机立断。'),
    ('心照不宣', '哦，哦，那算是我多说了，你是老门槛，我们心照不宣，是不是！'),
    ('奇技淫巧', '哪一个肯化三块半洋钱去买这样奇技淫巧的东西。'),
    ('官僚主义', '哪怕是辛辛苦苦的官僚主义也好，哪怕是艰苦奋斗的命令主义也好，都在反对之列。'),
    ('说来说去', '唉说来说去。就是太不灵机，太死脑筋。'),
    ('文质彬彬', '唐敖看那尹玉生得文质彬彬，极其清秀。'),
    ('彬彬有礼', '唤出他两个儿子，兄先弟后，彬彬有礼。'),
    ('唯心主义', '唯心主义的观点难以苟同。'),
    ('如影随形', '善恶昭彰，如影随形。'),
    ('理所当然', '善者福而恶者祸，理所当然。'),
    ('东山再起', '回到家乡，先图个骨肉团聚，一面藏器待时，或者圣恩高厚，想起来还有东山再起之日，也未可知。'),
    ('饱餐一顿', '回到家后，我将饱餐一顿。'),
    ('百发百中', '回见子牙，叩头在地：“丞相妙计，百发百中。”'),
    ('声嘶力竭', '因为气愤，话虽然说的不很多，可是有点声嘶力竭的样子。'),
    ('招架不住', '因农民起来形势甚猛，地主阶级招架不住，其武装势力大部分投降农会。'),
    ('扬长避短', '因地制宜，扬长避短。'),
    ('聪明才智', '因思姊姊同妹妹，聪明才智岂输男。'),
    ('哄堂大笑', '因把在筱亭客厅上的事情，说了一遍。大家哄堂大笑。'),
    ('遥遥无期', '因此工作便十分迁延，武昌城的攻破遥遥无期。'),
    ('道貌岸然', '因看见端甫道貌岸然，不敢造次。'),
    ('雨后春笋', '国内废科举，兴学校，好像雨后春笋，努力学习西方。'),
    ('喜不自胜', '国太只道孙权好意，喜不自胜。'),
    ('臭名昭著', '国民党以臭名昭著的《危害民国紧急治罪法》控告这一群手无寸铁的青年‘颠覆政府’。'),
    ('两全其美', '土霸打倒，穷苦人见青天。不是两全其美！'),
    ('才疏学浅', '在下虽有此志，只是才疏学浅，年纪又轻，经练更少。'),
    ('慷慨激昂', '在东京聚首时，一谈到国事上来，总要谈得慷慨激昂，而且有点口角流沫。'),
    ('行尸走肉', '在他们的心目中，任何貌似强大的侵略者，都只不过是一群徒有虚表的行尸走肉而已。'),
    ('一穷二白', '在他们的意念中，一切都是为了迅速改变‘一穷二白’的面貌。'),
    ('不可逾越', '在他看来，上海的学生娃和山寨的青年之间，是有着一道不可逾越的鸿沟的。'),
    ('欣欣向荣', '在其间欣欣向荣的，只有鲜花和绿草，这是比喻对于将来的希望。'),
    ('犹豫不决', '在决定这件事如何处理时，他变得犹豫不决起来。'),
    ('生生不息', '在天地，则气化流行，生生不息。（清·戴震《孟子字义疏证·道》）'),
    ('郁郁寡欢', '在她给余永泽和王晓燕的信中充满了悲天悯人和郁郁寡欢的情绪。'),
    ('争先恐后', '在学校举行的运动会上，各班同学争先恐后，奋力争先。'),
    ('阿猫阿狗', '在德国无论阿猫阿狗见面，一律互相举手高喊：“希特勒万岁”。'),
    ('固步自封', '在成绩面前，我们不能骄傲自满，固步自封。'),
    ('虚情假意', '在我是虚情假意，你听了一样的难过。'),
    ('个人主义', '在某些党员中还存在着比较浓厚的个人主义和自私自利的思想意识。'),
    ('高高兴兴', '在气象一新、大家都满意、大家高高兴兴的情况下，工作好做。'),
    ('百无聊赖', '在百无聊赖中，随手抓过一本书来，科学也好，文学也好，横竖什么都一样。'),
    ('狗血淋头', '在联合国会议上，在板门店谈判中，被骂得狗血淋头，一句踊也无法回。'),
    ('微不足道', '在草花中我们虽然是微不足道。但我们的花色却算是紫色代表。'),
    ('作恶多端', '在载垣等，未尝不自恃为顾命大臣，纵使作恶多端，定邀宽典。'),
    ('你来我往', '在过去的岁月里，他其实只知道人和人之间存在着恩怨，恩恩怨怨，你来我往。'),
    ('求同存异', '在这个问题上，我们还是求同存异吧。'),
    ('春风得意', '在这些“伸手”派心目中，新社会也不过是一个猎场，可以任由他们在其中践踏一切，呼朋引类，春风得意，纵马狩猎。'),
    ('人来人往', '在这人来人往的地方没办法集中精力。'),
    ('勾心斗角', '在这件事上，他们最是赤祼祼地毫无勾心斗角的意思。'),
    ('一面之词', '在这件事情上，我们不能只听一面之词，必须全面了解情况，然后再做处理。'),
    ('世外桃源', '在这儿，在这世外桃源的仙境中，有了人世喧嚣的声音。'),
    ('四面楚歌', '在这四面楚歌里，凭你怎样伶牙俐齿，也只得服从了。'),
    ('大雪纷飞', '在这大雪纷飞的天气里，我们最好呆在屋子里。'),
    ('弱肉强食', '在这样“弱肉强食”的情况下，“生活”是终于不易保全的。'),
    ('无与伦比', '在这段时间里，他受到祖国人民无与伦比的最热情的接待。'),
    ('深山老林', '在这深山老林中怎么会有电话通信呢？'),
    ('好整以暇', '在这种人心惶惶的时候，珏斋却好整以暇，大有轻裘缓带的气象，只把军队移驻山海关。'),
    ('紧要关头', '在这紧要关头我们绝不能退却。'),
    ('各取所需', '在这里我们可以各取所需。'),
    ('风口浪尖', '在这风口浪尖上，我们要谨慎从事。'),
    ('心惊肉跳', '在那个闷热的夜晚，发生了那种淑娴现在想起还心惊肉跳的事情，使她的精神受到极大的创伤。'),
    ('民不聊生', '在那些年月，军阀混战，土匪横行，民不聊生。'),
    ('自愧不如', '在那地方，圣裔们繁殖得非常多，成着使释迦牟怪和苏格拉底都自愧不如的特权阶级。'),
    ('不务正业', '在那时候他们是被骂为不务正业的青年，但没人知道当时的社会已无青年们可务的正业。'),
    ('日日夜夜', '在重庆红岩的日日夜夜，你英勇斗争，临危不惧。'),
    ('此起彼伏', '在鼾声此起彼伏中，领导人自己独独醒着。'),
    ('长此以往', '坚卓者无不灭亡，游移者愈益堕落，长此以往，将使中国无一好人。'),
    ('生龙活虎', '城外元兵虽多，却被张世杰一马在前，宗仁、宗义在后，如生龙活虎一般，杀入阵去。'),
    ('特立独行', '士之特立独行，适于义而已。'),
    ('声势浩大', '声势浩大的游行队伍，迈着整齐的步伐向主席台走来。'),
    ('太平盛世', '复古的，避难的，无智愚贤不肖，似乎都已神往于三百年前的太平盛世，就是“暂时做稳了奴隶的时代”了。'),
    ('夕阳西下', '夕阳西下路途行，越岭经峰十里余。'),
    ('取长补短', '外来干部和本地干部各有长处，也各有短处，必须互相取长补短，才能有进步。'),
    ('错落有致', '外湖跟里湖从错落有致的枝叶间望去，似乎时刻在变换模样儿。'),
    ('乌合之众', '外边虽有些人，也是乌合之众，不相统摄。'),
    ('一片漆黑', '外面一片漆黑，请备好光源。'),
    ('滴滴答答', '外面传来滴滴答答的雨声，更加显得夜的宁静。'),
    ('空空如也', '多少只眼睛也都向王忠的座位搜寻的时候，却见这个小人儿的座位早已空空如也。'),
    ('深仇大恨', '多年积压的深仇大恨，象火山的岩浆一样从江水山的身上暴发了！'),
    ('刀光剑影', '多年阔别，一旦重逢尤其在此刀光剑影的北中国一隅聚首，使人发生无限的感喟。'),
    ('高姓大名', '多蒙恩公的美意，改日相谢。不知恩公高姓大名，贵府何处？'),
    ('天下无双', '夜半，有女子可年十五六，姿颜服饰，天下无双。'),
    ('源源不断', '夜间，官军打通了由智亭山通往龙驹寨的大道，所以从天亮起就有军粮源源不断地从龙驹寨向西运送。'),
    ('光明正大', '大仙是光明正大之人，就以他的诳语作真。'),
    ('干将莫邪', '大冶铸金，金岂踊跃自谓我为干将莫邪乎？（明·归有光《与顾懋俭》）'),
    ('痴心妄想', '大凡人不做指望，到也不在心上；一做指望，便痴心妄想，时刻难过。'),
    ('大千世界', '大千世界无奇不有，充满了矛盾。'),
    ('无可奈何', '大哥同杨太守来拿我，实是一毫不知，既被他连累，也无可奈何了。'),
    ('无地自容', '大娘搜捉以出。女乃指福唾骂，福渐汗无地自容。'),
    ('凶神恶煞', '大家一看见金四和那些凶神恶煞的家丁，就知道是怎么一回事了。'),
    ('难以启齿', '大家也都如此主张。难的是这话由谁去说？谁也难以启齿。'),
    ('纷纷议论', '大家就纷纷议论，以为尚未出兵，先就伤人，一定是凶多吉少。'),
    ('悲从中来', '大家联了此语，益觉悲从中来，泣不可抑。'),
    ('水土不服', '大抵此症，起于饮食失调，兼之水土不服，食积于小腹之中，凝滞不消，遂至生热，升至胸中，便觉饥饿。'),
    ('活蹦乱跳', '大水看到活蹦乱跳的艾和尚一眨眼的工夫，就死在敌人枪弹之下，心里一阵疼。'),
    ('多种多样', '大海里有多种多样的海洋生物。'),
    ('忍俊不禁', '大熊猫憨态可掬，小猴子顽皮可爱，使得周围的大人们忍俊不禁，孩子们更是笑得前仰后合。'),
    ('千千万万', '大爷，你可千千万万见了这二个人的面再商量走的话！'),
    ('深谋远虑', '大王深谋远虑，说得有理。'),
    ('不闻不问', '大约这里的环境，本非有利于病，而不能完全不闻不问，也是使病缠绵之道。'),
    ('诚心诚意', '大远的诚心诚意来了，岂有个不叫你见个真佛儿去的呢？'),
    ('于事无补', '大错已经铸成，你再责备他也于事无补。'),
    ('各奔东西', '大难当头，他们各奔东西。'),
    ('稀里哗啦', '大雨稀里哗啦地泼下来。'),
    ('无依无靠', '天啊！只道与你一竹竿到底，白头相守，那里说起半路上就抛撇了，遗下许多儿女，无依无靠。'),
    ('应运而生', '天地生人，除大仁大恶，余者皆无大异；若大仁者则应运而生，大恶者则应劫而生，运生世治，劫生世危。'),
    ('五彩缤纷', '天大亮了，多云的天空，布满了五彩缤纷的朝霞。'),
    ('晴空万里', '天气十分好，晴空万里。'),
    ('缩成一团', '天气格外寒冷，小狗冻得缩成一团。'),
    ('天长地久', '天长地久有时尽，此恨绵绵无绝期。'),
    ('不在话下', '太史之类，不过傀儡，其实是不在话下的。'),
    ('将心比心', '太尉不将心比心，小子待将计就计。'),
    ('全军覆没', '太监郭敬监军，诸将悉为所制，师无纪律，而宋濂朱冕全军覆没矣。'),
    ('同甘共苦', '夫耕于前，妻耘于后，同甘共苦，相敬如宾。'),
    ('冲锋陷阵', '头一晚醉得倒下马来，第二天照样冲锋陷阵。不能喝酒，还能当军人吗？'),
    ('兴风作浪', '头两天见姊夫同前任不对，他便于中兴风作浪，挑剔前任的帐房。'),
    ('地广人稀', '奈缘地广人稀，首尾不能救应。'),
    ('人去楼空', '女主人公孤零零地消失在凄清的寒夜里，那种人去楼空的惆怅感觉一直折磨着我。'),
    ('前程似锦', '女儿已经开始了真正属于自己的人生，她的面前前程似锦，任何人也无法改变这一轨道了。'),
    ('相见恨晚', '女界伟人，久震耳鼓，真相见恨晚了。'),
    ('后会有期', '女菩萨千万保重！我们后会有期，暂且失陪。'),
    ('一年到头', '她一年到头都不回家。'),
    ('二话没说', '她二话没说接着就干。'),
    ('娇生惯养', '她从小娇生惯养，什么事也不会干。'),
    ('干脆利落', '她办事一向都是干脆利落的。'),
    ('千篇一律', '她又开始说起千篇一律的恳求的话语来了。'),
    ('情不自禁', '她又情不自禁地放声哭了。'),
    ('女扮男装', '她喜欢女扮男装。'),
    ('毫无顾忌', '她对做错了这个零件毫无顾忌。'),
    ('不依不饶', '她对别人总是不依不饶的。'),
    ('会心一笑', '她对我报以会心一笑。'),
    ('蹦蹦跳跳', '她带来一个蹦蹦跳跳的女孩。'),
    ('若有若无', '她很清楚，他对她早已若有若无，不放在心上了。'),
    ('破涕为笑', '她很高兴地赞同这个计划，并且破涕为笑地说她有逃的办法。'),
    ('心地善良', '她心地善良，十分乐于助人。'),
    ('急于求成', '她怎样呢？还是那样急于求成，不甘寂寞吗？'),
    ('严严实实', '她把口袋捂得严严实实，深怕人抢走她的血汗钱。'),
    ('如此这般', '她拉我到角落里如此这般地交代如何对付。'),
    ('按捺不住', '她按捺不住喜悦的心情。'),
    ('哭哭啼啼', '她整天哭哭啼啼，不吃不喝。'),
    ('时时刻刻', '她时时刻刻都保持高度警惕。'),
    ('有情有义', '她是一个有情有义的人。'),
    ('一星半点', '她是个干净利索的人，家里让她收拾得连一星半点的灰尘都没有。'),
    ('轻手轻脚', '她是个文静的姑娘，干什么都轻手轻脚的。'),
    ('定时炸弹', '她是张汉安插在他们中间的定时炸弹。'),
    ('见多识广', '她是每天上街去买菜的，自然见多识广，知道这东西的时价。'),
    ('的的确确', '她是的的确确有话要对我讲，还是句对我生死攸关的话。'),
    ('刀枪不入', '她有刀枪不入的本事。'),
    ('可有可无', '她活了五十年，第一次感觉到自己还不是一个可有可无的人。'),
    ('大红大紫', '她现在是大红大紫的大明星。'),
    ('货真价实', '她现在要求再念一遍时的不笑倒是货真价实的热心。'),
    ('一举一动', '她的一举一动都象个多年的媳妇，麻利，老到，还带着点自得的劲儿。'),
    ('古里古怪', '她的脾气古里古怪。'),
    ('含糊不清', '她的话语表达含糊不清。'),
    ('走投无路', '她真是走投无路了，只好来求老主人。'),
    ('文不对题', '她睡梦中常说英语——有时文不对题的使人发笑。'),
    ('不可估量', '她给公司造成不可估量的损失。'),
    ('心神不宁', '她自己也惊讶为什么如此心神不宁，最后她自慰地想到：‘是因为等待慧来。’'),
    ('自惭形秽', '她自惭形秽般只呆在一个黑暗的角落里，不敢发一言。'),
    ('不好意思', '她被人夸得不好意思了。'),
    ('软弱无力', '她软弱无力地回答我们的问题。'),
    ('平平淡淡', '她过着平平淡淡的生活。'),
    ('自作多情', '她这样做是自作多情。'),
    ('循序渐进', '她通常是从一个角度写，而不是从几个角度写；还只是循序渐进地写，而不是错综交叉地写。'),
    ('热情洋溢', '她那热情洋溢的仪态一直萦绕在我眼前。'),
    ('隔三差五', '她隔三差五就与他吵架。'),
    ('自告奋勇', '好心的渔户自告奋勇，选拔了五十多名上等青年猎手，披弓带箭前去寻找。'),
    ('耳目一新', '如今一上船，便觉得另是一番风味，耳目一新。'),
    ('一无所有', '如今凤姐儿一无所有，贾琏外头债务满身。'),
    ('开花结果', '如今方下种，还没有发芽哩，再隔五六年，开花结果，才到你口。'),
    ('天下大乱', '如今朝廷不明，天下大乱，天子昏昧，奸臣弄权，我等归顺宋公明，且居水泊。'),
    ('不折不扣', '如今的妇人跟男人不折不扣一样尊贵！'),
    ('心服口服', '如今请出一个管得着的人来管一管，嫂子就心服口服，也知道规矩了。'),
    ('一笔勾销', '如有班部监司，不才官吏，一笔勾销，永不叙用。'),
    ('贪官污吏', '如有真正贪官污吏，破戒和尚，秽行道士，方许下击。'),
    ('弱不禁风', '如果不参加劳动，也就会沾上资产阶级的思想意识，而且弱不禁风。'),
    ('半途而废', '如果就此请假回国，这里的事半途而废，将来保举弄不到，白吃一趟辛苦。'),
    ('一脉相承', '如果我们再知道他们是好到如之问《祭杨盈川文》所说的那程度，我们便更能了然于王、杨与沈、宋所以是一脉相承之故。'),
    ('粉身碎骨', '如果战争狂人胆敢轻举妄动，发动战争，结果必然会被压在大山底下，弄得粉身碎骨。'),
    ('良心发现', '如此一想，自然闷恨，要哭了。姐姐，你说这宗忖度岂非良心发现么？'),
    ('前所未有', '如此好令，真是酒席宴前所未有的，妹子恭逢其盛，能不浮一大白。'),
    ('左思右想', '如此左思右想，一时五内沸然。'),
    ('覆水难收', '如此才人，足以快婚，尔女已是覆水难收，何不宛转成就了他。'),
    ('训练有素', '如此整齐严密，虽极迅猛激烈而丝毫不乱，足见训练有素，名不虚传。'),
    ('处心积虑', '如此者处心积虑，已非一日。'),
    ('不谋而合', '如磁石铁，不谋而合。'),
    ('事半功倍', '如能善用他的特长和经验，比较地容易获得事半功倍的效果。'),
    ('隐姓埋名', '如若答应下来，你只好隐姓埋名，从此再别想出头了。'),
    ('青红皂白', '妈妈和哥哥且别叫喊，消消停停的，就有个青红皂白了。'),
    ('道听途说', '妹子道听途说，不知是否？尚求指示。'),
    ('鲜血淋漓', '始缠之时，其女百般痛苦，抚足哀号，甚至皮腐肉败，鲜血淋漓。'),
    ('如释重负', '姐姐如释重负似的松了一口气。'),
    ('不遗余力', '委员和事，调停惟赖孔方；绅士责言，控诉不遗余力。'),
    ('委曲求全', '委曲求全的苟活决不是真正的生。'),
    ('自命不凡', '娄县沈童者，年甫冠，习帖括，自命不凡，有太阿出匣遽化长虹之概。'),
    ('高抬贵手', '娘是小的一个主儿，娘不高抬贵手，小的一时儿存站不的。'),
    ('如痴如醉', '子京，你怎么如痴如醉，做出这个嘴脸，想是青霞事又发作了。'),
    ('爱屋及乌', '子存宠上了小老婆，未免“爱屋及乌”，把他也看得同上客一般。'),
    ('无中生有', '子息从来天数，原非人力能为。最是无中生有，堪令耳目新奇。'),
    ('东倒西歪', '子期使侍卫阻之。熊宜僚用手一拉，侍卫东倒西歪，二人径入殿中。'),
    ('痴人说梦', '子牙笑曰：“邓将军，你这篇言词，真如痴人说梦。”'),
    ('改过自新', '子能改过自新，弃越归吴，寡人必当重用。'),
    ('高山流水', '孔圣人尚学琴于师襄，一操便知其为文王。高山流水，得遇知音。'),
    ('乐在其中', '孔子曰：‘乐在其中矣。’遂自号为‘随园’云。'),
    ('进退两难', '孔明曰：“既主公在涪关进退两难之际，亮不得不去。”'),
    ('出人头地', '孙俊英见人家看得起，能出人头地，一呼百应，好不威风自在。'),
    ('抓耳挠腮', '孙悟空在旁闻讲，喜得他抓耳挠腮，眉花眼笑。'),
    ('七十二变', '孙悟空有七十二变的本领，你比他更厉害。'),
    ('融会贯通', '孙犁《后记》：“这种激情，虽然基于作者当时迫切的抗日要求，但还没有多方面和广大群众的伟大的复杂的抗日生活融会贯通。”'),
    ('匪夷所思', '孙莱山入枢廷，是在意中，乌少云则匪夷所思了。'),
    ('远走高飞', '孙行者！好男子不可远走高飞！快向前与我交战三合。'),
    ('是是非非', '孝悌忠信，刚毅质直，笃于为义，勇予疾恶，是是非非，终身不假人以色词。'),
    ('周而复始', '季节的春夏秋冬，植物的生长荣枯，周而复始，年年如此。'),
    ('孤军奋战', '孤军奋战的艰苦局面带来了重重困难。'),
    ('生搬硬套', '学习不是生搬硬套，生活中的语言也不能原封不动地运用，需要提炼。'),
    ('相辅相成', '学习和复习，是用以掌握知识和巩固知识的两个方面，相辅相成，缺一不可。'),
    ('咬文嚼字', '学习文件不能只咬文嚼字，关键是领会文件的精神实质。'),
    ('学以致用', '学习科学文化知识要学以致用。'),
    ('持之以恒', '学习要锲而不舍，持之以恒，就能取得好成绩。'),
    ('点点滴滴', '学习要靠点点滴滴地积累。'),
    ('天经地义', '学好科学文化知识是每个学生天经地义的事。'),
    ('合情合理', '学校认为这个方案合情合理，就定为制度。'),
    ('热火朝天', '学校里已经闹得热火朝天了。'),
    ('图文并茂', '学生都喜欢图文并茂的课本。'),
    ('一如既往', '它一如既往，是一片蓬勃的繁忙景象。'),
    ('卿卿我我', '它们在春情发动期，雌的和雄的碰在一起，难免“卿卿我我”的来一阵。'),
    ('铺天盖地', '它把大沙丘一下子卷上天空，然后又铺天盖地地撒下来。'),
    ('面目全非', '它的厄运，是在好书被有权者用相似的本子来掉换，年深月久，弄得面目全非。'),
    ('一言以蔽', '宋·洪迈《容斋续笔》第12卷：“诗著靡他之誓，百代可知；礼垂不嫁之文，一言以蔽。”'),
    ('断章取义', '宋人攻击王介甫，说他将明妃写成一个不忠君不爱国的人，其实是断章取义，故入人罪。'),
    ('顺流而下', '宋子英便叫水手开船，水手们答应一声，抽起跳板把船拦开，点了一篙，那船便顺流而下。'),
    ('千变万化', '官场中的事，千变万化，那里说得定呢。'),
    ('信以为真', '宝玉又问他地名庄名，来往远近，坐落何方，刘老老便顺口诌了出来。宝玉信以为真。'),
    ('低声下气', '宝玉背地里拉着他，低声下气，要问黛玉的话，紫娟从没好话回答。'),
    ('豁然开朗', '宝玉豁然开朗笑道：“很是，很是。'),
    ('察言观色', '宝钗见此景况，察言观色，早知觉了七八分。'),
    ('风雨无阻', '宝钗说道：“一月只要两次就够了。拟定日期，风雨无阻。”'),
    ('男女平等', '实现婚姻自由，男女平等，使青年和儿童得到有益的学习。'),
    ('空中楼阁', '实者，就事敷陈，不假造作，有根有据之谓也；虚者，空中楼阁，随意构成，无影无形之谓也。'),
    ('循环往复', '实践、认识、再实践、再认识，这种形式，循环往复以至无穷，而实践和认识之每一循环的内容，都比较地进到了高一级的程度。'),
    ('漂漂亮亮', '家珍穿着水红的旗袍，手挽一个蓝底白花的包裹，漂漂亮亮地回来了。'),
    ('身败名裂', '家里破产了——我父亲因为地权的事打了官司，闹得身败名裂。'),
    ('浅显易懂', '宽严相济其政乃安，这本是浅显易懂的道理，可王士俊之流就偏要曲解，想以不孝之名加罪于朕。'),
    ('面面俱到', '宾馆服务周全，衣食住行面面俱到，令客人非常满意。'),
    ('微乎其微', '富庶的河套，是黄河所给的一点点它口里所吐出的，和被它所吞没的比较起来，真是微乎其微了。'),
    ('一无所知', '对于世界历史，他一无所知。'),
    ('雪中送炭', '对于他们，第一步需要还不是“锦上添花”，而是“雪中送炭”。'),
    ('不敢苟同', '对于你的观点，我不敢苟同。'),
    ('幸灾乐祸', '对于同学的缺点和错误，我们不应采取幸灾乐祸的态度。'),
    ('拉帮结派', '对于少数人在改革中抵制、怠工、失职渎职；乘机制造思想混乱，拉帮结派，进行非法组织活动……就要严肃处理。'),
    ('落落大方', '对于我们也是非常宽大的。还有他的夫人也落落大方。'),
    ('起死回生', '对于时人那虚弱的感情，这真有起死回生的力量。'),
    ('由浅入深', '对于社会方面，也都是一步又一步地由低级向高级发展，即由浅入深，由片面到更多的方面。'),
    ('一丝一毫', '对于精密零件的加工，不允许有一丝一毫的误差。'),
    ('知己知彼', '对付敌人，一定要知己知彼，才能百战百胜。'),
    ('突然袭击', '对同志不能搞突然袭击。'),
    ('至关重要', '对我大有用处的人，每个人都是‘至关重要’的。'),
    ('有所作为', '对这个问题，苏联是能够有所作为的。'),
    ('无理取闹', '对那些无理取闹的人，我们决不应该迁就。'),
    ('星星点点', '对面的山坡上点缀着星星点点的小花。'),
    ('无家可归', '寺僧见了他无了根蒂，渐渐怠慢，不肯相留。要回故乡，已此无家可归。'),
    ('后顾之忧', '将军为殿，寡人后顾之忧矣。'),
    ('满载而归', '将卫国府库，及民间存留金粟之类，劫掠一空，堕其城郭，满载而归。'),
    ('独当一面', '将来可以独当一面，只嫌功名心重些。'),
    ('干干净净', '将民众的言论、出版、集会、结社、思想、信仰和身体等项自由权利剥夺得干干净净。'),
    ('当之无愧', '尊翁一生，清慎勤三字，可当之无愧。'),
    ('一般见识', '小人也知那厮胡为，不与他一般见识。（明·施耐庵《水浒全传》第十四回）'),
    ('白头到老', '小娘半老之际，风波历尽，刚好遇到个老成的孤老，两下志同道合，收绳卷索，白头到老。'),
    ('永垂不朽', '小将军丹心忠义，为国捐躯，青史简篇，永垂不朽，亦不辜负将军教养之功。'),
    ('风花雪月', '小弟每常见前辈批语，有些风花雪月的字样，被那些后生们看不见，便要想到诗词歌赋那条路上去，便要坏了心术。'),
    ('小打小闹', '小打小闹是干不成大事的。'),
    ('千难万难', '小生来这里走一遭，千难万难。'),
    ('像模像样', '小镇到处都在盘算和议论着，怎样像模像样地给将军送行。'),
    ('灯红酒绿', '少数人过着灯红酒绿，醉生梦死的生活，人民不满。'),
    ('魂飞天外', '尤二姐露出脸来，胡君荣一见，早已魂飞天外，那里还能辨气色？'),
    ('争奇斗艳', '尤其令邓幺姑神往的，就是讲到成都一般大户人家的生活，以及妇女们争奇斗艳的打扮。'),
    ('知难而退', '尤其是因为在那一级里有三、四个“吵客”，弄得那位英文教员不得不知难而退。'),
    ('赤子之心', '尧、舜、禹、汤、周、孔，时刻以救民济世为心，所谓赤子之心，原不过是“不忍”二字。'),
    ('气势汹汹', '就在这时候，从门外闯进了一位气势汹汹中年农妇。'),
    ('堂堂正正', '就如那妒妇破坏人家，他却也有一番堂堂正正的道理说出来，可知道家也却被他破了。'),
    ('无伤大雅', '就是甜味，也各具特色，有些是蜜糖般甜，有些是在甜中略带一点轻微的，“无伤大雅”和酸味。'),
    ('大喝一声', '就是重重地给患病者一个刺激，向他们大喝一声，说：‘你有病呀！’使患者为之一惊，出一身汗，然后好好地叫他们治疗'),
    ('不自量力', '就说我们殿试都是侥幸名列上等，并非不自量力，何敢自不量力，妄自谈文。'),
    ('摇身一变', '就这样铁路总公司的第七次的股东大会摇身一变变成了川汉铁路的“保路同志会”。'),
    ('其乐融融', '尽管家人极力制造天伦之乐、其乐融融的氛围，蒋介石却怎么也笑不起来。'),
    ('不管不顾', '尽管有外人在，他还是不管不顾的撞进来了。'),
    ('过眼云烟', '尽道是用不尽的金银，享不完的福禄了，谁知过眼云烟，容易消歇。'),
    ('洋洋洒洒', '局面询问也用不着洋洋洒洒的大文章。'),
    ('挨家挨户', '居委会的同志们正在挨家挨户地发送灭鼠药。'),
    ('美不胜收', '展览馆里展出的各种工艺品琳琅满目，美不胜收。'),
