    ('实实在在', '我们需要实实在在干活的人。'),
    ('三顾茅庐', '我住着半间儿草舍，再谁承望三顾茅庐。'),
    ('三位一体', '我俩没儿没女，洁琼常来，可以说是三位一体，宛如一家'),
    ('昏昏沉沉', '我努力睁大眼睛，我昏昏沉沉地捱着时刻。'),
    ('丢三落四', '我劳力弱，没牲口没车，又不会操持，干活又爱丢三落四。'),
    ('不上不下', '我却总是既不安乐，也不灭亡地不上不下地生活下来，都不能副任何一面的期望。'),
    ('料事如神', '我又不能料事如神，除了硬挺之外，总不免要吃点小亏。'),
    ('实话实说', '我只不过实话实说罢了。'),
    ('自我安慰', '我只是自我安慰罢了。'),
    ('分门别类', '我只要现在的时务书，分门别类的便好。'),
    ('震撼人心', '我听到这震撼人心的消息时激动得快要流泪。'),
    ('苦口婆心', '我和龙济光苦口婆心的谈了十几点钟。'),
    ('说到做到', '我喜欢他说到做到的性格。'),
    ('拖拖拉拉', '我喜欢你这种拖拖拉拉的性格。'),
    ('斩钉截铁', '我喜欢那种斩钉截铁的作风。'),
    ('迷迷糊糊', '我喝酒之后头部一直是迷迷糊糊的。'),
    ('生机勃勃', '我国的第三产业生机勃勃，发展非常迅速。'),
    ('曲高和寡', '我在省城，只听人称赞靓云，从没有人说起逸云，可知道曲高和寡呢！'),
    ('断断续续', '我实在忍不住打断她断断续续的谈话。'),
    ('隐隐约约', '我对老家有隐隐约约的记忆。'),
    ('模模糊糊', '我对老家的印象一直是模模糊糊的。'),
    ('在天之灵', '我并非说，大家都须天天去痛哭流涕，以凭吊先烈的“在天之灵”，一年中有一天记住他们就可以了。'),
    ('白衣天使', '我很喜欢白衣天使。'),
    ('朴实无华', '我很欣赏他那朴实无华的性格。'),
    ('差强人意', '我得了这一封信，似乎还差强人意。'),
    ('痛哭流涕', '我怎能忍心告诉他，使这个老人痛哭流涕呢？'),
    ('索然无味', '我情愿做一回“文剪公”，因为事情和文章都有意思，太删节了怕会索然无味。'),
    ('门当户对', '我想他两家也就算门当户对了，一说去，自然成的；谁知他这会子来了，说不中用。'),
    ('传宗接代', '我想劝他讨个“小”，将来生个儿子也可以传宗接代。'),
    ('想方设法', '我想方设法也要办到。'),
    ('颠沛流离', '我所感到悲哀的，是有几个同我来的学生，至今还找不到学校进，还在颠沛流离。'),
    ('筋疲力尽', '我才逃到这里来，已经筋疲力尽了，还有什么办法呢？'),
    ('息事宁人', '我承认我是抱着“息事宁人”的苦衷来接受它的。'),
    ('清清楚楚', '我把帐目理得清清楚楚了。'),
    ('平安无事', '我把选书的九十几两银子给了他，才买回这个东西来，而今幸得平安无事。'),
    ('万念俱灰', '我明白自己会活不到多久了，霎时间万念俱灰，稍微感觉到死底恐怖。'),
    ('百感交集', '我是上一个世纪出生的人，能参加这样的盛会，百感交集，思绪万千。'),
    ('千真万确', '我是从何营长的小公馆里得来的。营长的姨太太已经避到县里去了。还是雇的王麻子的船，千真万确！'),
    ('举一反三', '我是凭着一卷《诗韵》学说话，倒可以有“举一反三”的效验。'),
    ('脱口而出', '我晓得你这个人向来是有口无心的，但也不可不拘什么话便脱口而出。'),
    ('格格不入', '我本不知“运动”的人，所以凡所讲演，多与该同盟格格不入。'),
    ('纸醉金迷', '我来到日本不久，听的不多，见的不广，但在五光十色、纸醉金迷的纷乱生活中，有些事物给我的刺激特别深。'),
    ('络绎不绝', '我梦里所到的地方，竟是一片康庄大道，马来车往，络绎不绝。'),
    ('每时每刻', '我每时每刻都在想你。'),
    ('毫不犹豫', '我毫不犹豫地跳了进来，就再也不去了。'),
    ('意思意思', '我派她给你意思意思。'),
    ('生儿育女', '我现在很想生儿育女。'),
    ('生生世世', '我生生世世忘不了这一刻的感觉。'),
    ('山清水秀', '我的家乡是个山清水秀的好地方。'),
    ('真刀真枪', '我的意思是大敌当前，民族危亡，一个热血男儿就应当真刀真枪地干，光搞这些意思不大！'),
    ('不劳而获', '我的目标是不满于杨，而因此而是为的举动，却也许被第三者收渔人之利，不劳而获。'),
    ('不屑一顾', '我的眼光是一直线，只看前面的，两旁和后方，悍都然不屑一顾了。'),
    ('唉声叹气', '我看你脸上一团私欲愁闷气色！这会子又唉声叹气，你那些还不足，还不自在？'),
    ('鬼鬼祟祟', '我看瑞贞这些日子是有点邪，鬼鬼祟祟，交些乱朋友。'),
    ('仔仔细细', '我瞅见史良仔仔细细地把小红花一个个嵌入上衣的扣眼，嵌好后还左右端详。'),
    ('祖祖辈辈', '我祖祖辈辈都是种地的。'),
    ('万丈深渊', '我突然有跌进万丈深渊的凄凉感觉。'),
    ('紧追不舍', '我紧追不舍，终于成为前三名。'),
    ('累死累活', '我累死累活还不是为了你。'),
    ('长途跋涉', '我背痛腰酸，真像经过了长途跋涉似的，我倦得厉害。'),
    ('赏善罚恶', '我能在大众面前，冠冕堂皇地阅看的，是《文昌帝君阴骘文图说》和《玉历钞传》，都画着冥冥之中赏善罚恶的故事。'),
    ('身家性命', '我若没有还他，这件事就要破！身家性命关系，我所以和老哥商议。（清·吴敬梓《儒林外史》第三十二回）'),
    ('晕头转向', '我被你整得晕头转向。'),
    ('人情世故', '我说你到底没有经练，所以这些人情世故一点也不懂。'),
    ('没心没肺', '我说你怎么这么没心没肺的！'),
    ('果不其然', '我说姑老爷今非昔比，少不得有人把银子送上门去给他用，只怕姑老爷还不稀罕哩，今日果不其然。'),
    ('为非作歹', '我说的是好话，不过叫你心里留神，并没叫你去为非作歹。'),
    ('胡搅蛮缠', '我说的正经话，你不听，胡搅蛮缠的说了这些闲篇儿，谁来听你。'),
    ('大江南北', '我谈起买如意的事，他说有一支很别致的，只怕大江南北的玉器店，找不出一个来。'),
    ('意想不到', '我走进房间，看见意想不到的景象。'),
    ('波涛汹涌', '我跟着书本活了那么长的时间。我的心仿佛落在一个波涛汹涌的海上受着颠簸。'),
    ('茅塞顿开', '我身无力，我腹无才，得三公之教，茅塞顿开。'),
    ('蒙在鼓里', '我还蒙在鼓里，对此时一无所知。'),
    ('冰清玉洁', '我这一去冰清玉洁，干事回还，管着你们喝采他。'),
    ('自寻烦恼', '我这是自寻烦恼。'),
    ('无价之宝', '我这珠衣是无价之宝哩。'),
    ('清清白白', '我这辈子一向都是清清白白的。'),
    ('不顾一切', '我闭上眼睛，不顾一切的向着他手里的刀迎上去。'),
    ('调兵遣将', '我闻得海上倭贼利害，自去厮杀不成？只是调兵遣将，罚罪赏功而已。'),
    ('养家糊口', '我高兴极了，从此我就和大人一样当了工人，等我挣了工钱，就可以帮助养家糊口啦！'),
    ('矫枉过正', '或有避其谤者，又每矫枉过正，至坐视儿女之放纵，而不一置问。'),
    ('胡作非为', '或诬好吃懒做，或诬胡作非为。'),
    ('分崩离析', '战争使全国分崩离析的局面变成了比较团结的局面。'),
    ('摇摇欲坠', '战士们靠近边缘向下一看，头晕目眩，觉得眼前的大岩来回晃动，自己的身体摇摇欲坠。'),
    ('回光返照', '所以唐末宋初，骈体文又回光返照了一下。'),
    ('一落千丈', '所以喜奎一嫁，转瞬坤伶声势，一落千丈，伶界牛耳，又让男伶夺去。'),
    ('一心一意', '所以彭官保便一心一意的料理防守事宜，庄制军便一心一意料理军需器械。'),
    ('随随便便', '所以我们讲‘五十年’，不是随随便便、感情冲动而讲的，是考虑到中国的现实和发展的需要。'),
    ('绞尽脑汁', '所以绞尽脑汁也想不到战略、战术和个人应当如何参加战斗。'),
    ('无忧无虑', '所以虽没有在家里自在，我也算是无忧无虑的过着了。'),
    ('引以为戒', '所以近七八年来，历任巡抚者引以为戒，不敢委他事情。'),
    ('粗制滥造', '所谓爱工，就是粗制滥造，不管质量的恶劣。'),
    ('引人入胜', '扇画小幅，苏州园林，格局很小，却总是那么引人入胜。'),
    ('出人意料', '才貌却相当，缘合未堪奇赏，出人意料，在那错联鸾凰。'),
    ('闻风丧胆', '打得敌人闻风丧胆，弃尸累累。'),
    ('打成一片', '扬弃知识阶级的绅士身分，提高大众的鉴赏水准，这样打成一片，平民化，大众化。'),
    ('今生今世', '扰了这一家人家，今生今世还不的他，来生来世是必填还他则个。'),
    ('打抱不平', '扶正义，打抱不平，正是我们革命党我的本色。'),
    ('事倍功半', '把这民间事业整顿得件件整齐，桩桩发达，这岂不是事倍功半吗？'),
    ('神出鬼没', '抗日游击队神出鬼没，打得日本鬼子魂飞魄散。'),
    ('心心相印', '抚台看了，彼此心心相印，断无驳回之理。'),
    ('不容置疑', '报告的内容与群众反映的情况一致，不容置疑。'),
    ('真真假假', '报纸上真真假假的娱乐新闻实在不值得一读。'),
    ('担惊受怕', '担惊受怕的一晚，就是我生平最甜蜜的一天。'),
    ('夺眶而出', '拿手背擦擦夺眶而出的眼泪，接着他就疯子一样冲向李扯火去。'),
    ('力不从心', '按我的政治思想水平、斗争阅历和知识能力，担当编选陈毅同志诗词的工作确是力不从心。'),
    ('天壤之别', '按照一般人的生理机能来说，聪明与不聪明虽有差别，但并不存在天壤之别。'),
    ('答非所问', '按照着次序一问一答，没有答非所问的弊病，就算情意格外浓厚。'),
    ('挑拨离间', '挑拨离间的人，有着不可告人的目的。'),
    ('得心应手', '挟了七八万现款的冯云卿就此走进了公债市场，半年来总算得心应手，扯起息来，二分半是有的。'),
    ('背水一战', '挫折也有两重性。它可以把人置于死地，也可能使人置于死地而后生。他只有背水一战了。'),
    ('前因后果', '振德说完前因后果，深叹一声。'),
    ('七情六欲', '捐去三纲五常，绝去七情六欲，费其半菽，如失金珠，拔其一毛，有关痛痒。'),
    ('小道消息', '据小道消息说，这病还要持续一段时间。'),
    ('足不出户', '据我个人的经验，我们那里的土话，和苏州很不同，但一部《海上花列传》，却教我“足不出户”懂了白。'),
    ('蠢蠢欲动', '据点里的敌人又蠢蠢欲动。'),
    ('顺手牵羊', '据说座山雕的部下有个顺手牵羊的老方子，一撮毛可能是想施展这个伎俩。'),
    ('狼狈不堪', '掌声如翻腾的怒海汹涌的扑向台上去，弄得这些丑类面红耳赤，狼狈不堪。'),
    ('物美价廉', '提倡物美价廉，老少无欺，反对粗制滥造，偷工减料。 ◎朱德《要把手工业生产合作社搞好》'),
    ('大步流星', '提着灯笼的生宝在天亮前开始结霜的牛车路上，大步流星地向南走去。'),
    ('牵强附会', '揣古希腊哲人，似不无微知此意者，而厥后则牵强附会之说大行。'),
    ('屡见不鲜', '搜身的纠葛，在香港屡见不鲜。'),
    ('摇头晃脑', '摇头晃脑的读起来，真是音调铿锵，使人不自觉其头晕。'),
    ('大呼小叫', '擎火把的都是年轻的农民，另一只手提着枪，也有拿镐的，大呼小叫的嚷嚷着。'),
    ('崇洋媚外', '改革开发绝不是崇洋媚外。'),
    ('天翻地覆', '改革开放以来，我国农村发生了天翻地覆的变化。'),
    ('自力更生', '放在自己力量的基础上，叫做自力更生。'),
    ('诗情画意', '放棹西湖发浩歌，诗情画意两如何。'),
    ('一丝不挂', '放闸老兵殊耐冷，一丝不挂下冰滩。'),
    ('无关痛痒', '政府当初虽只不理那些招人头痛的教员，后来竟不理到无关痛痒的官吏。'),
    ('朝令夕改', '政策要力求相对地稳定，不能朝令夕改。'),
    ('四分五裂', '故其端起于大夫士之怙私，而其祸可至于亡国灭种，四分五裂，而不可收拾。'),
    ('五光十色', '故宫珍宝馆的玻璃柜里，摆着五光十色的稀世奇珍。'),
    ('七嘴八舌', '故晋大夫七嘴八舌，冷讥热嘲，皆由于心之大公也。'),
    ('偷偷摸摸', '敌人汉奸派遣反革命特务分子偷偷摸摸地钻入共产党、八路军、新四军内施行破坏工作。'),
    ('节节败退', '敌人节节败退，我军节节胜利。'),
    ('连滚带爬', '敌人被打得连滚带爬地逃回去了。'),
    ('居高临下', '敌居高临下，我战地不利。'),
    ('杂乱无章', '救火车开不进狭窄的弄。水桶拿不出许多。往来取水只是杂乱无章的一阵胡闹。'),
    ('如此而已', '教吾子与汝子，幸其成长，吾女与汝女，待其嫁，如此而已。'),
    ('日新月异', '教授之术，亦采法列强，教科之书，日新月异。'),
    ('不屈不挠', '教皇捉了他回，他在堂上不屈不挠，定归开出信教自由的理数。'),
    ('身心健康', '教育要注意到孩子们的身心健康。'),
    ('万紫千红', '整个文坛出现了前所未有的百花齐放、万紫千红的大好局面。'),
    ('行之有效', '整风是在我们历史上行之有效的办法。'),
    ('文人墨客', '文人墨客大概是感性太锐敏了之故罢，向来就很娇气，什么也给他说不得，见不得，听不得，想不得。'),
    ('似曾相识', '文淑忽然惊喜地想到，她看见了一张似曾相识的黑黑的脸。'),
    ('子虚乌有', '文贵征实，不蕲于振奇，所以愧文士子虚乌有之习也。'),
    ('滔滔不绝', '斡离不得汪豹献了李刘隘口，无人阻当，滔滔不绝，把十万大兵尽数渡了黄河。'),
    ('冷酷无情', '斤澜反映现实生活，有时像不是用笔，而是用解剖刀。在给人以深刻感的同时，也带来一些冷酷无情的压抑感。'),
    ('斩草除根', '斩草除根，萌芽不发；斩草若不除根，春至萌芽再发。'),
    ('变本加厉', '断句取义是在一句两句里拉出一个两个字来发挥，比起断章取义，真是变本加厉了。'),
    ('一塌糊涂', '新开设的中学，更是一塌糊涂，笑话百出。'),
    ('十全十美', '新生事物在刚产生时，并不都是十全十美，但总是不断发展壮大，最终是要取代旧事物的。'),
    ('自生自灭', '新生事物，如不关心和培育，就只能是自生自灭。'),
    ('绝无仅有', '新的一辈继他们的父亲或者母亲之后成为作家的，可以说绝无仅有。'),
    ('纸上谈兵', '新近有个大挑知县上了一个条陈，其中有些话都是窒碍难行，毕竟书生之见，全是纸上谈兵。'),
    ('凹凸不平', '方志敏《我从事革命斗争的略述》：“道路是凹凸不平的，柴屑粪渣，零零散散地散布在路上。”'),
    ('身经百战', '方才要说的，正是梁朝中一员虎将，姓葛名周，生来胸襟海阔，志量山高；力敌万夫，身经百战。'),
    ('秋高气爽', '方拟秋高气爽，遣将西征。'),
    ('一声不吭', '方方一声不吭地从人群中挤上来，用手里的砖朝这孩子的颅顶使劲一拍。'),
    ('难兄难弟', '方玉桦一言未发，但看得出她也有点激动，她显然记起他们是一九五七年的难兄难弟。'),
    ('言不由衷', '旋复下一通令，洋洋洒洒，约一二千言，小子因他言不由衷，不愿详录。'),
    ('冲口而出', '无如他此时是满怀的遂心快意，满面的吐气扬眉，话挤话不由得冲口而出。'),
    ('孤注一掷', '无如他被全台的公愤逼迫得没有回旋余地，只好挺身而出，作孤注一掷了。'),
    ('人心惶惶', '无端起来胡闹，蒌喊一阵，西跑一阵，弄得人心惶惶，不是扰乱治安是什么？'),
    ('萎靡不振', '无精打采地喘了一口粗气，然后象个病人一样萎靡不振地站在那里。'),
    ('息息相关', '无线电网繁密而敏捷，世界的每一角落息息相关，真是个“天下一家”。'),
    ('弄虚作假', '无论做什么事都应该实事求是，不该弄虚作假。'),
    ('妻离子散', '无辜人民之死伤成千累万，妻离子散啼饥号寒者到处皆是。'),
    ('患得患失', '既无“患得患失”的念头，心情也自然安泰，决非欲“骗人安心，所以这样说”的：切祈明鉴为幸。'),
    ('无稽之谈', '既无其说，是为无稽之谈。'),
    ('与世无争', '既然人家同我不对，我也乐得与世无争，回家享用。'),
    ('一拍即合', '既然我们一拍即合，所见略同，我也不瞒你。'),
    ('显而易见', '日本帝国主义和中国讨伐派的失望，已显而易见。'),
    ('大江东去', '早被我们伟大的党所领导的中国人民的巨掌击退，如大江东去，永不复返了。'),
    ('正人君子', '旬这样的才是斯文骨肉朋友，有意气，有肝胆，相与了这样正人君子，也不枉了。'),
    ('三三两两', '时文林街一带已有歪戴呢帽的人三三两两散在街上。'),
    ('时过境迁', '时过境迁，色衰爱驰，我对它们也失去了兴趣。'),
    ('变化多端', '明·冯梦龙《古今小说·陈从善梅岭失浑家》：“这齐天大圣神通广大，变化多端。”'),
    ('枝繁叶茂', '昔日的小树林现在已经是枝繁叶茂了。'),
    ('一年一度', '昔日繁华人羡我，一年一度易蹉跎。'),
    ('生不逢时', '昔汉文帝不知魏尚贤而囚之，知李广才而不用，乃叹其生不逢时。'),
    ('春去秋来', '春去秋来，他觉得自己真的老了。'),
    ('漫山遍野', '春天来了，漫山遍野都披上了绿装。'),
    ('繁花似锦', '春天的世博园，繁花似锦，五彩缤纷。'),
    ('春暖花开', '春暖花开，我好引着孩子们园里做活。'),
    ('心中有数', '春玲要先同儒春谈一次，摸摸他的底，心中有数，为她去和老东山交锋做准备。'),
    ('丰富多彩', '春节期间的文艺节目丰富多彩。'),
    ('指日可待', '是以我主上神佑，泥马渡江，正位金陵，用贤任能，中兴指日可待。'),
    ('风和日丽', '是时风和日丽，遍地金黄，青衫红袖，越阡度陌，蝶蜂乱飞，令人不饮自醉。'),
    ('盖世英雄', '是盖世英雄，始信短如春梦。'),
    ('依依不舍', '晚会结束已经大半天了，同学们才依依不舍地离去。'),
    ('国家大事', '普通一般学者，只在书斋里打圈子，对于国家大事则不闻不问。'),
    ('暴饮暴食', '暴饮暴食对人身体不利。'),
    ('叹为观止', '更佐以乐音灯影，光怪陆离，不可逼视。生抚掌称奇，叹为观止。'),
    ('乐此不疲', '更兼这位老先生，天生又是无论什么疑难，每问必知，据知而答，无答不即详且尽，并且乐此不疲。'),
    ('牛鬼蛇神', '更有一种可笑的，肚子里原没有什么，东拉西扯，弄得牛鬼蛇神，还自以为奥博。'),
    ('滚瓜烂熟', '曹寅从小对唐诗就背得滚瓜烂熟。'),
    ('得天独厚', '曹沾进园，草草看了，便觉这“南园”得天独厚，就在它有一片好水。'),
    ('曾几何时', '曾几何时，他自己去做了一个小小的官儿回来，而他又劝我去学法政了。'),
    ('事无巨细', '曾未期月，援溺振渴，事无巨细，悉究本末。'),
    ('指指点点', '曾朴《孽海花》第33回：“看那老番，正望着怒瀑的两岬间，指指点点地给徐骧讲话。”'),
    ('九泉之下', '替你孩儿，尽养生送死之礼，我便九泉之下，可也瞑目。'),
    ('发扬光大', '最合理的孝道恐怕是继承父辈的成就，把它发扬光大，好教下一辈得到更好的精神的与物质的遗产。'),
    ('穷凶极恶', '最后侯殿坤穷凶极恶，提起嗓子宣布：“谁也不准埋，谁埋与共产党同罪。”'),
    ('若有所思', '月光下，他默默地站在太湖石旁，若有所思。'),
    ('国泰民安', '有一天，沟不臭，水又清，国泰民安享太平。'),
    ('嫉恶如仇', '有万的绝对公正、嫉恶如仇、见公共事一马当先，使得生宝感到互助组有这个人。'),
    ('赴汤蹈火', '有三个人，义胆包身，武艺出众，敢赴汤蹈火，同死同生。'),
    ('全心全意', '有了这样的勇气才能够做到全心全意为人民服务。'),
    ('随时随地', '有人向他建议：多招募民间乡勇，分散在宁波、镇海、定海附近，随时随地以小队水陆分扰乱人。'),
    ('自欺欺人', '有人说中国的实业就会借此促进，那是自欺欺人之谈。'),
    ('一厢情愿', '有人说：‘你这是一厢情愿，石敢同意去吗？’'),
    ('心心念念', '有人遇一事，则心心念念不肯舍，毕竟何益？'),
    ('千差万别', '有什么大画家能区别这千差万别的绿和红么？'),
    ('风平浪静', '有孩儿在这里，不要怕他，包管风平浪静。'),
    ('杯水车薪', '有新债未动毫分的，除了承许夏鼎三十两外，大有杯水车薪之状。'),
    ('一文不值', '有时说自己的作文的根柢全是同情，有时将校对者骂得一文不值。'),
    ('有朝一日', '有朝一日，我出矛庐指点世人迷，凭着我剑挥星斗，我志逐风雷。'),
    ('说三道四', '有的人工作不努力，别人有了成绩，却整天说三道四。'),
    ('挺身而出', '有的挺身而出，被关在拘押所里。'),
    ('高高在上', '有着理智的青年朋友们眼看部长高高在上，“三青团”爪牙虎视眈眈，也只有沉默装傻而已。'),
    ('延年益寿', '服肉芝延年益寿。'),
    ('灵丹妙药', '望大圣爷爷早发灵丹妙药打救。'),
    ('一臂之力', '望孔明助一臂之力，同破曹贼。'),
    ('家破人亡', '朱家从朱老巩气死，朱老忠的姐姐跳河自尽，朱老忠只身闯关东，闯得家破人亡。'),
    ('义无反顾', '朱成功身受大明的厚恩，只有一死图报，义无反顾。'),
    ('蛛丝马迹', '机敏的公安人员根据现场的蛛丝马迹，很快找到了作案人的线索。'),
    ('一命呜呼', '杀两个叫花子开张！这两个叫花子就是这样一命呜呼了。 ★毛泽东《湖南农民运动考察报告》'),
    ('赶尽杀绝', '杀戮是对待他们的最简截的办法，正如同要消灭蝗灾只有去赶尽杀绝了蝗虫。'),
    ('翻山越岭', '李准《马小翠的故事》：“想贴个春联，往往要跑几十里，翻山越岭到山下请人写。”'),
    ('垂头丧气', '李德才一口回绝说情的事，运涛垂头丧气走出来。'),
    ('若隐若现', '李惊，方将诘问，则见其若隐若现，恍惚如烟雾，宛转间已登榻。'),
    ('忍气吞声', '李瓶儿这边分明听见指骂的是他，把两只手气的冰冷，忍气吞声，敢怒而不敢言。'),
    ('心急如焚', '李自成心急如焚，只觉得树木伐得太慢。'),
    ('胡思乱想', '杏莉母亲正在胡思乱想之际，听到有人敲门，高兴极了！'),
    ('信口开河', '村老老是信口开河，情哥哥偏寻根究底。'),
    ('小心谨慎', '杜兴到此多时，小心谨慎。'),
    ('二话不说', '来到岸边，二话不说，驾起船，直奔河心。'),
    ('低人一等', '来自农村的孩子不要有低人一等的想法。'),
    ('问心无愧', '林冲那时候却觉得在“刀枪无情”的理由下伤害了那汉子的生命，原是冠冕堂皇，问心无愧。'),
    ('有说有笑', '林边场园里，晒豆子的，打芝麻的，剥包米的，到处有说有笑，是一派热闹的丰收景象。'),
    ('无所适从', '某书应读某音，敝处未得高明指教，往往读错，以致后学无所适从。'),
    ('孤陋寡闻', '某孤陋寡闻，不足当公之荐。'),
    ('后会无期', '某旦夕南迁，后会无期，不能无怅惘也。'),
    ('天下无敌', '某闻许都曹操，扫荡中原，吕布、二袁皆为所灭，近又破马超，天下无敌矣。'),
    ('高谈阔论', '柴进高谈阔论，一片言语，娄敏中大喜，就留柴进在相府管待。'),
    ('一帆风顺', '栉霜沐露多劳顿，喜借得一帆风顺。'),
    ('顾名思义', '桂花蝉顾名思义，想是香味如桂花，或因桂花开时乃有，未详。'),
    ('必经之路', '桥北有八角碑亭，乃去来必经之路。'),
    ('一腔热血', '梁启超《新罗马·楔子》：“老夫生当数百年前，抱此一腔热血，楚囚对泣。”'),
    ('束手无策', '梅飏仁正在束手无策的时候，听了师爷的话说甚是中听，立刻照办。'),
    ('砸锅卖铁', '欠你的账，即使砸锅卖铁我也要给你还上。'),
    ('大摇大摆', '次日早晨，大摇大摆出堂，将回子发落了。'),
    ('年少无知', '欧阳那个人，据我看，是个年少无知的流氓。'),
    ('千钧一发', '正在千钧一发的时刻，一位不知名的解放军战士奋不顾身跳进冰冷的河水中，救起了落水儿童。'),
    ('雪上加霜', '正在惊慌，偏又转了迎面大风，真是雪上加霜。'),
    ('皆大欢喜', '正在皆大欢喜间，忽然太后密诏了清帝的本生父贤王来宫。'),
    ('鹤立鸡群', '正在谈论，谁知女儿国王忽见林之洋杂在众人中，如鹤立鸡群一般。'),
    ('惊喜交集', '正在这里，夫妻不期而遇，惊喜交集。'),
    ('手足无措', '正忧疑不定，忽报宋兵到了，惊得手足无措。'),
    ('鬼使神差', '正是呢，这是一高兴起灶，鬼使神差来了这些人。'),
    ('无出其右', '此二方专治一切肿毒，初起者速服速消，已溃者亦能败毒收口，大约古人痈疽各方，无出其右了。'),
    ('忘恩负义', '此人好夸大，且忘恩负义，你要仔细识他才好。'),
    ('文武双全', '此人姓姜，名维，字伯约，天水冀人也；事母至孝，文武双全，智勇足备，真当世之英杰也。'),
    ('不拘小节', '此人廓达之才，不拘小节。'),
    ('念念不忘', '此吾所以感刻于心，而念念不忘者也。'),
    ('同流合污', '此数贼者，同流合污，败坏国政。'),
    ('兵荒马乱', '此时四处兵荒马乱，朝秦暮楚，我勉强做了一部《旧唐书》，那里还有闲情逸致弄这笔墨。”'),
    ('首屈一指', '此校确系美国之首屈一指，我毕业于此后，纵欲继续研究，在此邦亦无处可去也。'),
    ('萍水相逢', '此生平第二知心交也。惜萍水相逢，聚首无多日耳。'),
    ('崭露头角', '此番吴氏北返，独倡保定会议，无非欲崭露头角，力与段派抗衡。'),
    ('厚颜无耻', '此种自私自利完全蔑视国家利益之理由，北平各团体竟敢说出，吾人殊服其厚颜无耻。'),
    ('伤筋动骨', '此等结束甚妙，生旦相见不十分吃力，相会亦不曾吃力，到底不曾伤筋动骨。'),
    ('相依为命', '死而复生的只有这些杂乱的败草。永逝不返的却是我们相依为命的慈母。'),
    ('焦头烂额', '殡焰飞腾，众水手被火烧得焦头烂额。'),
    ('众志成城', '段祺瑞既得国务员同情，便以为众志成城，正可一战。'),
    ('目瞪口呆', '殷、雷二将见众官激变，不复朝仪，吓得目瞪口呆，不知所出。'),
    ('夜以继日', '殷之季君，亦奏斯乐。酒池肉林，夜以继日。'),
    ('心如刀绞', '殷郊又见殷洪，心如刀绞，意似油煎。'),
    ('小心翼翼', '母亲小心翼翼地起床做饭，心里欣喜地想，让儿子多睡一会，不要惊醒他。'),
    ('大惑不解', '母疑涉妄，然窥女无他，大惑不解。'),
    ('英雄本色', '母舅虽系绿林聚义，山寨生涯，然须保善锄强，不愧英雄本色。'),
    ('游山玩水', '每与源游山玩水，吊古寻幽，赏月吟风，怡情遣兴，诗赋文词，山川殆遍。'),
    ('死皮赖脸', '每个人都应有自尊心人家不给你，你不要死皮赖脸地去要。'),
    ('乔装改扮', '每个国家都应严防他国乔装改扮的间谍与特务分子的渗透。'),
    ('缺一不可', '每个学生都要德智体全面发展，三者缺一不可。'),
    ('无计可施', '每个干部如果都能做到清正廉洁，行贿者也就无计可施了。'),
    ('千家万户', '每生出一个儿子都要封一个王，就有千家万户倾家破产，妻离子散，受不尽的糟践。'),
    ('尽善尽美', '比亦有人说足下诚尽善尽美。'),
    ('轰轰烈烈', '比前番在梁山泊上更觉轰轰烈烈，做出惊天动地的事业来。'),
    ('惊天动地', '比前番在梁山泊上更觉轰轰烈烈，做出惊天动地的事业来，功垂竹帛，世享荣华。'),
    ('胸有成竹', '毛委员胸有成竹，决定马上向南去追赶部队。'),
    ('完完全全', '毛泽东《反对本本主义》：“你完完全全调查明白了，你对那个问题就有了解决的办法了。”'),
    ('不理不睬', '毛泽东《必须注意经济工作》：“官僚主义的表现，一种是不理不睬或敷衍塞责的怠工现象。我们要同这种现象作严厉的斗争。”'),
    ('毫无疑问', '毫无疑问，这事跟她有直接关系。'),
    ('客客气气', '民主党派提意见向来是客客气气的。'),
    ('潜移默化', '民众文学当有一种“潜移默化”之功，以纯正的博大的趣味，替代旧有读物、戏剧等底不洁的、褊狭的趣味。'),
    ('水落石出', '水山，不要急。事情早晚能弄个水落石出。'),
    ('一统天下', '汉朝自高祖斩白蛇而起义，一统天下。'),
    ('海枯石烂', '汝要说我降，除非海枯石烂。'),
    ('大逆不道', '汝赖吾玉玺，僭称帝号，背反汉室，大逆不道！吾方欲加兵问罪，岂肯反助贼乎！'),
    ('平淡无奇', '江西境内的风物，太平淡无奇了，这儿和长江沿岸所见到的别无二致。'),
    ('一点半点', '沉寂的寒夜，静悄悄已没一点半点风意。'),
    ('沉默寡言', '沉默寡言，深沉不露，令我忆君之丰采。'),
    ('破口大骂', '沙龙破口大骂，所有十一家猎户俱是他一人承当。'),
    ('看家本领', '没有配角或“下手”，主角的好多看家本领都使不出来。'),
    ('沧海桑田', '沧海桑田，谓世事之多变。'),
    ('沧海横流', '沧海横流，方显出英雄本色。'),
    ('得寸进尺', '法国得寸进尺，五年以后吞并了整个南圻，而心犹未足，还打算攘夺北圻，仅留下中圻给越南。'),
    ('洞房花烛', '洞房花烛之夜，两新人原是旧相知，又多是吃惊吃吓，哭哭啼啼，死边过的，竟得团圆，其乐不可名状。'),
    ('天上人间', '流水落花春去也，天上人间。'),
    ('昏迷不醒', '流血和过多疲劳，使他昏迷不醒，脸色煞白。'),
    ('板上钉钉', '海云是已经定性、已经作了板上钉钉的正式结论的阶级敌人。'),
    ('炎黄子孙', '海内外的炎黄子孙都不会同意台独的。'),
    ('无奇不有', '海底世界无奇不有，光是已知的动物就有三万多种。'),
    ('千奇百怪', '海洋里的生物千奇百怪，非常迷人。'),
    ('呼之欲出', '海立山奔，烟云灭没，谓有龙焉，呼之欲出。'),
    ('欢呼雀跃', '消息传来，大家立刻欢呼雀跃起来。'),
    ('不请自来', '消息公布后，来了许多不请自来的人。'),
    ('证据确凿', '深恐不法勇丁，骚扰百姓，所以面谕本县：倘有前项情事，证据确凿，准其到县指控。审明之后，即以军法从事，决不宽贷。'),
    ('奇奇怪怪', '清·名教中人《好逑传》第14回：“天下事奇奇怪怪，最料不定，再不料无心中救侯孝，倒像有心去救水尚书的一般。”'),
    ('灵机一动', '清·文康《儿女英雄传》第四回：“俄延了半晌，忽然灵机一动，心中悟将过来。”'),
    ('小心在意', '清·无垢道人《八仙全传》第一回：“这官场之事不是容易干的，此去务要小心在意。”'),
    ('金银财宝', '清·曹雪芹《红楼梦》第112回：“且说那伙贼原是何三等邀的，偷抢了好些金银财宝接运出去，见人追赶，知道都是那些不中用的人。”'),
    ('里里外外', '清·曹雪芹《红楼梦》第72回：“如今里里外外上上下下背着我嚼说我的不少，就差你来说了，可知没家亲引不出外鬼来。”'),
    ('叮叮当当', '清·曹雪芹《红楼梦》第87回：“一回儿，檐下的铁马也只管叮叮当当的乱敲起来。一时雪雁先吃完了，进来伺候。”'),
    ('有权有势', '清·曹雪芹《红楼梦》第四回：“如今凡作地方官者，皆有一个私单，上面写的是本省最有权有势、极富极贵的大乡绅名姓，各省皆然。”'),
    ('乒乒乓乓', '清·荑荻散人《玉娇梨》第14回：“忽听得两面头锣乒乒乓乓敲将来，随后就是一对清道蓝旗，许多执事摆列将来。”'),
    ('大鱼大肉', '清·荑荻散人《玉娇梨》第16回：“多卖几亩田，做个财主，大鱼大肉，好不受用。”'),
    ('实不相瞒', '清·荑荻散人《玉娇梨》第十回：“实不相瞒，小弟此时仆马皆饥，正在此商量，恰好遇兄。”'),
    ('云淡风轻', '清·荻岸山人《平山冷燕》第五回：“写了半晌，才写得‘云淡风轻’四个字，便要放下笔。”'),
    ('朦朦胧胧', '清·褚人获《隋唐演义》第19回：“夫人朦朦胧胧，尚不肯就走，早被几个宫人扶的扶，拽的拽，将他搀出宫来迎驾。”'),
    ('头晕眼花', '清·褚人获《隋唐演义》第44回：“罗士信也吃了几杯，坐不到半个时辰，觉得天旋地转，头晕眼花，伏倒几上。”'),
    ('毫不在意', '清·钱彩《说岳全传》第一回：“我佛原是个大慈大悲之主，毫不在意。”'),
    ('取而代之', '清帝方今玩于彼股掌之上，及其时则取而代之耳。'),
    ('心甘情愿', '温州不算十分穷苦的地方，也没碰着大荒年，干什么得了七个小毛钱，就心甘情愿的将自己的小妹子捧给人家呢？'),
    ('温文尔雅', '温文尔雅，正是学者的态度。'),
    ('热血沸腾', '游行的人们个个都是热血沸腾。'),
    ('五花八门', '湖北的省政府在当时真正是一种鱼龙漫衍的“模范政府”，那个委员会五花八门地是什么人品都有。'),
    ('接二连三', '满屋子的手都拱起来，膝关节和腿关节接二连三地屈折，仿佛就要蹲了下去似的。'),
    ('报仇雪恨', '滥官害民贱徒，把我全家诛戮，今日正好报仇雪恨！'),
    ('大喜过望', '灿若灯下一看，正是前日相逢之人，不觉大喜过望，方才放下了心。'),
    ('倾盆大雨', '烟拥层峦云拥腰，倾盆大雨定明朝。'),
    ('水泄不通', '热心的读者除邮局汇捐款络绎不绝外，每天到门口来亲交捐款的，也挤得水泄不通。'),
    ('来龙去脉', '焦裕录严肃地说：“要弄清它的来龙去脉，打垮它、制服它。”'),
    ('起承转合', '然而不得已，也只好起承转合，上台去说几句。'),
    ('大风大浪', '然而她到底是经过无数大风大浪的，深知躲避不了的烦恼，只有昂起头来硬顶。'),
    ('地老天荒', '然而海枯石烂，此恨难消，地老天荒，此情不泯！'),
    ('沾沾自喜', '然而象他那样的人，决不至于让某一件事的胜利弄得沾沾自喜，就此满足。'),
    ('空穴来风', '然而银行当事人，安能逃避责任，空穴来风，理有固然。'),
    ('大显身手', '爱唱的人，就在舞台上痛痛快快唱吧！爱种棉花的，就在连成片的土地上大显身手吧！（茹志娟《高高的白杨树》）'),
    ('层出不穷', '爱国精神之表现于中外文学里已经是层出不穷的，数不胜数了。'),
    ('舍己为人', '爱朋友，讲义气，舍己为人，这些地方他和朱老忠有共同的地方。'),
    ('遮风挡雨', '父母真诚地为孩子遮风挡雨。'),
    ('一尘不染', '特别是夏季，绿树红楼，一尘不染。'),
    ('力所能及', '特别是要用实例、用典型示范去告诉他们组织起来的好处，这种好处是超出单干户力所能及的。'),
    ('独善其身', '独善其身尽日安，何须千古名不朽。'),
    ('狭路相逢', '狭路相逢这恶人，如何是好。'),
    ('魂飞魄散', '猛然间一个人从身后冒冒失失的按住，也不出声，二人唬得魂飞魄散。'),
    ('晴天霹雳', '猝闻这信，真是晴天霹雳，人人裂目，个个椎心。'),
    ('不言不语', '王中见母子说话没缝，只得起来。不言不语，走到前厅，看见主人灵柩。'),
    ('实至名归', '王主任要电报看了，赞他实至名归。'),
    ('聊胜于无', '王二瞎子一听仍是衙门里的人，就是声光比账房差些，尚属慰情聊胜于无。'),
    ('心肝宝贝', '王太太又何至于当她心肝宝贝样，留到这个岁数还不放？'),
    ('别有用心', '王太尊也是说他办事可靠，那里知道他是别有用心的呢。'),
    ('不伦不类', '王夫人听了，早知道来意了。又见他说的不伦不类，也不便不理他。'),
    ('愤愤不平', '王子成父诸人，俱愤愤不平，请于桓公，欲劫鲁侯，以报曹沫之辱。'),
    ('捧腹大笑', '王捧腹大笑。'),
    ('令人钦佩', '王朔《一半是火焰，一半是海水》：“就是那些‘小晃’还有点江湖义气，有点令人钦佩的担事的勇气。”'),
    ('欢欢喜喜', '王朔《无人喝彩》：“不说八抬大轿，也得请几桌客放几挂鞭，然后欢欢喜喜入洞房。”'),
    ('修身养性', '王朔《玩儿的就是心跳》：“上了年纪就安安静静地修身养性颐养天年了。”'),
    ('不绝于耳', '王朔《玩儿的就是心跳》：“开关车门声砰砰不绝于耳。”'),
    ('超凡脱俗', '王朔《给我顶住》：“是你把她抬到了超凡脱俗的境界与尘世欢乐绝了缘。”'),
    ('寡不敌众', '王朗寡不敌众，与白虎、周昕杀条血路，走入城中，拽起吊桥，坚闭城门。'),
    ('若无其事', '王柬芝若无其事地闩上门，又叫她点着灯，他那双眼睛四处巡视着。'),
    ('默默无闻', '现在不知道他怎样，久没有听到消息了，那默默无闻的原因，或者就因为中国人还没有死完的缘故吧。'),
    ('鱼龙混杂', '现在人多手乱，鱼龙混杂，倒是这么着，他们也洗洗清。'),
    ('含情脉脉', '现在又见她含情脉脉，不带点些儿轻狂。'),
    ('言归正传', '现在我们言归正传，集中讨论这件事，发言要围绕中心。'),
    ('大错特错', '现在我们进了牢狱便是‘得仁’，那是大错特错！'),
    ('生死关头', '现在是总罢工的生死关头，没有时间让你去从容整理！'),
    ('史无前例', '现在的贫富悬殊是史无前例；现在的享用娱乐也是史无前例的。（朱自清《论且顾眼前》）'),
    ('更新换代', '现在科学技术更新换代很快。'),
    ('堂而皇之', '现在这时代，劳动做工是堂而皇之的了。'),
    ('别无选择', '现在，我们别无选择，只有拼搏到底。'),
    ('摇旗呐喊', '球场上球迷们摇旗呐喊，为各自的球队助威。'),
    ('开源节流', '理财之道，不外开源节流。'),
    ('乱七八糟', '琴弹得乱七八糟，可是她的嗓子怪清亮的。'),
    ('博大精深', '瑚之为学，博大精深，以经世自任。'),
    ('大失所望', '瑞虹大失所望，但到此地间，无可奈何。'),
    ('相得益彰', '由于它的内容太卓越了，朴拙的形式并不造成不良影响；相反的，却使它们相得益彰。'),
    ('掉以轻心', '由于这样，好些人就对于文学作品中另一方面的道理—装饰的美掉以轻心了。'),
    ('同日而语', '由此观之，其为乐未可以同日而语也。'),
    ('和颜悦色', '申子平急上前，和颜悦色的把原委说了一遍。'),
    ('男男女女', '电影院里早已挤满许多男男女女。'),
    ('保家卫国', '男子汉应担当起保家卫国的重任。'),
    ('坑蒙拐骗', '白主任，你怎么竟干坑蒙拐骗的事呢!'),
    ('一哄而散', '白凤、阿男早收拾好钱文，向众人道谢，看的就一哄而散了。'),
    ('白发苍苍', '白发苍苍的李四光硖硖眼睛，笑了一笑。'),
    ('一飞冲天', '白常欲一鸣惊人，一飞冲天。'),
    ('精益求精', '白求恩同志是个医生，他以医疗为职业，对技术精益求精；在整个八路军医务系统中，他的医术是很高明的。'),
    ('白纸黑字', '白纸黑字贴在墙上，你还昧得了？”（赵树理《锻炼锻炼》）'),
    ('白驹过隙', '白驹过隙，日月穿梭，才见梅开腊底，又早天气回阳。'),
    ('毁于一旦', '百余年辛苦经营的圆明园，毁于一旦，更是令人椎心泣血的莫大恨事。'),
    ('一家之言', '皆当补译，以成一家之言。'),
    ('一意孤行', '皇上和杨文弱、高起潜虽有意与虏议和，但迫于臣民清议，尚不敢公然一意孤行，与虏订城下之盟。'),
    ('不可一世', '盖兴会飙举，不可一世矣。'),
    ('不可多得', '盖北宋以睢漆擅名，今已不可多得。'),
    ('目中无人', '盖欲使执事知区区布衣亦有不可犯者，毋遂目中无人而慨凌轹之也。'),
    ('天荒地老', '盖谓世间惟有愿得成双的，随你天荒地老，此情到底不泯也。'),
    ('逆流而上', '目前，正有一股寒流向我们压过来，我们要逆流而上，打上去！'),
    ('截然不同', '直到近来，经过许多学者的研究，才知道孩子的世界，与成人截然不同。'),
    ('斗转星移', '直吃的昏惨惨更阑夜深，直熬的明皎皎斗转星移。'),
    ('鸦雀无声', '直等到大众去净之后，静悄悄的鸦雀无声。'),
    ('无从下手', '相传曹操怕死后被人掘坟，造了七十二疑冢，令人无从下手。'),
    ('茁壮成长', '看到下一代健康活泼地茁壮成长，为人父母者无不感到十分欣慰。'),
    ('可怜巴巴', '看到他可怜巴巴的样子，我的怒火也就灭了。'),
    ('聚精会神', '看校样时的聚精会神，就和在写作的时候一样，因为我的目的要使它没有一个错字。'),
    ('交头接耳', '看见门上那些人在那里交头接耳，好像要使贾政知道的似的，又不好明回，只管咕咕唧唧的说话。'),
    ('走马观花', '看这部书也不过走马观花。'),
    ('自由自在', '看那些交了卷出去的人真象自由自在的仙人。'),
    ('威风凛凛', '看那少年，生得身长八尺，浓眉大眼，阔面重颐，威风凛凛。'),
    ('真心实意', '真心实意，才能找到知己。'),
    ('改朝换代', '真是改朝换代了。学生也来管闲事！他们要到苏货铺里检查东洋货。'),
    ('邪不压正', '真是邪不压正，我们终于胜利了。'),
    ('不胜枚举', '真是钉子之多，不胜枚举。'),
    ('翻天覆地', '真象翻天覆地的变动就快要临头了。'),
    ('一线生机', '眼前分明有一线生机。'),
    ('泪如雨下', '眼盻盻看着他人去了，自己不能奋飞，万箭攒心，不觉泪如雨下。'),
    ('平白无故', '眼看平白无故被他们拿去。不，这等于是他们砸明火、路劫！（梁斌《红旗谱》三十二）'),
    ('精疲力尽', '瞿秋白《饿乡纪程》：“走得精疲力尽，想找一辆马车，也找不着。”'),
    ('痛心疾首', '瞿耐庵自从到任至今也有半年了。治下的百姓因他听断糊涂，一个个痛心疾首。'),
    ('分庭抗礼', '知县此番便和他分庭抗礼，留着吃了饭，叫他拜做老师。'),
    ('推陈出新', '研究棋艺，推陈出新。'),
    ('掩耳盗铃', '硬把汉奸合法化了，只是掩耳盗铃的笨拙的把戏。'),
    ('参差不齐', '礼生见他们参差不齐，也只好由着他们敷衍了事。'),
    ('各种各样', '社会上的人各种各样。'),
    ('群魔乱舞', '社会动荡，群魔乱舞的时代一去不复返了。'),
    ('停滞不前', '社会是发展的、进步的，决不会停滞不前，或者倒退。'),
    ('适者生存', '社会竞争十分残酷，适者生存'),
    ('一见钟情', '祁连山俘虏了我的心，青海湖我一见钟情。（徐迟《三峡记·远游》）'),
    ('万事如意', '祝你万事如意。'),
    ('红红火火', '祝你们的小日子过得红红火火。'),
    ('过河拆桥', '祥子受了那么多的累，过河拆桥，老头子翻脸不认人，他们替祥子不平。'),
    ('堆积如山', '福王仓中的粮食堆积如山，朽得不能再吃。'),
    ('不可缺少', '私人工商业是新民主主义经济不可缺少的一部分，我们要扶助它发展。'),
    ('奇耻大辱', '科学家和文学家都遭到了奇耻大辱，有的因受迫害致死。'),
    ('另当别论', '穆宗是年方弱冠，不急于此，谁知祸起不测，另当别论。'),
    ('其乐无穷', '穷人却挟了一条破席，铺在路上，脱衣服，浴凉风，其乐无穷。'),
    ('苟延残喘', '穷得当卖全无，虽只区区四金，到也不无小补，又可以苟延残喘得好几日了。'),
    ('指手画脚', '站在他们前头领导他们呢？还是站在他们后头指手画脚地批评他们呢？'),
    ('十字路口', '站在歧路上是几乎难于举足，站在十字路口，是可走的道路很多。（鲁迅《华盖集·北京通信》）'),
    ('安安静静', '章诒和《往事并不如烟·君子之交》：“你的心上是不是长了草？能不能安安静静地做成一件事？”'),
    ('老弱病残', '章诒和《往事并不如烟·斯人寂寞》：“对个老弱病残来说，在一千多天的日子里，什么情况都可能发生。”'),
    ('善解人意', '章诒和《往事并不如烟·最后的贵族》：“她与康老一样的善解人意，却很少将自己的事随便告人。”'),
    ('乐于助人', '章诒和《往事并不如烟·最后的贵族》：“康同璧的乐于助人，在一定程度上是受了家庭的影响。”'),
    ('勤俭节约', '章诒和《往事并不如烟·正在有情无思间》：“那年月提倡的是艰苦朴素、勤俭节约。”'),
    ('悲欢离合', '童年的记忆最单纯最真切，影响最深最久，种种悲欢离合，回想起来最有意思。'),
    ('竭尽全力', '竭尽全力地去反对第一个可能性，争取第二个可能性，反对第一个前途，争取第二个前途。'),
    ('我行我素', '笑骂由人笑骂，我行我素而已。'),
    ('人多势众', '第三派可人多势众，这伙人咬牙发狠地极力肯定，说他是在闹左道邪门。'),
    ('无所顾忌', '等到后来张太太把抵押的凭据禀了上头存了案，他却无所顾忌了。'),
    ('万家灯火', '签后当日送出，我回家时已经万家灯火了。'),
    ('简而言之', '简而言之，我们得尽快办好。'),
    ('不以为意', '管亥望见救军来到，亲自引兵迎敌；因见玄德兵少，不以为意。'),
    ('名不虚传', '系船白面问溪翁，名不虚传说未通。'),
    ('冷冷清清', '红军每到一地，群众冷冷清清，经过宣传之后，才慢慢地起来。'),
    ('后患无穷', '纵容破坏植被、滥砍乱伐，是后患无穷的事。'),
    ('极乐世界', '细观此景，与我大唐何异！所为极乐世界，诚此之谓也。'),
    ('颠倒黑白', '终日终夜，只是躺在烟铺上，公事大小，一概不问，任着幕宾胥使，颠倒黑白。'),
    ('真相大白', '经过严密的侦察，这个案件终于真相大白。'),
    ('脱颖而出', '经过艰苦努力，他的学习成绩终于在全班脱颖而出。'),
    ('遍体鳞伤', '经过这十多天的轰炸，广州是遍体鳞伤了。'),
    ('行云流水', '结构如行云流水，层次分明，先后呼应。'),
    ('不识好歹', '给你们读一点古书总是好意；古书又不是毒药，竟会这样胡闹起来，这明明是不识好歹呀！'),
    ('举手投足', '给老幼妇孺让座是举手投足的事情。'),
    ('无法无天', '统领的兵，一个个无法无天，我们的苦头也吃够了，实在说不出一个“好”字。'),
    ('寸步难行', '美娘赤了脚，寸步难行。'),
    ('百花齐放', '美术展览会上展出了许多新作品，百花齐放，各具风格。'),
    ('两小无猜', '翁有女，小字江城，与生同甲，时皆八、九岁，两小无猜，日共嬉戏。'),
    ('古今中外', '翻遍了古今中外的历史，没有一个国家曾经用这种所谓示威运动而变成了既富且强。'),
    ('不紧不慢', '老人不紧不慢地说……'),
    ('赤手空拳', '老人没了主意，日本兵有枪，他自己赤手空拳。'),
    ('明见万里', '老先生台论，可谓明见万里。'),
    ('自得其乐', '老头儿有个老伴儿，带一个伙计，就这么活着，倒也自得其乐。'),
    ('目不转睛', '老婆婆看着小官人，目不转睛，不觉两泪交流。'),
    ('一口咬定', '老山东摇摇头，一口咬定：“不用看，我心里有数！我家的秤老辈用的，十四两顶新秤一斤，错不了。”'),
    ('恰如其分', '老师举的这个例子恰如其分，同学们很快就掌握了这种方法。'),
    ('有问必答', '老师对学生提出的问题应该有问必答。'),
    ('置之不理', '老师批评他，他置之不理。'),
    ('字里行间', '老弟上的条陈，第一要不拘成格，字里行间，略带些古文气息，方能中肯。'),
    ('出乎意料', '老朋友劝他出去一下调理也好，出乎意料的是学校竟然不准。'),
    ('有色眼镜', '老梁，假若你总是戴上有色眼镜，看一切事物和一切人，假若你把你我之间的冲突当作是个人意气用事，那就是清清楚楚地毁你自己。'),
    ('稀奇古怪', '老残道：“这也罢了，只是你赶紧说你那稀奇古怪的案情罢。”'),
    ('多如牛毛', '老百姓痛恨官府催粮催捐，苛捐杂派多如牛毛，逼得老百姓活不下去。'),
    ('酣畅淋漓', '老舍先生写老张的“钱本位”的哲学，确乎是酣畅淋漓，阐扬尽致。'),
    ('深思熟虑', '而其人亦得深思熟虑，周旋于是，不过十年，将必有卓然可观者也。'),
    ('名副其实', '而况教育能不能名副其实，还是个不能便下断语的问题。'),
    ('急功近利', '而急功近利，不避声色，则阳明学为厉阶。'),
    ('任劳任怨', '而杨嗣昌也完全执行他的主张，任劳任怨。'),
    ('背井离乡', '背井离乡，卧雪眠霜。'),
    ('忍辱负重', '胡仇叹道：“‘忍辱负重’。郑兄，真不可及！”'),
    ('腥风血雨', '腥风血雨满松林，散乱毛发坠山奄。'),
    ('信誓旦旦', '臣乃脉定于内，心正于怀，信誓旦旦，秉志不回，翻然高举，与彼长辞。'),
    ('众口难调', '臣非纵子不忠，奈众口难调。'),
    ('三皇五帝', '自从盘古开天地，三皇五帝到于今，历史上曾经有过我们这样的长征吗？'),
    ('闭门造车', '自以为闭门造车，出而合辙，而门外之辙与其所造之车，果相合否。'),
    ('战无不胜', '自先王以来，楚兵战无不胜。'),
    ('英雄豪杰', '自古英雄豪杰，不经心志之拂乱，未必能奋发有为，故敌国外患之来，实磨砺英豪之一块试金石也。'),
    ('风调雨顺', '自后国泰民安，风调雨顺，五谷丰登，人物康阜，真是升平世界。'),
    ('自始至终', '自始至终，秀莲唱得很拘谨，好像并不想取悦听众。'),
    ('神来之笔', '自己也觉得仿佛是神来之笔，如用别的韵语形式去写，便决不能有此力量。'),
    ('装聋作哑', '自己的事为甚么要让旁人摆布，自己还装聋作哑！'),
    ('权宜之计', '自成心中认为成立娘子军只是一时权宜之计，往后怎么个办法，他还没有想妥当。'),
    ('百家争鸣', '自春秋末年以来，中国的思想得到一个极大的开放，呈现出一个百家争鸣的局面。'),
    ('日积月累', '自是以后，日积月累，千百成群，其为国之蠹害甚矣。'),
    ('念念有词', '至三更时，仗剑步罡，焚符一道，口中念念有词，把令牌一拍，只见李邕忽从壁间步出。'),
    ('吞吞吐吐', '至于新作，现在可是难了，较好的简直无处发表，但若做得吞吞吐吐，自己又觉无聊。（鲁迅《书信集·致曹靖华》）'),
    ('斤斤计较', '至于梦中的“苦乐”，则照我素人的见解，毕竟是梦中的“苦乐”，不必斤斤计较的。'),
    ('大张旗鼓', '至于那一部小说，本来当属于古董之部，若要大张旗鼓，颂为二十世纪的新作品，则小子不敏，实不敢也。'),
    ('石沉大海', '至第三日，又带了几个水手，分头寻找，也是枉然。一连找了数日，竟似石沉大海。'),
    ('异曲同工', '至诚虽是个小弟弟，又是个“书朋友，他的观察力和记忆力却骎骎乎与大哥异曲同工。'),
    ('翩翩起舞', '舞池内一对对情侣在翩翩起舞。'),
    ('素不相识', '船儿只管乘风破浪的一直的走，走向那素不相识的他乡。'),
    ('人山人海', '节日的公园人山人海，热闹极了。'),
    ('亭亭玉立', '花型小，比起亭亭玉立的荷花远逊。'),
    ('车水马龙', '花天酒地，闹个不休，车水马龙，日无暇晷。'),
    ('人间天堂', '苏杭被称为人间天堂。'),
    ('独树一帜', '苏轼也擅长书法，他取法颜真卿，但能独树一帜，与蔡襄、黄庭坚、米芾并称宋代四大家。'),
    ('三言两语', '若不是我这老手三言两语拿他降伏住，还不晓得闹点什么事情出来哩。'),
    ('有意无意', '若以有意无意可解不可解间求之，不免此诗第一耳。”'),
    ('如鱼得水', '若使他回来了，我们就应该如鱼得水，欢喜的了不得，那里还有功夫在这里纳闷呢！'),
    ('一年半载', '若小弟侥幸，这回去就得个肥美地方，到任一年半载，那时带几百银子来帮衬他，倒不值甚么。'),
    ('并驾齐驱', '若让我估量这本书的总价值，我以为只逊于《红楼梦》一筹，与《儒林外史》是可以并驾齐驱的。'),
    ('敬而远之', '若遇此等人，敬而远之，以免杀身之祸。'),
    ('风风雨雨', '若闹闹嚷嚷，弄得满坝风风雨雨，不是逗得人暗里朝他说怪话吗？（克非《春潮急》二十六）'),
    ('设身处地', '若非梦往神游，何谓设身处地？'),
    ('小家子气', '若题目过于新巧，韵过于险，再不得好诗，倒小家子气。（清·曹雪芹《红楼梦》第三十七回）'),
    ('将信将疑', '荣禄对他是持着戒心的，所以这番愤激之言，在将信将疑之间。'),
    ('袖手旁观', '荪老三的事就和我自己的事一样，我不能袖手旁观。'),
    ('无情无义', '莫怪我无情无义。'),
    ('盖棺定论', '莫道古人多玉碎，盖棺定论未嫌迟。'),
    ('心神不定', '莲峰心神不定，吃了夜饭，却去灯下赶要紧笔墨。'),
    ('坐立不安', '萧状元终日在此来往，吾等见了坐立不安。'),
    ('任人宰割', '落后就要挨打，只好任人宰割。'),
    ('不可告人', '著诸书者，其人皆深极哀苦，有不可告人之隐，乃以委曲譬喻出之。'),
    ('不可收拾', '蒲殿俊辈登台之后，因为纵容兵士的结果，弄到了一个不可收拾的地步。'),
    ('功成身退', '蔡京这个左仆射更是难处，还是以‘功成身退’为佳。'),
    ('不明不白', '薛婆当时满脸堆下笑来，便道：“大官人休得错怪。老身一生不曾要别人一厘一毫不明不白的钱财。”'),
    ('易如反掌', '藩台又叫首府、首县写信出去，向外府、县替他张罗，大约一二千金，易如反掌。'),
    ('要死要活', '虔婆也慌了，叫了老乌龟上来，再三劝解，总是不肯依，闹的要死要活。'),
    ('省吃俭用', '虞华轩在家，省吃俭用，积起几两银子。'),
    ('各有所长', '虽各有所长，皆不免著于一偏。'),
    ('爱不释手', '虽是不合他的路数，可奈文有定评，他看了也知道爱不释手。'),
    ('喜怒哀乐', '虽是海外之邦，不过言语不同，衣服有异，那喜怒哀乐的人情，原是一样的。'),
    ('一窍不通', '虽然他是一窍不通的浑虫，可是双桥镇上并无“镇长”之流的官儿，他也还明白。'),
    ('口口相传', '虽然他败坏了口口相传的韵事。'),
    ('古往今来', '虽然住了两三天，日子却不多，把古往今来没见过的，没吃过的，没听见的，都经验过了。'),
    ('销声匿迹', '虽然在初期也有少数人唱导‘与抗战无关’论，但为大势所迫，不久也就销声匿迹了。'),
    ('地利人和', '虽然犯了一次错误，红军已卷土重来此地利人和之边界，前途希望还是不恶。'),
    ('大相径庭', '虽然结果一样，其“因”却大相径庭。'),
    ('声东击西', '蜀人或声东击西，指南攻北，吾兵必须分头守把。'),
    ('谋财害命', '血池狱、阿鼻狱、秤杆狱，脱皮露骨，折臂断筋，也只为谋财害命，宰畜屠生。'),
    ('手到擒来', '行者道：“这个容易，老孙去手到擒来。”'),
    ('肃然起敬', '衍举眼观看仲连，神清骨爽，飘飘乎有神仙之度，不觉肃然起敬。'),
    ('泛滥成灾', '表报之多，闹得泛滥成灾。'),
    ('现身说法', '袁伯珍这一席话，可谓现身说法。'),
    ('恍然大悟', '袁太守和庄太守听了，方才恍然大悟，彼此相视而笑。'),
    ('一见倾心', '袁小姐对于我们的太太是一见倾心，说我们的太太浑身都是曲线，是他眼中的第一美人。（冰心《我们太太的客厅》）'),
    ('心烦意乱', '袁绍回冀州，心烦意乱，不理政事。'),
    ('误打误撞', '袭人笑道：“不过是误打误撞的遇见了，说约下了可是没有的事。”'),
    ('西子捧心', '西子捧心，孙寿折腰。'),
    ('西装革履', '西装革履、华裙艳服，只有在演出的时候演员的身上才出现。'),
    ('回心转意', '要不然时，叫他趁早回心转意，有多少好处。'),
    ('重蹈覆辙', '要从失败中吸取教训，以免重蹈覆辙。'),
    ('全知全能', '要做到全知全能是不容易的。'),
    ('流芳百世', '要做到流芳百世也不是很难。'),
    ('一生一世', '要是有了生活做，我一生一世也忘不了你的恩。'),
    ('天外有天', '要知道天外有天，不能骄傲自满。'),
    ('不择手段', '要谋生，谋生之道，则不择手段。'),
    ('见义勇为', '见义勇为真汉子，莫将成败论英雄。'),
    ('张牙舞爪', '见了州官，州判老爷胆子也壮了，张牙舞爪，有句没句，跟着教习说了一大泡。'),
    ('冷嘲热讽', '见了老徐，说了几句冷嘲热讽的话儿。'),
    ('见仁见智', '见仁见智，议论纷纭，却无非背后论人是非，在兆奎面前都有忌讳。'),
    ('柔情似水', '见他穿一身白纱衫裤，头上只带着一排茉莉花条，趁着那杨柳纤腰，梨花白面，趁显得柔情似水，媚态如春。'),
    ('沉吟不语', '见士及沉吟不语，便问士及道：“请问哥哥，这是何人所送？如此踌躇？”'),
    ('东张西望', '见范进抱着鸡，手里插个草标，一步一踱的，东张西望，在那里寻人买。'),
    ('先入为主', '见长幼尊卑之节有一定不易之理，先入为主，故后起之私心，终有所顾忌而不敢逞。'),
    ('视而不见', '视而不见，谓合道于希夷。'),
    ('柴米油盐', '解决群众的穿衣问题，吃饭问题，住房问题，柴米油盐问题，疾病卫生问题，婚姻问题。'),
    ('光彩夺目', '解开来，只见一团绵裹着寸许大一颗夜明珠，光彩夺目。'),
    ('大势所趋', '解放区人民的力量，大后方人民的力量，国际形势，大势所趋，使得国民党不得不承认这些东西。'),
    ('手忙脚乱', '諕的我手忙脚乱紧收拾。'),
    ('一视同仁', '警察却不怕自行车，更不怕洋车和三轮儿。他们对洋车和三轮儿倒是一视同仁，一个不顺眼就拳脚一齐来。'),
    ('眉飞色舞', '譬如“郭巨埋儿”，无论如何总难以画到引得孩子眉飞色舞，自愿躺到坑里去。'),
    ('默不作声', '讨论会上，大家都对提出的问题踊跃发表意见，而他却一直默不作声。'),
    ('千疮百孔', '让他们都显显身手，谁能把这个千疮百孔的中国从热火里救出来，算谁有本事。'),
    ('死去活来', '让众官进去，才晓得柳知府已经吓得死去活来。'),
    ('休养生息', '许其修睦，因以罢兵，庶几休养生息，各正性命，仰合于天心。'),
    ('打打闹闹', '许逊、方方打打闹闹，看到那边亭子里有几个小孩在打弹弓仗。'),
    ('欲罢不能', '设或命运坎坷，从中别生枝节，拖延日久，虽要将就了事，欲罢不能。'),
    ('长篇大论', '诗上所叙闺臣姐姐事迹，长篇大论，倒象替他题了一个小照。'),
    ('不堪回首', '诚有令人不堪回首者，则我今日之临眺于此，虽百年之久，曾不能以一瞬尔。'),
    ('津津有味', '话是这样说，可是谈起理论，许宁还是一套套地向道静谈得津津有味，头头是道。'),
    ('荣华富贵', '话说人生荣华富贵，眼前的多是空花，不可认为实相。'),
    ('据为己有', '话说袁伯珍见王德黼的矿山苗旺，有利可图，便想夺他的利权，据为己有。'),
    ('蜂拥而至', '该处七哨匪徒，不下数十万人，每聚众时，用牛角一吹，无不蜂拥而至。'),
    ('本末倒置', '该简者你却详而不简，该详者你又简而不详。本末倒置，批评你还不愿意？乱弹琴！'),
    ('欲言又止', '语甚凄楚，惊问之，欲言又止者再。'),
    ('未尝不可', '说以前九年都是酝酿的时期，或是过渡的时期，也未尝不可。'),
    ('照本宣科', '说法是照本宣科，十分单纯的。'),
    ('大同小异', '说的是侯统领一个，其实如今做官的人，无非与侯统领大同小异罢了。'),
    ('谈何容易', '说的，谈何容易，他肯由你要回，方才不带他们去了。'),
    ('不堪入目', '说着，早一屁股坐下，那种气极败坏的样子，实是不堪入目。'),
    ('扬长而去', '说罢，深深一揖，扬长而去。'),
    ('开门见山', '说话要开门见山，谭兄之意，欲以世兄读书之事，烦潜老照管理。'),
    ('一言难尽', '说起这件事，真是一言难尽，等有时间我们再详谈。'),
    ('大获全胜', '请伏兵于河口，乘其将济而击之，必大获全胜。'),
    ('对号入座', '请勿对号入座。'),
    ('不明真相', '请尽快公布事情的真相，让那些不明真相的群众回到各自岗位上去。'),
    ('手下留情', '请手下留情，不要扼杀新生力量。'),
    ('整整齐齐', '请把座位排得整整齐齐。'),
    ('七七八八', '请把这些七七八八收拾整齐。'),
    ('零零碎碎', '请把这些零零碎碎收拾好。'),
    ('前前后后', '请把这件事情的前前后后说一遍。'),
    ('尊姓大名', '请问您的尊姓大名？'),
    ('风雨同舟', '诸公热诚毅力，十倍仲恺，当有善法，济此艰难。庶几风雨同舟，危亡共拯。'),
    ('死记硬背', '读书不能靠死记硬背。'),
    ('自暴自弃', '读书人悲观失望，自暴自弃；可是那些工人却多么坚强呵，多么勇敢呵！'),
    ('浮想联翩', '读六月三十日《人民日报》，余江县消灭了血吸虫。浮想联翩，夜不能寐。'),
