    ('反反复复', '邓小平《贵州新区工作的策略》：“因此要对党内干部作反反复复的教育，才能保证其执行。”'),
    ('大吃一惊', '那个朋友和他再次见面，不禁大吃一惊。'),
    ('混淆视听', '那些人经常故意混淆视听，影响很坏。'),
    ('无名小卒', '那些无名小卒，尽都解甲投降。'),
    ('勉勉强强', '那余大人出其不意，只得勉勉强强答道：‘读过。’'),
