    '太史公曰：始翟公为廷尉，宾客阗门；及废，门外可设雀罗。翟公复为廷尉，宾客欲往，翟公乃大署其门曰：‘一死一生，乃知交情。’',
    '指有关生死的关键时刻。',
    '杨子取为我，拔一毛而利天下，不为也。',
    '一根汗毛也不肯拔。原指杨朱的极端为我主义。后形容为人非常吝啬自私。',
    '一毛吞海，海性无亏。纤芥投锋，锋利不动。学与无学唯我知焉。',
    '毛：同“蚝”，蛤蜊。一只蛤蜊吞吸海水。比喻无损于事。',
    '三年中作变律诗九首，上广州李帅，其文意长于讽刺，亦有陈拾遗一鳞半甲。',
    '比喻零星片段的事物。',
    '且夫天地之间，物各有主；苟非吾之所有，虽一毫而莫取。',
    '纵然是一个模子铸的，好道打磨不到，也有多个瘢儿，少个蒂儿，却怎么这等一毫不差。',
    '指完全相同，没有一点差异。',
    '一根毫毛也不肯拔。原指杨朱的极端为我主义。后形容为人非常吝啬自私。',
    '即其可名状者言之，则本之一毫不染之真，而加之百折不移之守。',
    '据《易说》言也。',
    '指差错虽微，造成的危害甚大。',
    '古者百里而异习，千里而殊俗。故明王修道，一民同俗。',
    '指使人民的思想风俗齐同。',
    '一口气做成。形容文章结构紧凑，文气连贯。也比喻做一件事安排紧凑，迅速不间断地完成。',
    '以诗志别，分韵得‘秋’字，援笔立就，一气浑成。',
    '形容诗文首尾贯通，完满自然，不见雕凿。',
    '山中苦寒，法体清康。一水之隔，无缘躬诣道场，少闻謦欬。',
    '受一条河水的阻隔。比喻双方因受水路交通不便而很少会面。',
    '渺然一水隔，何由税归鞅？',
    '我一沐三捉发，一饭三吐哺，起以待士，犹恐失天下之贤人。',
    '比喻求贤心切。',
    '然我一沐三捉发，一饭三吐哺，起以待士，犹恐失天下之贤人。',
    '沐：洗头；捉：用手攥住；哺：口中含的食物。洗一次头与吃一顿饭要停顿三次。形容渴求贤才，谦恭下士。形容为延揽贤才而忙碌',
    '吾文王之子，武王之弟，成王之叔父也，又相天下，吾於天下亦不轻矣，然一沐三握发，一饭三吐哺，犹恐失天下之士。’',
    '沐：洗头；握：用手攥住。洗一次头发中间要停下来三次。比喻求贤心切。',
    '沐：洗头。洗一次头要停顿三次。形容渴求贤才，谦恭下士',
    '天下之生久矣，一治一乱。',
    '譬如一泓清水，有少许砂土便见。',
    '泓：水清的样子。一片明净清澈的水。比喻心地纯洁。',
    '冷暖旧雨今雨，是非一波万波。',
    '比喻事情开端后的不断发展变化。同“一波才动万波随”。',
    '然其一波三折笔之势，亦自不苟。',
    '波：指书法中的捺；折：指写字时转笔锋。原指写字的笔法曲折多变。现比喻文章的结构起伏曲折。也比喻事情进行中意外的变化很多。',
    '千尺丝纶直下垂，一波才动万波随。',
    '指一波方动，万波随之而起。比喻事情开端后的不断发展变化。',
    '波澜开阖，如在江湖中，一波未平，一波已作。',
    '一个浪头尚未平复，另一个浪头又掀起了。比喻事情进行波折很多，一个问题还没有解决，另一个问题又发生了。',
    '波澜开阖，如在江湖中，一波未成，一波已作。',
    '一个波浪还没形成，另一个波浪又起来了',
    '形容江河水势奔流直下，流得又快又远。同“一泻千里”。',
    '大江在河，一泻千里。',
    '泻：水往下直注。形容江河奔流直下，流得又快又远。也比喻文笔或乐曲气势奔放。也形容价格猛跌不止。',
    '一泻汪洋。',
    '形容水流迅速，水势浩大。',
    '悬流轰轰射水府，一泻百里翻云涛。',
    '青山万里静散地，白雨一洗空垂萝。',
    '易世之怨，一洗而空。',
    '有鸟将来，张罗而待之，得鸟者罗之一目也。今为一目之罗，则无时得鸟矣。',
    '只有一个洞的网。',
    '一洼死水全无浪，也有春风摆动时。',
    '这畜生说什么乘人不备逃出来，那全是他一派胡言罢了。',
    '公初不示诸将腹心，而今委以兵，此皆嗜利者，朝廷以一浆十饼诱之，去矣。',
    '一碗浆，十个饼。比喻小恩小惠。',
    '十分清楚、明白。',
    '我姓韩的桥是桥，路是路，一清二白的，怕谁来歪我不成。',
    '比喻十分清白。亦比喻非常清楚。',
    '你在衙门中一清如水，朝廷知你是个个廉吏，异日定来聘你为官。',
