    '一渊不两蛟，水定则清正。',
    '比喻两雄不能并立。',
    '吾王不游，吾何以休？吾王不豫，吾何以助？一游一豫，为诸侯度。',
    '豫：游乐。常指帝王的游乐生活。',
    '说罢了这一句，便一溜烟外面去了。',
    '形容跑得很快。',
    '心下大喜，将书藏在柏中，复翻身爬出窗外，将窗扇依旧闭上，一溜风走到方丈里坐定，悄悄开书，默诵那词咒。',
    '我正忒坎坷，自怨咨，九重天忽有君恩至，正是一湾死水全无浪，也有春风摆动时。',
    '秋痕这一日，愤气填胸，一点泪也没有，和衣睡到三更后，一灯如豆，炉火不温，好像窗外梅树下悉索有声，又像人叹气。',
    '一盏只有豆粒那样大光线的灯。形容灯光暗弱。',
    '饭尚未蒸熟，一场好梦已经做醒。原比喻人生虚幻。后比喻不能实现的梦想。',
    '做成一件事就出了名。',
    '一炷心香洞府开，偃松皱涩半莓苔。',
