    '但是中国的人，只有家族和宗族的团体，没有民族的精神，所以虽有四万万人结合成一个中国，实在是一片散沙。',
    '比喻力量分散，没有组织起来。同“一盘散沙”。',
    '郑州底下黄河开了口子，漫延十余州县，一片汪洋，尽成泽国。',
