    '形容遭遇火灾（或战火），房屋全部被衩焚毁的景象。',
    '圣人望下一看，见他正是服官从政的年纪，脸上一团正气，胸中自然是一片至诚。',
    '形容十分真挚诚恳。',
    '一片丹心合万灵，应时甘雨带龙腥。',
