    '一牛九锁，更相牵挛，案明如市，不得东西，请谳得报，日中被刑。',
    '比喻无法解脱。',
    '拘卢舍，此云五百弓，亦云一牛吼地，谓大牛鸣声所极闻。或云一鼓声。《俱舍》云二里，《杂宝藏》云五里。',
    '指牛鸣声可及之地。比喻距离较近。',
