    '瓶中装满水晃不响，装半瓶水时一晃就响。比喻充实的人谦虚寡言，而浅薄的人偏偏爱显示夸耀自己。',
    '一辈子。',
    '相怜相念倍相亲，一生一代一双人。',
    '一死一生，乃知交情；一贫一富，乃见交态；一贵一贱，交情乃见。',
