    '指时好时病。形容体弱。',
    '虔婆道：‘也常时三好两歹的，亏的太平府陈四老爷照顾他。’',
    '身体三天好，两天不好。指时好时病。形容体弱。',
    '娘子与冯官人相见之后，至今三好二怯。',
    '指时好时病。形容体弱。同“三好两歹”。',
    '你做状元的人，三妻四妾，任凭再娶。',
    '妻妾众多的意思。',
    '三姑者，尼姑、道姑、卦姑也；六婆者，牙婆、媒婆、师婆、虔婆、药婆、稳婆也。',
    '吏勋封考，三婆两嫂。',
    '犹言三妻四妾。',
    '我大茶小礼，三媒六证，亲自娶了个夫人。',
    '旧时婚姻，由父母包办，还必须有媒人介绍。表示郑重其事。',
    '‘莫须有’三字，何以服天下？',
    '狱：指官司，罪案。指宋朝名将岳飞的冤狱。后也泛指冤狱。',
    '兀那三宫六院，妃嫔彩女听者：明日圣驾亲到御园，打一金弹，金弹落处，有拾得者。',
    '泛指帝王的妃嫔。',
    '永谢十年旧，老死三家村。',
    '指偏僻的小乡村。',
    '毛先生以三寸不烂之舌，强于百万之师。',
    '比喻能说会辩的口才。',
    '车之所以能转千里者，以其要在三寸之辖。',
    '辖：车轴头上穿的小铁棍，管住轮子使其不脱落。指车辖。比喻事物的关键。',
    '凿金为莲花以帖地，令潘妃行春上，曰：‘此步步生莲花也。’',
    '金莲：旧指女子缠过的小脚。封建时代美誉妇女小脚的用语。',
    '回头我自会请三先生来，大家三对六面讲个明白。',
    '人 指会同当事双方及中间人或见证人。',
    '太师闻报，破了两阵，只急得三尸神暴跳，七窍内生烟。',
    '三尸：道家认为人体内有作崇的神，叫“三尸”或“三尸神”；七窍：指两眼、两耳、两鼻孔和嘴。形容人气愤到极点。',
    '比喻奸佞之臣。',
    '形容人气愤到极点。',
    '时清不及英豪人，三尺童儿重廉蔺。',
    '指年幼还不太懂事的儿童。',
    '夫三尺童子至无识也，指犬豕而使之拜，则怫然怒。',
    '指年幼不懂事的儿童。',
    '东北方言，指家庭之内的事。',
    '三山半落青天外，二水中分白鹭洲。',
    '三山：护国山，位于南京西南，以有三峰得名；二水：白鹭洲，位于长江之中，分江面为二。泛指南京的山水。',
    '三山五岳渺何许？云烟汗漫空竛竮。',
    '五岳：泰山、华山、衡山、嵩山、恒山。泛指名山或各地。',
    '你要出了三差两错，叫小堆八在前方知道了，我们可怎么对得起他！',
    '泛指差错。比喻偶然的差错。',
    '要有什么三差五错，那事情就难说了！',
    '泛指差错。常指意外的事故。',
    '粗茶淡饭，饱即休，被破遮寒，暖即休；三平二满，过即休，不贪不妨，老即休。',
    '平、满：平日、满日。旧时占卜认为平日、满日主生，为种谷佳日。比喻生活过得去，很满足。',
    '日有光，月有明。三年不目日，视必盲；三年不目月，精必荧。',
    '三年不见日月，精神不振，眼睛朦胧。比喻懒于修养，不求进取。',
    '虽有园圃，不窥视之，言专学也。',
    '指专心苦学。',
    '三年不蜚，蜚将冲天，三年不鸣，鸣将惊人。',
    '蜚：飞。比喻长期退隐，无所作为。',
    '也须知俺这三年五载，看看衰迈，还有甚精金响钞，暗暗藏埋。',
    '三、五：表示大概数量；载：年。指多年。',
    '苌弘死于蜀，藏其血，三年而化为碧。',
    '指忠心不泯。',
    '于是隐居教授，三征七辟皆不就。',
    '三、七：泛指多次；征、辟：征召，指朝廷召举布衣之士授以官职。形容朝廷多次征召选拔。',
    '聊欲弦歌，以为三径之资可乎？',
    '三径：所说汉代隐士蒋诩在房前曾开三条小径，后人因以三径代称住宅庭院。比喻筹集隐居住所的费用。',
    '舜一徙成邑，再徙成都，三徙成国。',
    '形容圣人到处都受到百姓的拥戴。同“三徙成都”。',
    '舜避丹朱，又不愿众聚，故三度逃走，移徙避之。百姓慕德，从者十万，所居之处，自成都邑。',
    '相传舜三度迁移，百姓慕德而从，所至处自成都邑。形容圣人到处都受到百姓的拥戴。',
    '又想这样又想那样，犹豫不定。常指不安心，不专一。',
    '季文子三思而后行。',
    '三：再三，表示多次。指经过反复考虑，然后再去做。',
    '言与三人结怨则仇恨集身，难以免祸。',
    '吴师大北。越之左军右军，乃遂涉而从之，又大败天没。又郊败之。三战三北，乃至于吴。',
    '北：败逃。打三仗，败三次。形容屡战屡败。',
    '故楚南公曰：‘楚虽三户，亡秦必楚’也。',
    '三户：几户人家；亡：灭。虽只几户人家，也能灭掉秦国。比喻正义而暂时弱小的力量，有消灭暴力的必胜信心。',
    '三折肱，知为良医。',
    '几次断臂，就能知道医治断臂的方法。后比喻对某事阅历多，富有经验，成为内行。也指高明的医道。',
    '三折肱知为良医。',
    '肱：手臂。几次断臂，就能懂得医治断臂的方法。后比喻对某事阅历多，自能造诣精深。',
    '三折股为良医。予五升词场，四遭掎摭，是以窃知乎文则。',
    '比喻对某事阅历多，富有经验，自能造诣精深。',
    '几次断臂，就能懂得医治断臂的方法。后比喻对某事阅历多，富有经验，自能造诣精深。',
    '晋大夫三拜稽首曰：‘君履后土而戴皇天，皇天后土实闻君之言，群臣敢在下风。’',
    '指封建社会进见帝王及祭拜祖先的大礼。',
    '比喻人少的敌不过人多的。',
    '三拳两脚，和大虫敌斗，把大虫登时打死了。',
    '有他娘子将小人告到官中，三推六问，吊拷绷扒，打的小人受不过，只得屈招了。',
    '推：推究；问：审问。旧时指反复审训。',
    '金丹舍利同仁义，三教元来是一家。',
    '三教：指儒教、道教、佛教；一体：一家。旧时认为三教形式不同，但同是一个本源。',
    '（梁武）帝问三教九流及汉朝旧事，了如目前。',
    '故时人谓之三无坐处，谓宰相、御史及员外官也。',
    '坐处：坐位。本指宰相、御史、员外官员太多，没有办公的地方可坐。后泛指官员太多，人浮于事。',
    '这果真是三日不弹，手生荆棘。',
    '三天不弹琴，手就象长了荆棘那样不灵活。比喻一停止练习，技艺就会生疏。',
    '过江积年，恒大饮酒，常经三日不醒。时人谓之三日仆射。',
    '仆射：古代官名。旧指沉缅于饮酒的人。',
    '三日入厨下，洗手作羹汤。未谙姑食性，先遣小姑尝。',
    '古代风俗，新娘结婚三日后到厨房做饭。借指初入社会或刚任职。',
    '景宗谓所亲曰：‘今来扬州作贵人，动转不得，路行开车幔，小人辄言不可。闭置车中，如三日新妇。遭此邑邑，使人无气。',
    '旧时过门三日之新妇，举止不得自专。因以喻行动备受拘束者。',
    '佛法不是小事，老僧昔在蒙马大师一喝，直得三日耳聋眼黑。',
    '形容受到强烈的震动。',
    '以其上殿进呈，曰取圣旨；上可否讫，云领圣旨；退谕禀事者，曰已得圣旨也。',
    '用来讽刺庸禄低能的大官。',
    '三旬九遇食，十年著一冠。',
    '旬：十天叫一旬。三十天中只能吃九顿饭。形容家境贫困。',
    '绸缪束薪，三星在天。',
    '指新婚。',
    '绸缪束楚，三星在户。',
    '表示新婚之喜。',
    '三星：原指明亮而接近的三颗星，也指福星、禄星、寿星三个神仙。指有福、禄、有寿，命运好。',
    '老娘也不消得三智五猜，只一智便猜个十分。',
    '比喻用尽心思，多方猜测。',
    '四人者（陈象舆、胡旦、董俨、梁灝）日夕会昌言第。京师为之语曰：‘陈三更，董半夜’。',
    '一夜分为五更，三更是午夜十二时。指深夜。',
    '第一殿秦广大王即差鬼使催请陛下，要三曹对案。',
    '指审问对质。',
    '子在齐闻《韶》，三月不知肉味。',
    '三个月之内吃肉不觉得有味道。比喻集中注意力于某一事物而忘记了其它事情。也借用来形容几个月不吃肉。',
    '常言‘同声相应，同气相求’，自有一班无赖子弟，三朋四友，和他擎鹰放鹞，驾犬驰马，射猎打生为乐。',
    '泛指各种朋友。',
    '指三、五天。',
    '行太尉事节乡侯熹三世在位，为国元老。',
    '元老：资格最老，声望最高的老臣。原指受三世皇帝重用的臣子。现在用来指在一个机构里长期工作过的资格老的人。',
    '以之为不辨是非黑白的典实。',
    '当尧之时，皋陶为士。将杀人，皋陶曰：‘杀之三。’尧曰：‘宥之三。’故天下畏皋陶执法之坚，而乐尧用刑之宽。',
    '宥：赦罪。形容断案慎重。',
    '三杯两盏淡酒，怎敌他、晚来风急。',
    '形容饮用少量的酒。',
    '可不道‘三杯和万事，一醉解千愁。’',
    '和：缓和。指饮酒可以解脱愁闷消除烦恼。',
    '张千，可不道：‘三杯和万事，一醉解千愁。’孩儿，我且不吃，一发等你吃了这钟，凑个三杯，可不好那 。',
    '指饮酒可以消除烦恼，解脱愁闷。',
    '三杯通大道，一斗合自然。',
    '三杯：指饮了三杯酒；大道：宽广的道路。三杯酒下肚，可达理想境界。形容旧时文人因政治上不得意，靠饮酒来安慰自己，自我陶醉。',
    '三次张榜，广求意见，再作最后决定。极言行事慎重。',
    '朝士掌建邦外朝之法。左九棘，孤卿大夫位焉，群士在其后；右九棘，公侯伯子男位焉，群吏在其后；面三槐，三公位焉，州长众庶在其后。',
    '中国周代朝廷种三槐九棘，公卿大夫分坐其下，后因以“槐棘”指三公或三公之位。',
    '她靸着鞋子，三步两脚赶到侧铺的跟前。',
    '快速行走的样子。',
    '那巡捕得了这句话，立刻三步并做二步，急忙跑了出来。',
    '形容快步前进的样子。',
    '心重十二两，中有七孔，三毛，盛精汁三合，主藏神。',
    '指心思，心机。',
    '嫌我不好，谁叫你们瞎了眼，三求四告的，跑了我们家做甚么去了？',
    '指再三求告。',
    '洞庭潇湘意渺绵，三江七泽情洄沿。',
    '泛指江河湖泽。',
    '取玉甚难，越三江五湖，至昆仑之山，千人往，百人反；百人往，十人反。',
    '①指东南方的三条江与太湖流域一带的湖泊。②江河湖泊的泛称。',
    '烧卖匾食有何难，三汤两割我也会。',
    '泛指烹饪之事。也指各种肴馔。',
    '众人祭毕，陈敬济下来还礼，请去卷棚内三汤五割管待出门。',
    '泛指烹饪之事。也指各种肴馔。同“三汤两割”。',
    '一重一掩藏山坞，三沐三熏屏世尘。',
    '再三沐浴熏香。表示郑重或虔敬。亦作“三沐三熏”。',
    '重归畎亩，更须三沐三薰。',
    '指各种波折。',
    '方将坐足下，三浴而三熏之，听仆之所为，少安无躁。',
    '浴：沐浴。再三薰香、沐浴。表示以礼待人，对人尊重。也表示郑重其事。',
    '方将坐足下，三浴而三薰之，听仆之所为，少安无躁。',
    '多次沐浴并用香料涂身。这是我国古代对人极为尊重的一种礼遇。同“三衅三浴”。',
    '比至，三衅三浴之，桓公亲逆之于郊，而与之坐而问焉。',
    '衅：以香涂身。多次沐浴并用香料涂身。这是我国古代对人极为尊重的一种礼遇。',
    '指非常清白。',
    '但有些八难三灾，一心斋戒。',
    '比喻小孩生来多病。也形容经常遭遇不幸。',
    '谁家也有三灾六难哩！互相帮助嘛！',
    '比喻小孩生来多病。也形容经常遭遇不幸。同“三灾八难”。',
    '比至，三衅三沐之，桓公亲逆之于郊，而与之坐而问焉。',
    '①多次沐浴并用香料涂身。这是我国古代对人极为尊重的一种礼遇。同“三衅三浴”。②表示虔敬。③比喻栽培，提携。',
    '三牲五鼎供朝夕，须胜似啜菽并饮水。',
    '原形容祭品丰盛。现形容食物丰富美好。',
    '四爷赶上一步，就势按倒，解他腰带，三环五扣的捆了一回。',
    '形容捆绑结实。',
    '想这新年大节，老爷衙门里，三班六房，那一位不送帖子来？',
    '三班：指皂、壮、快班，均为差役；六房：指吏、户、礼、兵、刑、工房，均为书办胥吏。明、清时州县衙门中吏役的总称。',
    '平昔在三瓦两巷行走耍子，捣子都认的。',
    '旧指富家子弟寻欢作乐的地方。同“三瓦两舍”。',
    '瓦、舍：宋、元时指妓院及各种娱乐场所。旧指富家子弟寻欢作乐的地方。',
    '衙内你不晓得，他是清白人家女儿，那肯同那三瓦四舍的奉迎。',
    '宋代对妓院、茶楼、酒肆及其他娱乐场所的总称。',
    '三生：佛家指前生、今生、来生；幸：幸运。三世都很幸运。比喻非常幸运。',
    '三生石上旧精魂，赏月吟风不要论。惭愧情人往相访，此生虽异性长存。',
    '佛教故事，唐代李源与高僧圆泽禅师相约来世相见的故事。借指前世姻缘，来世重新缔结。',
    '三荆欢同株，四鸟悲异林。',
    '比喻兄弟之间重新和好。',
    '三男两女，孙息盈前，何为坐自殚竭？',
    '生有三个儿子，两个女儿。指人儿女两全。',
    '德武已于岭表娶尔硃氏为妻，及遇赦得还，至襄州，闻裴守节，乃出其后妻，重与裴合。生三男四女。',
    '泛指子女众多。',
    '一言半语恩情，三番两次丁宁。',
    '指屡次，多次。',
    '你将书呈三番两次调发小生到此，萧条旅馆，个月期程，不蒙放参。',
    '番：遍数。一再，多次。',
    '三、四：指次数之多；番、复：反复。变化无常或反复多次。',
    '先帝焦于求治，刻于理财，渴于用人，骤于行法，以致十七年之天下，三番四覆，夕改朝更。',
    '三、四：指次数之多；番、覆：反复，翻悔。形容变化无常，反复多次。',
    '到老没个儿女，设或三病四痛，没个贴体亲人，那时要茶无茶，要饭没饭，便是活受地狱，何须定要变得牛马！',
    '指病痛很多。',
    '三百六十行中人，尽有狼心狗行，狠似強盜之人。',
    '指长期以咸菜度日，生活清贫。齏，咸菜。三百瓮，极言其多，一时吃不完。',
    '旧传一贫士死，见阴更，为言‘当年生，汝有三百瓮齑禄未尽。’',
    '瓮：陶制的盛器；齑：咸菜。指长期以咸菜度日，生活清贫。',
    '三皇：伏羲、神农、黄帝；五帝：少昊、颛顼、帝喾、尧、舜。原为传说中我国远古的部落酋长。后借指远古时代。',
    '少正卯在鲁，与孔子并，孔子之门三盈三虚，唯颜渊不去。',
    '盈：满。虚：空。指孔子的满门弟子，被少正卯讲学所吸引，多次离开孔子之门。形容讲学效果好，影响大。',
    '曾子曰：‘吾日三省吾身，为人谋而不忠乎？’',
    '省：检查、反省；身：自身。原指每日从三个方面检查自己，后指多次自觉地检查自己。',
