    '凡响：平凡的音乐。形容事物不平凡，很出色。',
    '《礼》，父母之仇，不同戴天。',
    '不从流俗。',
    '流俗：流行的习俗。与世俗习气不同。形容品德高尚。',
    '老兄明白，弟半生书剑飘零，寄食江湖，囊中不名一文。',
