    '指不局限于一种规格或一个格局。',
    '通有盗铸钱之罪，景帝考验，通亡，寄死人家，不名一钱。',
    '吐：倾诉；快：痛快。不说出来就不痛快。',
    '人亦有言，柔则茹之，刚则吐之。维仲山甫，柔亦不茹，刚亦不吐，不侮矜寡，不畏强御。',
    '形容人正直不阿，不欺软怕硬。',
    '大则以訏谟排祸难，小则以谠正匡过失，内不虑身计，外不恤人言，古人所难也。',
    '不要舍不得指点教导。',
    '恰好听到树上黄莺巧啭，就对拜住道：‘老夫再欲求教，将《满江红》调赋“莺”一首，望不吝珠玉，意下如何？’',
    '吝：舍不得。不要舍不得好的东西。恳切希望别人给予指教的谦词。',
    '但我相信倘有请益的时候，先生是一定不吝赐教的。',
    '吝：吝惜；赐：赏予；教：教导，教诲。不吝惜自己的意见，希望给予指导。请人指教的客气话。',
    '兄如不吝金玉，即求小小做一套，待小弟步韵和将去，便无差失了。',
    '吝：吝惜。不吝惜宝贵美好的东西。',
