    '老婆也辛酸，陪着掉了若干的泪，饶着说上些不咸不淡的话。',
    '绍兴二十八年：‘敢问大众，因甚不觉？岂不见道，不哑不聋，不做大家公。’',
    '算啦，大家不哼不哈，就当没有这码事，回去吧！',
    '不言语，该说而不说。',
    '然此书与《宝箓天章》，不啻云泥之别。',
    '不啻：无异于。无异于从云天之上到地上的泥土的距离。比喻差别极大',
    '贱妾水冰心，多蒙公子云天高谊，从虎口救出，其洪恩大德，不啻天地父母。',
    '不啻：无异于。无异于天地之别。比喻差别极大。',
    '吴有吴音，越有越语，相去不啻天渊。',
    '不啻：无异于。渊：深潭。无异于从云天之上到深潭之底。比喻差别极大。',
    '不喑不聋，不成姑公。',
    '姑公：婆婆，公公。指作为一家之主，对下辈的过失要能装糊涂。',
    '抱不器之器，成乎有用之用。',
    '不器：不象器物那样只有某一方面的作用，即不同于一般的才能。指具有全才的人。',
    '老赵州十八上便解破家散宅，徒为戏论，虽然如是，不因一事，不长一智。',
