    '西门庆不因不由，信步走入里面观看。',
    '犹言无意之中。',
    '比舍先炊已，呼鸿及热釜炊。鸿曰：‘童子鸿不因人热者也。’灭灶更燃火。',
    '因：依靠。汉时梁鸿不趁他人热灶烧火煮饭。比喻为人孤僻高傲。也比喻不依赖别人。',
    '子曰：不在其位，不谋其政。',
    '不担任这个职务，就不去过问这个职务范围内的事情。',
    '不堪：经不起。形容力量薄弱，经不起一击。也形容论点不严密，经不起反驳。',
    '指形象丑恶，使人看不下去。',
    '二词哗于市井，虽儿女子初学言者，亦知歌之，但淫艳亵狎，不堪入耳。',
    '堪：可，能；入耳：听。指说的话使人听不进去（多指脏话）。',
    '忧：愁苦。不能忍受那样的愁苦。',
    '柳曰：‘月香姊情词俱哀，令人不堪卒读。’竹曰：‘月香之志亦大可悲已。’雪香闭目不语，泪落衫袖。',
    '不堪：不能；卒：完毕，结束。形容文章写得凄惨悲苦，令人心酸，不忍读完。也指文章粗劣，使人不肯读下去。',
    '堪：可以忍受；回首：回顾，回忆。指对过去的事情想起来就会感到痛苦，因而不忍去回忆。',
    '这时的乌云已经弹尽粮绝，几小时以前乌合起来的兵马，现在是丧魂失魄，溃不成军，大有不堪收拾之状了。',
    '堪：可；收拾：整理，整顿。无法整顿。',
    '其菲薄揶揄，不堪视听。',
    '堪：可，能。言辞污秽，行为卑劣，不能看与听。',
