    '然则如之何而可也？曰：不塞不流，不止不行。',
    '指对佛教、道教如不阻塞，儒家学说就不能推行。现比喻不破除旧的、坏的东西，新的、好的东西就建立不起来。',
    '然则如之何而可也？曰：不塞不流，不止不行，人其人，火其书，庐其居。',
    '比喻只有破除旧的、错误的东西，才能建立新的、正确的东西。',
    '还在半个月前，张腊月隐隐听说，南二社有个吴淑兰的妇女队长，在不声不吭地跟她暗赛。',
    '指不说话；不出声。',
    '你们只想自己的爱人像旧式妇女一样，百依百顺，不声不气，来服侍你们。',
    '子贡既与卫将军文子言。适鲁，见孔子曰：‘卫将军文子问二三子之于赐，不壹而三焉。赐也辞，不获命；以所见者对矣。’',
    '指再三；多次。',
