    '以为士人不齿，放弃终身。',
    '齿：象牙齿一样排列。不能列于人类。指被人看不起。',
    '人生各自有穷通，世事宁论拙与工。裹马革心空许国，不龟手药却成功。早朝玉勒千门雪，夜坐蓬窗万壑风。借得奇书且勤读，小儿能续地炉红。',
    '①使手不冻裂的药。②比喻微才薄技。',
    '［米芾］又不能与世俯仰，故从仕数困。',
    '与时迁徙，与世偃仰。',
    '偃仰：俯仰。指没有一定的主张，随大流。',
    '圣人不凝滞于物，而能与世推移。',
    '随着世道的变化而变化以合时宜。',
    '自以为无患，与人无争也。',
    '世：世人，周围的人。不跟社会上的人发生争执。这是一种消极的回避矛盾的处世态度。',
    '世：世人，周围的人。不跟社会上的人竞争。这是一种消极的回避矛盾的处世态度。',
    '岂若卑论侪俗，与世沉浮而取荣名哉。',
    '然不能与世浮沉。平视贵要，若无人，故所至龃龉。',
    '和世界一起永远存在。多用于赞颂人的功绩和不朽的精神品德。',
    '仆适自念，以金盆玉碗贮狗矢，真无颜出见同人，行将遁迹山林，与世长辞矣。',
    '辞：告别。和人世永别了。指去世。',
    '与社会上的人们隔离，断绝来往。形容隐居或人迹不到的极偏僻地方。',
    '邈哉许公，执真履贞，辞尧天下，抱朴隐形，川停岳峙，澹泊无营，栖迟高山，与世靡争。',
    '和世上的人没有争执。形容脱俗拔尘的达观态度。',
    '取诸人以为善，是与人为善者也。故君子莫大乎与人为善。',
    '与：赞许，赞助；为：做；善：好事。指赞成人学好。现指善意帮助人。',
    '施主莫恼。‘与人方便，自己方便。’你就与我说说地名如何？我也可解得你的烦恼。',
    '与：给。给予他人各种便利',
    '罢罢罢，自古道与人方便，自己方便。看你这二个妇人，也不是已下人家的。',
    '给他人便利，他人也会给自己便利。',
    '不跟社会上的人发生争执。这是一种消极的回避矛盾的处世态度。',
    '无忤逆之言，无不合之义。',
    '忤：抵触。没有和人相抵触的时候。指与人相处和善。',
    '跟大家不一样。',
    '念蒙圣主恩，荣爵与众殊。',
    '殊：不同。跟大家不一样。指人的性格、行为等不一般或事物很有特色。',
    '家兄一想，这件事倘要认真办起来，与受同科，不但姓文的担不起，就是老哥亦落不是的。',
    '行贿和受贿的人受到同等的处罚。',
    '为人之所为者，人亦无疵焉，是之谓与人为徒。成而上比者，与古为徒。',
    '徒：同类的人。和古人作朋友。',
    '君：尊称对方；胜：胜于。和您谈了一会儿，受益比读了十年书还多。形容与别人交谈的时间虽短，收获却很大。',
    '其左执鞭弭，右属橐腱，以与君周旋。',
    '周旋：追逐驰逐。奉陪你较量较量。指表面礼貌实际不客气',
    '西北荒中，有玉馈之酒，酒泉注焉，上有玉樽，取一樽，一樽复生，与天地同休，无干时。',
    '登昆仑兮食玉英，与天地兮同寿，与日月兮同光。',
    '寿：寿命。与天地一样长久。比喻寿命很长',
    '汝年渐长，足知善恶，当每思刻厉，奉朝廷为心，爵秩自然与年俱进。',
    '与：跟，和。随着时间一天天地增长。形容不断增长。',
    '涉冬浸剧，与日俱增。',
    '耳目唯有聪察，神彩弥加精明。颜与日而俱新，智将年而共远。',
    '新：新面貌。随着时间一同更新。',
    '瘀积之血，牢不可拔，新生之血，不得周灌，与日俱积，其人尚有生理乎。',
    '二子位既成立，夫人因得冥心斋静，累感真灵，修真之益，与日俱进。',
    '与：跟，和。随着时间一天天地进步。形容不断进步或提高。',
    '推此志也，虽与日月争光可也。',
    '争：竞争。与太阳、月亮比光辉。常用以称赞人的精神、功业伟大。',
    '与天地兮比寿，与日月兮齐光。',
    '与太阳、月亮的光芒相当。常用以称赞人的精神、功业伟大。',
    '身直为闺閤之臣，宁得自引深藏于岩穴邪！故且从俗浮湛，与时俯仰，以通其狂惑。',
    '俯仰：抬起落下。随着社会潮流或进或退。',
    '损益盈虚，与时偕行。',
    '变通趋时。',
    '吾不凝滞于物，与时推移。',
    '陶冶世俗，与时浮沉，吾不如子；论王霸之余策，览倚仗之要害，吾似有一日之长。',
    '浮沉：在水中忽上忽下的漂游。指随当时的世俗或进或退。',
    '故曰‘上失其道，民散久矣’。而欲绳之以古行刑，投之以残弃，非所谓与时消息者也。',
    '指事物无常，随时间的推移而兴盛衰亡。消，消亡。息，孳生。',
    '白刃合，流矢接，步血属肠，与死扶伤。',
    '与：援助；扶：扶助。援助要死的人，辅助受伤的人',
    '海内虚耗，户口减半，光知时务之要，轻徭薄役，与民休息。',
    '古之人与民偕乐，故能乐也。',
    '原指君王施行仁政，与百姓休戚与共，同享欢乐。后泛指领导与群众一起游乐，共享幸福。',
    '今王四猎于此，百姓闻王车马之音，见羽旄之美，举欣欣然有喜色而相告曰：‘吾王庶几无疾病与，何以能田猎也？’此无他，与民同乐也。',
    '又念有天下者未见不监古而治，弃古而乱也。岂上位者务在镇静，不须与民同忧也？',
    '与人民共患难。',
    '朕嘉唐虞而乐殷周，据旧以鉴新，其赦天下与民更始。',
    '更始：重新开始。原指封建帝王即位改元或采取某些重大措施。后比喻改革旧状，建立新秩序。',
    '丞相衔奉国威，为民除害，元恶大憝，心当枭夷。',
    '替百姓除祸害。',
    '宝夤作乱，以亮为黄门侍郎。亮善处人间，与物无忤。及宝夤败，从之者遇祸，唯亮获全。',
    '指处世态度随和，与人无所抵触。',
    '湖少有节操，笃志于学，专精讲习，不干时务，与物无竞，好以德义服人。',
    '指与世人无所争竞。',
    '与狐议裘，无时焉可。',
    '裘：毛皮。跟狐狸商量要剥它的做大衣。比喻谋求有损对方切身利益的事，对方是绝对不会答应的。',
    '周人有爱裘而好珍羞，欲为千金之裘而与狐谋其皮，欲具少牢之珍而与羊谋其羞，言未卒，狐相率逃于重丘之下，羊相呼藏于深林之中。',
    '谋：商量。跟狐狸商量要剥它的皮。比喻跟恶人商量要他放弃自己的利益，绝对办不到。',
    '谋：商量；羞：珍羞，精美的食物。跟羊商量要它的肉。比喻跟恶人商量要他放弃自己的利益，绝对办不到。',
    '身与草木俱朽，声与日月并彰。',
    '古来贤豪，不遭与运，埋光铲采，与草木俱腐者，可胜咤哉！',
    '虽然，自今观之，孔北海、盛孝章犹在世，而向之讥评者与草木同腐久矣。',
    '今乘万民之力而反为残贼，是为虎傅翼，曷为弗除。',
    '翼：翅膀。替老虎加上翅膀。比喻帮助坏人，增加恶人的势力。',
    '谋：商量。跟老虎商量要剥它的皮。比喻跟恶人商量要他放弃自己的利益，绝对办不到。',
    '人生七十鬼为邻，已觉风光属别人。',
    '邻：邻居。与鬼做邻居。形容离死不远了。',
    '不光彩、见不得人的事在外面到处传扬。',
    '长相丑陋的人经常做出一些离奇古怪的事来为难别人。',
    '相貌丑陋的人。',
    '案车骑将军义真，凶忍之性，爰自稚弱，咸阳之酷，丑声远播。',
    '声：名声；溢：外流。丑恶的名声到处传播。形容臭名远扬。',
    '咸阳之酷，丑声远播。',
    '坏名声传播得很远。',
    '丑媳妇免不得见公姑，缅焉呈面，公姑具眼，是妍是丑，其必有以区别之也。',
    '公姑：公婆。比喻害怕见人而不得不见人。',
    '常言道：‘丑媳妇少不得见公婆。’只得脱袍解带，免冠徒跣，跪于门外。',
