    '丑媳妇总得要见公婆的，索性我自己招罢。',
    '比喻隐藏不住，总要露相。',
    '而影响剿说，盖头窃尾，如贫人借富人之衣，庄农作大贾之饰，极力装作做，丑态尽露。',
    '丑恶的形态彻底暴露出来。',
    '贾琏亦丑态毕露。',
    '毕：完全。丑恶的形态彻底暴露。',
    '他们那有甚么心事！不过因明日就要放榜，得失心未免过重，以致弄的忽哭忽笑，丑态百出。',
    '各种丑恶的样子都表现出来了。',
    '丑类恶物，顽嚣不友。',
    '指坏人。',
    '赵文华陪着严嵩，抹粉脸席前趋奉，丑腔恶态，演出真鸣凤。',
    '卑贱的声调，丑恶的样子。',
    '不中听的话先说出来以免发生矛盾。',
    '信者，诚也，专一不移也。',
    '今此数家之言，所以兼包大小之义，岂可偏绝哉。若必专己守残，党同门，忌道真，违明昭，失圣意，以陷于文吏之议，甚为二三君子不取也。',
    '固执己见，抱残守缺。指囿于派系、门户之成见而不能通权达变。',
