    '跋扈：霸道，不讲理。形容把持大权，独断专行。',
    '会依言，即遣人赍表进赴洛阳，言邓艾专权恣肆，结好蜀人，早晚必反矣。',
    '形容把持大权，独断专行。',
    '朕久闻其专权误国，今仙机示朕，朕当即为处分，卿不可泄于外人。',
    '坏人专权会坑害国家。',
    '帝少而聪慧，知冀骄横，尝朝群臣，目冀曰：‘此跋扈将军也。’',
    '众怒难犯，专欲难成，合二难以安国，危之道也。',
    '专欲：个人欲望。单凭个人意愿，事情难以办成。',
    '专门用于指定项目的钱款专项使用。',
    '不问生产，不交宾客，专精覃思，无所不通。',
    '覃：深入地。精心专研，深入思考。',
    '左右笔力如川之方至，无使楚汉专美于前，乃副下交之望。',
    '专美：独享美名。指先于别人独享美名',
    '寒食只数日间，得且住为佳耳。',
    '且：暂且；佳：好。还是暂且住在这里好。多用以劝留客人住下。',
    '毕竟史进与三个头领怎地脱身，且听下回分解。',
    '分解：叙述。宋元以来章回小说结束语。',
    '如来日魏兵到，锐气正盛，不可便迎，且战且走。',
    '且：指两件事同时并进；走：逃跑。一边作战，一边逃跑。',
    '北军奋勇，四门杀出，我军且战且退，诱北军四散离城。',
    '一边作战，一边退却。',
    '融殊不平，谓曰：‘仆出於扶桑，入於汤谷，照耀天下，谁云不知，而卿此问？’昭略云：‘不知许事，且食蛤蜊。’',
    '指姑且置之不问。',
    '世上无难事，人心自不坚。',
    '天下没有难事。',
    '祖师道：‘世上无难事，只怕有心人。’',
    '指只要肯下决心去做，任何困难都能克服。',
    '泛指延续的各代。',
    '指今生、来世以至永世。',
    '又有一幅对联，写的是‘世事洞明皆学问，人情练达即文章。’',
    '洞：洞悉，了解；明：明白。对于人世间的各种事情，都看得透彻明白。',
    '今世事纷扰，复有瓦解之势矣。',
    '纷扰：纷乱。形容社会情况混乱。',
    '在中国及其执政党内，干部中大山头不明显，但小山头小圈子则处处存在，世人皆知。',
    '世人：所有人。指很多人都知道。',
    '林家虽贫到没饭吃，也是世代书香人家，断不肯将他家的人丢给亲戚，落的耻笑。',
    '久闻公世代簪缨，何不立于庙堂，辅佐天子，乃区区作相府门下一吏乎？',
    '你不要以～衡量穷人，以为他们一点骨气也没有。',
    '世人的庸俗见解。',
    '子之所言，世俗之言也。',
    '指当时社会上流行的一般人的言论、说法。含贬义。',
    '原指与现实社会隔绝、生活安乐的理想境界。后也指环境幽静生活安逸的地方。借指一种空想的脱离现实斗争的美好世界。',
    '世家子弟富人或斗鸡走马狗，弋猎博戏，乱齐民。',
    '世家：古代称世代显贵的家族。指门第高，世代做官人家的子弟。',
    '殷仲文风流儒雅，海内知名，世异时移，出为东阳太守。',
    '世、时：社会、时代。异、移：不同、变化。社会变化了，时代不同了。亦作“时移世改”、“时移世异”、“时移俗易”、“时异事殊”。',
    '南亩耕，东山卧，世态人情经历多。',
    '指社会风尚和为人处世之道。',
    '世：社会。比喻社会上人情淡薄。',
    '他宿世是夫妻，何须苦折离？世情看冷暖，人面逐高低。',
    '世情：社会人情；人面：人的脸色。社会人情从人的态度的冷淡或热情可以看出来，人的脸色好坏因对方的地位高低而不同。',
    '世扰俗乱，灾害不绝，遂以破国亡身灭嗣。',
    '社会骚乱，风气败坏。',
    '王言如丝，其出如纶。',
    '后中书省代皇帝草拟诏旨，称为掌丝纶。指父子或祖孙相继在中书省任职。',
    '为人处世的道理。',
    '又前都尉浩周劝君遣子，乃实朝臣交谋，以此卜君，君果有辞，外引隗嚣遣子不终，内喻窦融守忠而已，世殊时异，人各有心。',
    '世、时：时代；殊、异：不同，差异。指时代不同了。',
    '世济其美，后世承前世之美。',
    '指后代继承前代的美德。',
    '大道之行也，天下为公。选贤与能，讲信修睦。故人不独亲其亲，不独子其子……是故谋团而不兴，盗窃乱贼而不作，故外户而不闭，是谓大同。',
    '大同：我国古代一些思想家心目中的理想社会。指没有压迫、剥削的平等、自由的社会景象。',
    '世禄之家，鲜克由礼。',
    '从昔勇断抛名后，世路荣枯见几回。',
    '世路：生活道路。世间人事经历的兴盛和衰败。',
    '家山泉石寻常忆，世路风波子细谙。',
    '世路：生活道路；风波：各种矛盾。指生活中充满各种矛盾。',
    '刑罚世轻世重，惟齐非齐，有伦有要。',
    '世：当世。意思是刑罚要根据当时社会情况确定轻重严宽。',
    '远：久远；陈：陈旧。年代已经相隔很久远了。',
    '所关于世道人心者甚钜，是以载籍虽繁，莫可废也。',
    '泛指社会的道德风尚和人们的思想情感等。',
    '世道日交丧，浇风散淳源。',
    '世道：社会风气；日：日益；衰：衰败。社会风气一天天地败落。',
    '世道：社会风气；浇漓：指人情淡薄。指社会上人情刻薄冷淡。',
    '正是世间无难事，只怕有心人。',
    '只要有决心，世间没有难住人的事。',
    '卖药修琴归去迟，山风吹尽桂花枝。世间甲子须臾事，逢著仙人莫看棋。',
    '世间：人世间；甲子：六十年；须臾：片刻。指六十年是非常短暂的。形容时间流逝得非常快。',
    '世风：社会风气；古：指古朴。社会风气不像古时那样朴实。',
    '我国世风日下，亲戚尚如此，况友乎？',
    '指社会风气一天不如一天。',
    '若论心里的丘壑泾渭，颇步熙凤的后尘。',
    '丘壑：山丘与坑谷；泾渭：泾水和渭水，比喻是非。比喻对事物的高低是非分得清。',
    '故乃建秋山之功，享不訾之禄。',
    '比喻功绩伟大。',
    '楚王轼怒蛙，以昆虫之敢死；丙吉问牛，恐阴阳之失时。',
    '看到牛的异常想起天气变化，赞扬官员关心百姓疾苦。',
    '左辅右弼，前疑后承。一日万机，业业兢兢。',
    '业业矜矜，若履冰谷，思与亿兆，同此维新。',
    '业峻鸿绩：即业峻绩鸿，功业高，成绩大。',
    '功业高，成绩大。',
    '业精于勤，荒于嬉；行成于思，毁于随。',
    '业：学业；精：精通；于：在于；勤：勤奋。学业精深是由勤奋得来的。',
    '窃伏自念，业绍箕裘，家藏坟索，插架之收储，趋庭之问答，其于文献盖遮几焉。',
    '绍：继承；箕：畚箕；裘：兽皮袄。比喻能继承父祖的事业。',
    '荒：荒废。贪恋玩耍就会荒废学业',
    '日月欲明，浮云蔽之；河水欲清，沙土秽之；丛生欲脩，秋风败之。',
    '兰：兰草；秀：开花；败：衰败。兰草要开花，但秋风使之凋谢。比喻好人做好事而遭坏人陷害。',
    '煤矿的空中索道，越过了丛山峻岭。',
    '丛：聚集；竣：高大。无数高大险峻的山岭',
    '指即使轻而小的物件，装载多了也可以使车轴折断。',
    '为渊驱鱼者，獭也；为丛驱爵（雀）者，鹯也；为汤武驱民者，桀与纣也。',
    '比喻不行善政，等于把老百姓赶到敌人方面去。',
    '使木板子东一下，西一下，撺这一二百下子。',
    '指做事无计划。比喻行动漂忽无定。',
    '慨自唐虞成周之际，爰宅四时，东作西成，岁月时日，水火土谷，历世不易。',
    '东作：指春耕；西成：指秋收。指春种秋熟。',
    '她还是馋猫儿似的东偷西摸。',
    '指暗中干不正当的事。',
    '愁高怅远。身世事，但难准。况禁他，东兔西乌相逐，古古今今不问。',
    '兔、乌：古代神话传说中说，月亮里有玉兔，太阳里有三足金乌，所以用乌、兔代表日月。月亮东升，太阳西落。表示时光不断流逝。',
    '近日治河，乃遏之使不得北，而南入于淮，以便运耳。南行非河之本性，东冲西决，率无宁岁。',
    '形容洪水四处冲决泛滥。',
    '他带着一班人巧妙地摔开了追击的敌人，东冲西撞，想再追上大队。',
    '指无把握地四处奔走寻找。',
    '曹操见云东冲西突，所向无前……奋然大怒，自领左右将士来赶赵云。',
    '指四处冲锋突击。',
    '东飞伯劳西飞燕，黄姑织女时相见。',
    '劳：伯劳。比喻情侣、朋友离别。',
    '张华见褚陶，语陆平原曰：‘君兄弟龙跃云津，顾彦先凤鸣朝阳，谓东南之宝已尽，不意复见褚生！’',
    '指东南地区的杰出人才。',
    '筠曰：‘陆平原东南之秀，王文度独步江东，吾得比踪昔人，何所多恨。’乃欣然就职。',
    '指东南地方的杰出人才。',
    '东南之美，曩惟延州；显允陆生，于今鲜俦。',
    '指东南人物中之佼佼者。',
    '金朝那解番狼将，血溅东南半壁天。',
    '半壁：半边。指长江中下游及其以东、以南的半边江山。',
    '东南之美者，有会稽之竹箭焉。',
    '比喻优秀人才。',
    '乐府诗《孔雀东南飞》',
    '比喻夫妻分离。',
    '东面望者，不见西墙；南乡视者，不睹北方，意有所在也。',
