    '及至东园秘器，珠襦玉柙，豫以赐贤，无不备具。',
    '指皇室、显宦死后用的棺材。',
    '踰东家墙而搂其处子，则得妻；不搂则不得妻；则将搂之乎？',
    '指邻居的处女。',
    '天下之佳人，莫若楚国；楚国之丽者，莫若臣里；臣里之美者，莫若臣东家之子……然此女登墙窥臣三年，至今未许也。',
    '指美貌女子倾心于男子。',
    '臣闻贫人女与富人女会绩，贫人女曰：‘我无以买烛，而子之烛光幸有余，子可分我余光，无损子明，而得一斯便焉。’',
    '东邻墙壁上透过来的光。表示对他人有好处而对自己并无损害的照顾或好处。',
    '[李甲]口里虽如此说，心中割舍不下，依旧又往外边东央西告，只是夜里不进院门了。',
    '指到处恳求。',
    '王象荩承主母之命，遵依程公条例，东央西浼，托产行寻售主。',
    '指到处恳求请托。',
    '你也光，我也光，东奔西向，我就养遍濮州城，你也难来拦当。',
    '骤然起兵戈，扰攘。卷尘飞，东奔西撞，娇儿拆散知何往？',
    '形容无固定目标，到处乱闯。',
    '钱塘县派差去查过，果然那些狗东奔西窜，践踏田禾。',
