    '他打过多少次败仗，东奔西逃，最后决定了与汉家和好的大计。',
    '跑到东，又逃到西。到处逃窜。同“东逃西窜”。',
    '此中的工作者，刚一动手，必先觉着孤独无助；工具破败，不堪适用，一切技术上的设备，东完西缺。',
    '缺东少西，不完备，短缺。',
    '君乃舍之，蹑屣千里，所谓以郑为东家丘者也。',
    '丘：孔丘。孔子的西邻不知孔子的学问，称孔子为“东家丘”。指对人缺乏认识，缺乏了解。',
    '北郭先生生已老，东家夫子子为恭。',
