    '又来东寻西觅，只恐还在左近，放心不下。',
    '指到处寻找。',
    '东封西款边功多，江淮陆地生洪波，内库马价支垂尽，民因无力官奈何。',
    '封：封爵；款：归顺。东边封爵，西边归顺。指边境罢战，修好言和。',
    '安虽受朝寄，然东山之志始末不渝，每形于言色。',
    '指隐居的念头。',
    '隐居会稽东山，年逾四十复出为桓温司马，累迁中书、司徒等要职，晋室赖以转危为安。',
    '指再度出任要职。也比喻失势之后又重新得势。',
    '悬拟壮猷，东山复起。',
    '卿累违朝旨，高卧东山。',
    '比喻隐居不仕，生活安闲。',
    '原约一到任所差人进京图干此事，谁知所去的，多不得力。我这里好不盼望，不甫能勾回个信来，定是东差西误的。',
    '指出现这样或那样的差池、错误。形容办事不得力。',
    '《史记·吴王濞列传》、《汉书·晁错传》载：汉景帝时，御史大夫晁错被谗，“衣朝衣斩东市。”',
    '为朝臣被杀之典。',
    '东平思王冢在无盐，人传言王在国思归京师，后葬，其冢上松柏皆西靡也。',
    '指人死之后，对故乡的思恋之情亦不泯灭。',
    '潜应坦腹之姿，妙契东床之选。',
    '指佳婿的人选。',
    '他成了总工程师的东床佳婿以来，厂里的那些科长、主任们，对他似乎比过去客气多了。',
    '对女婿的美称。同“东床娇婿”。',
    '闻来觅婿，咸自矜持；唯有一郎在东床上坦腹卧，如不闻。',
    '指女婿。',
    '此人名唤孙绍祖，生得相貌魁梧……贾赦见是世交子侄，且人品家当都相称合，遂择为东床姣婿。',
    '东床娇婿实堪怜，况过青春美少年。',
    '对女婿的美称。',
    '东海龙神差老僧来做媒，招你为东床娇客。',
    '遣门生与王丞相书，求女婿。……门生归白郗曰：‘王家诸郎，亦皆可嘉，闻来觅婿，咸自矜持，惟有一郎在床上坦腹卧，如不闻。’',
    '指为人豁达，才能出众的女婿。是女婿的美称。',
    '东床择对，得凤举之名英；中遘冓宣劳，励鸡鸣之至诚。',
    '指择婿。',
    '三人挤在一个舱角里，看他们的眼睛，偷偷地东张西张的神气。',
