    '只见前面一个人摇摆将来，见张贡生带了一伙家人东张西觑，料他是个要嫖的勤儿没个帮的人，所以迟疑。',
    '惟王不迩声色，不殖货利，德懋懋官，功懋懋赏……东征西夷怨，南征北狄怨。',
    '本指商汤向一方征伐，则另一方人民埋怨他不先来解救自己。后指帝王兴仁义之师为民除害，深受百姓拥戴。',
    '至如出车授钺，东征西讨，孤虚向背，则虽女子之众，可以当于丈夫。',
    '指四面出兵征战讨伐。',
    '但当循分守职，保境睦邻，自无外患。何必东迁西徙，徒取劳瘁。',
    '指四处迁移，漂泊不定。',
    '厉色扬声，东怒西怨。',
