    '指任意指责别人。',
    '姐姐若不见怜，怎样着落妹子死后魂灵，不至东扬西荡。',
    '指飘泊无定。',
    '及至准算与他，又要减你的价钱，准算过，便有几两赢余，要他找绝，他又东扭西捏，朝三暮四，没有得爽利与你。',
    '扭捏作态，不爽快。',
    '嘴唇不停地做怪样而实际并未说话。',
    '你少东扯葫芦西扯瓢，抗旱就抗旱，怎么又发癫，想起去查账了。',
    '说话东扯西拉。',
