    '……纷纷～地向梁三老汉的草棚院奔来劝架。',
    '形容紧急匆忙的样子。',
    '接着这声丢心落意的叫骂，几个铜板，或者几张毛票，被抛在街上了。',
    '形容合意、痛快。',
    '填然鼓之，兵刃既接，弃甲曳兵而走，或百步而后止，或五十步而后止。',
    '形容吃了败仗狼狈逃跑的景象。',
    '盔、甲：头盔和铠甲。跑得连盔甲都丢了。形容打败仗后逃跑的狼狈相。',
    '形容吃了败仗狼狈逃跑的景象。同“丢盔卸甲”。',
