    '乘舆：帝王坐的车。指帝王流亡在外。',
    '宋卫间郑师之在外而乘虚以入其国。',
    '乘：趁着；虚：空隙，弱点。趁着空隙或无人防范而进入。',
    '乘分可图，乘虚可惊，乘乱可取。',
    '乘：趁着；惊：惊吓。趁敌人空虚可以恫吓他。',
    '将至所居，自后垣乘虚而入，径及庭中。',
    '乘：趁。趁着虚弱疏漏的地方进入。',
    '黄龙举起磬击子来，在磬上铿铿锵锵的乱击，协律谐声，乘虚蹈隙。',
    '犹言切中窾窍。比喻叩击中节。',
    '分为奇兵，乘虚迭出，以扰河南。',
    '虚：空虚、弱点。迭：屡次。指军事上向对方没有设防或兵力薄弱的地方进攻。',
    '未尝梦乘车入鼠穴，捣齑噉铁杵，皆无想无因故也。',
    '坐车进入老鼠洞。比喻不合情理，无法办到的事。',
    '卿虽乘车我戴笠，后日相逢下车揖；我步行，君乘马，他日相逢君当下。',
    '乘：坐，驾；笠：斗笠。比喻不因为富贵而改变贫贱之交。',
    '古者大夫乃不徒行，今之贱隶乘轻驱肥。',
    '乘好车，驱良马。形容生活奢华。',
    '乘酒假气，将迫于人，岂近直哉。',
    '乘：就着；假：利用。借着酒醉的气势。',
    '利用空隙或漏洞以等待机会。',
    '趁机会干坏事。',
    '坚壁清野以为体，乘间击瑕以为用，战虽不足，守则有余。',
    '乘：趁，利用；间：间隙；瑕：空隙。钻空子，打击对方薄弱的地方。',
    '伺敌之隙，乘间取利。',
    '乘：利用；间：空隙。利用对方力量薄弱的地方袭击取胜。',
    '然而特怵于天下之士不乐于吾之说，故切切然议之，遂使小人乘间投隙，持一偏可喜之论以媒己私利。',
    '于是浮浪之士，失职这徒，乘间抵隙。',
    '指趁机钻空子。',
    '《新唐书·刘栖楚传》：“然其性诡激，敢为怪行，乘险抵巇，若无顾藉。‘',
    '冒险钻空子。巇，多指（山岭）险恶、险峻。',
    '恐乘隙捣虚，瑕者毕坚，而胜负之势未可料也。',
    '趁空子，攻虚弱。',
    '间不自入，乘隙而入。',
    '趁着虚弱疏漏的地方进入。',
    '他那神气似真非真，因为是师长的老部属，平时又会逢场作趣，这时节乘顺水船就来那么一手。',
    '比喻顺势行事。',
    '吴监督子登闻之，遂又乘风兴浪，思设法以破坏此留学事务所。',
    '比喻趁机挑起事端。',
    '悫年少时，炳问其志，悫曰：‘愿乘长风破万里浪。’',
    '船只乘着风势破浪前进。比喻排除困难，奋勇前进。',
    '投机主义蜊是最善于乘风转舵的。',
    '比喻顺随情势改变态度。',
    '陛下诚能行此二者……后日之政，如顺风吹毛，乘高决水，可以不劳而成功者。',
    '倘若交锋，不宜浪战，须乘高居险，出奇匿伏。',
    '居：占据。占据高峻、险要的地势。',
    '只留下伊行笔踪就不怕事成空，准备着乘鸾跨凤。',
    '乘鸾：求得佳偶。比喻结成美好的佳偶。',
    '黄尚为司徒，与李元礼俱娶太尉桓温女，时人谓桓叔元两女俱乘龙，言得婿如龙也。',
    '乘龙：女子乘坐于龙上得道成仙。佳婿：称意的女婿。旧时指才貌双全的女婿。也用作誉称别人的女婿。',
    '……昞遂奋衣来坐，神志肃然，曰：‘向闻先生欲求快女婿，昞其人也。’瑀遂以女妻之。',
    '乘龙：女子乘坐于龙上得道成仙。快婿：称意的女婿。旧时指才貌双全的女婿。也用作誉称别人的女婿。',
    '你是老爷跟马贱人，敢辱我乘龙贵婿，打不的你？',
    '对别人的女婿的称赞。',
    '沈文素呀！沈文素！你蟾宫折桂，莫大还有乘龙配凤的好运么？',
    '比喻得佳偶，结良缘。',
    '假作痴呆，纠缠不休。',
    '九世犹可以复仇乎？虽百世可也。',
    '九世：九代，形容历时久远。指久远的深仇。',
    '张公艺九世同居，北齐东安王永乐、隋大使梁子恭躬慰抚，表其门。',
    '九世：九代。九代人居住在一起不分家。',
    '我这个糟老头子捡点破烂，虽说有点霸道，九九归一，也是生活逼的。',
    '九九归原，他们的目的，总不外乎一个翰林学士的头衔。',
    '夫或跃在渊者，终飨九五之位。',
    '九五：指帝位。指帝王的尊位。',
    '九五，飞龙在天，利见大人。',
    '九五：指帝位。旧指帝王的尊位。',
    '“为山九仞，功亏一篑”的略语。比喻功败垂成。',
    '七匠八娼九儒十丐，后之者，贱之也。',
    '儒：旧指读书人。元代统治者把人分为十等，读书人列为九等，居于末等的乞丐之上。后指知识分子受到歧视和苛待。',
    '功名事，不信朝鳞暮羽。九关虎豹如许。',
    '比喻凶残的权臣。',
    '之子于归，皇驳其马，亲结其缡，九十其仪。',
    '九、十：虚数，形容多；仪：仪表。旧时指女子出嫁时，父母反复叮咛要注意仪容举止。指礼仪非常多。也指夸奖新妇的仪态很美。',
    '九十春光在何处？古人今人留不住。',
    '九十：指春季三个月，共九十天。指春天的美好光景。',
    '有志之士，望古遥集。无由起其人于九原之下。',
    '九原：山名，春秋时晋国卿大夫的墓地。泛指墓地。',
    '赵文子与叔向游于九原，曰：‘死者若可作也，吾谁与归？’',
    '九原：春秋时晋国卿大夫的墓地在九原，因称墓地；作：起，兴起。设想死者再生。',
    '至如三奔三景之妙，九变十化之精，各探其门，互称要妙。',
    '昔得管仲相齐桓，霸诸侯，有九合一匡之功。',
    '原指春秋时齐桓公多次会合诸侯，称霸主，使混乱的政局得以安定。后用以形容有卓越的治国才能。',
    '至于中正九品，上圣古贤皆所不为，岂蔽于此事而有不周哉，将以政化之宜无取于此也。',
    '指中国古代魏、晋、南北朝维护世族特权的官吏选拔制度。代指等级制度。',
    '风微烟澹雨萧然，隔岸马嘶何处。九回肠，双脸泪，夕阳天。',
    '形容回环往复的忧思。回肠：形容内心焦虑不安。',
    '是以肠一日而九回，居则忽忽若有所忘。',
    '形容痛苦、忧虑、愁闷已经到了极点。同“九回肠”。',
    '上畅九垓，下坼八埏。',
    '善守者藏于九地之下，善攻者动于九天之上，故能自保而全胜也。',
    '原指天上的最高层和地的最深处。后比喻两者相差极远。',
    '你看此女非凡，真乃九天仙女也。',
    '指天上的仙女，比喻绝色美女。',
    '俱怀逸兴壮思飞，欲上青天揽明月。',
    '揽：采摘。到天的最高处去摘月。常形容壮志豪情。',
    '九如：该诗中连用了九个“如”字，有祝贺福寿延绵不绝之意；天保：《诗经·小雅》中的篇名。旧时祝寿的话，祝贺福寿绵长。',
    '杀头固然是没有命吃饭，打屁股也是九宗七祖都不得超生的事。',
    '泛指祖宗。',
    '合抱之木，生于毫末；九层之台，起于累土；千里之行，始于足下。',
    '累：堆迭，积聚。九层高台，是从一筐土开始堆积起来的。比喻欲成大事，须从基础做起。',
    '天地之间，九州八极。',
    '九州：中国古代地域共划分为九州；八极：九州之外最边远的地方。指天下所有远近的地区。',
    '九州四海常无事，万岁千秋乐未央。',
    '犹言天下。泛指全中国。',
    '十八年而有六年之积，二十七年而有九年之储。',
    '九年的储备。指国家平时有所积蓄，以备非常。',
    '国无九年之蓄，曰不足；无六年之蓄，曰急；无三年之蓄，曰国非其国也。',
    '蓄：积聚，储藏。九年的储备。指国家平时有所积蓄，以备非常。',
    '九战九胜，追北千里。',
    '形容每战必胜。',
    '方人九折臂，更历方药，则成良医。',
    '九：泛指多次；折：断。多次折断胳膊，经过反复治疗而熟知医理。比喻阅历多，经验丰富。',
    '公输盘九设攻城之机变，子墨子九距之。',
    '九：泛指多次；距：通“拒”，抵抗。形容攻守征战非常激烈。',
    '爹爹也，全不怕九故十亲笑耻。',
    '建心乎窈冥之野，藏志乎九旋之渊，虽有明目，孰能窥其情。',
    '九：多数；旋：旋窝；渊：深渊。旋窝多的深渊。比喻智谋深广。',
    '九春三秋，天景清丽。',
    '九春：春季共九十天，故称“九春”；三秋：秀季三个月，故称“三秋”。指春天和秋天的美好时光。',
    '待我引他到九曲十八弯中，唤我那结义兄弟出来，就好与他算账。',
    '曲：曲折；弯：不直。指十分弯曲。',
    '形容痛苦、忧虑、愁闷已经到了极点。',
    '画家于人物，必九朽一罢。谓先以土笔扑取形似，数次修改，故曰九朽；继以淡墨一描而成，故曰一罢，罢者，毕事也。',
    '原指画人物的一种技法。后也指在文学、艺术创作中严肃认真的态度。',
    '凡士子不由及第出身，便做到九棘三槐，终久被人欺侮。',
    '棘、槐：树名。古代皇宫外朝种植棘树和槐树，作为臣子朝见皇帝时所居位置的标志。后泛指三公、九卿等高级官职。',
    '虽九死无一生，未足悔恨。',
    '亦余心之所善兮，虽九死其犹未悔。',
    '九：表示极多。纵然死很多回也不后悔。形容意志坚定，不认经历多少危险，也决不动摇退缩。',
    '泛指所有的江河。',
    '九泉：地下。死人埋葬的地方，即在阴间。',
    '冀幽诚丹款，傥或昭然，虽复身膏草土，九泉无恨。',
    '九：虚数，指极深；九泉：也称“黄泉”，人死后埋葬的地方。指死而无恨。',
    '九洲四海常无事，万岁千秋乐未央。',
    '做子弟的须要九流三教皆通，八万四千傍门尽晓。',
    '莫遣洪炉旷真宰，九流人物待陶甄。',
    '指社会上的各种人物。',
    '汉·刘安《七略·诸子略》中把诸子思想分为十家，即：儒、道、阴阳、法、名、墨、纵横、杂、农、小说十家，除掉小说家，就称为九流。',
    '先秦到汉初各种学说派别的总称。',
    '见九流宾客，不与交言。',
    '先秦到汉初有法、名、墨、儒、道、阴阳、纵横、杂、农九种学术流派。指上中下各品的人才和各种人物。',
    '阴阳、卜筮、占相、医方、族氏、山经、地志、字书、图画九流百家天人之书，乃至浮图、老子、外国之说，皆所详悉。',
    '泛指各种学术流派。同“九流一家”。',
    '说甚么九烈三贞孟姜女，他可也不比其余。',
    '假令仆伏法受诛，若九牛亡一毛，与蝼蚁何以异？',
    '兄弟，你不知他靴尖点地，有九牛二虎之力，休要放他小歇。',
    '比喻很大的力气。常用于很费力才做成一件事的场合。',
    '形容态度十分坚决。',
    '泛指古代典籍。',
    '汉崔篆母师氏，通九经百家之言。',
    '泛指古代典籍和各种学术流派。',
    '热气上升为蒸，火干为熯。比喻久经熬炼。',
    '矿山是除了神话中的仙境之外，最令人神往的去处，而三教九流，九行八业之中，矿工是最崇高的职业。',
    '指各种行业。',
    '九衢三市风光丽，正万家、急管繁弦。',
    '指繁华的街市。',
    '其一转至九转，迟速各有日数多少，以此知之耳。其转数少，其药力不足，故服之用日多得仙迟也；其转数多药力成，故服之用日少而提仙速也。',
    '转：循环变化；丸：指金丹。道家语，指炼得九转金丹。后常比喻经过长期不懈的艰苦努力而终于获得成功。',
    '转：循环变华。原为道家语，指炼得九转金丹。后常比喻经过长期不懈的艰苦努力而终于获得成功。',
    '九锡：古代帝王赐给重臣的车马、虎贲等九种器物。形容位高权重，深受皇帝宠信的大臣。',
    '帝王受百官朝拜的大殿。同“九间朝殿”。',
    '帝王受百官朝拜的大殿。间，指两柱的距离。九间，极言堂殿之宽广。亦作“九间大殿”。',
    '九阍虎豹嗟难近，一炬龙蛇事可怜。',
    '比喻凶残的权臣。同“九关虎豹”。',
    '太子也你在这七宝盒中，我陈琳早魂飞九霄云外。',
    '呜呼，贤首之宗不振久矣，凛乎若九鼎一丝之悬。',
    '老师～，即纳吉问名，不逾于此，门生传示司马，使他静守甥舍，以待乘龙可也。 ★清·无名氏《人中画·风流配》',
    '《史记·平原君列传》：“毛先生一至楚而使赵重于九鼎大吕。毛先生以三寸之舌，强于百万之师。胜不敢复相士。”',
    '昔之所以议进退天下士大夫者，今又重之以权位，故其一言之出，则九鼎不足为重。',
    '形容说话有分量，比较起来九鼎也不算重。',
    '毛先生一至楚，而使赵重于九鼎大吕。',
    '九鼎：古传说，夏禹铸九鼎，象征九州，是夏商周三代的传国之宝；大吕：周庙大钟。比喻说得话力量大，分量重。',
    '逮平贻厥，乃乞丐之徒，嗣恶稔之余基，纵奸邪之凶德。',
    '徒：辈。形容乞求恩宠的人。',
    '君释褐登宰府，三十六日，拥麾盖，守兵马郡，乞儿乘小车，一何驶乎？',
    '讽刺官职提升得快的话。',
    '暴富乞儿休说梦，谁家窖里火无烟。',
    '乞儿：乞丐。乞丐骤然发了大财。比喻学问大增。',
    '自此之后，范氏门徒，路遇乞儿马医，弗敢辱也。',
    '乞儿：乞丐；马医：兽医中专治马病的人。旧指卑贱的人。',
    '荒时暴月，向亲友乞哀告怜，借得几斗几升，敷衍三日五日，债务丛集，如牛负重。',
    '哀：怜悯；告：请求。乞求别人的怜悯和帮助。',
    '怜：怜悯；乞：乞求。狗摇着尾巴向主人乞求爱怜。比喻装出一副可怜相向人讨好。',
    '太岁在酉，乞浆得酒。',
    '浆：淡酒，一种比酒质量差的饮料。讨杯浆水喝，却得到了酒。比喻得到的超过所要求的。',
    '寡君欲徼福于周公，愿乞灵于臧氏。',
    '乞灵：求助于所谓的的某种中权威；药石：治病的药物和砭石，泛指药物。求助于神灵和药物。',
    '乞丐似的寒酸相。',
    '充国乞骸骨，赐安车驷马。',
    '乞：求，讨。古代官吏因年老请求退职。',
    '作之不变，习与体成，则自然矣。',
    '习：习惯。长期的习惯将会形成一定的性格。',
    '兹乃不义，习与性成。',
    '性：性格。长期习惯于怎样，就会形成怎样的性格。有习惯成自然的意思。',
    '盖承成化以来，滥授冗员，俱以中旨批出，遂习为故常，不以为怪也。',
    '故常：常例。经常如此，养成习惯，就被当作常规了。',
    '民生而有习有常，以习为常。',
    '习：习惯。指某种事情经常去做，或某种现象经常看到，也就觉得很平常了。',
    '将由居上者未能悛改，为下者习以成俗，教化陵迟。',
    '俗：习惯。长期以来就是这样做，成了习俗。',
    '习以成性，迁善远罪而不自知，行成德立。',
