    '云气升腾，柱石湿润。形容湿气很重。',
    '水激则旱兮，矢激则远；万物回薄兮，振荡相转。云蒸雨降兮，错缪相纷；大钧播物兮，坱圠无垠。',
    '云气向上升腾，雨水降落。形容下雨。也比喻广施恩泽。',
