    '云行雨洽，天临地持。',
    '比喻广施恩泽。',
    '于是大厦云谲波诡，摧摧而成观。',
    '形容众人像云聚、像水涌一样从各处涌来并聚集在一起。',
    '度曲未终，云起雪飞，初若飘飘，后遂霏霏。',
    '如云兴起，如雪飘飞。比喻乐曲悠扬，变化有致。',
    '《汉书·叙传下》：“云起龙襄，化为侯王。”颜师古注：“襄，举也。”一本作“云起龙骧”。',
    '云起龙骧，化为侯王。',
    '夫票盐售价不及纲盐之半，而纲商岸悬课绌，票商云趋鹜赴者，何哉？',
    '比喻从四方奔赴而至。',
    '云为车兮风为马。',
    '指神灵的车马。',
    '把一桩惊风骇浪的案，办得来云过天空。',
