    '忽然间昏惨惨云迷雾罩，疏剌剌风吹叶落，振山林声声虎啸，绕溪涧哀哀猿叫。',
    '形容天气昏暗，气氛阴森。',
    '巴的到绿杨渡口，早则是云迷雾锁黄昏后。',
    '云雾遮挡视线，看得很模糊。',
    '手抉云汉分天章，天孙为织云锦裳。',
    '云锦：神话传说中织女用彩云织出的锦缎。天章：彩云组合成的花纹。比喻文章极为高雅、华美。',
    '云阶月地一相过，未抵经年别恨多。',
    '以云为阶，以月为地。指天上。亦指仙境。',
    '斩木为兵，揭竿为旗，天下云集响应，嬴粮而景从，山东豪杰遂并起而亡秦族矣。',
