    '朝发河海，夕宿江汉，沉浮往来，云集雾散。',
    '像云一样聚集，像雾一样离散。比喻人事盛衰，聚散无常。',
    '原指古代神话传说巫山神女兴云降雨的事。后称男女欢合。',
    '云雾之盛，顷刻而讫；暴雨之盛，不过终日。',
