    '两条大江，骤然相见，欢腾拥抱，激起云雾迷蒙，波涛沸荡，至此似乎稍为平定，水天极目之处，灰蒙蒙的远山展开一卷清淡的水墨画。',
    '霓，虹也。雨则虹见，故大旱而思见之。',
    '比喻迫切地盼望。',
    '云霞雕色，有逾画工之妙。',
    '云霞：比喻文采。形容满眼都是精采的文笔、',
    '云飞泥沉，卑高异等。',
    '①比喻消失。②比喻悬殊极大。',
    '千古事、云飞烟灭。贺老定场无消息，想沉香亭北繁华歇。',
    '比喻消逝。',
    '云飞雨散今如此，绣闼雕甍作荒谷。',
    '比喻原先的事物不复存在。',
    '看他那云鬟雾鬓，杏脸桃腮，柳眉星眼，不由咱不动心也。',
    '头发象飘浮萦绕的云雾。形容女子发美。',
    '云龙喻贵，井蛙喻贱。',
    '云端的龙，井底的蛙。比喻地位的高下相差极大。',
    '云从龙，风从虎，圣人作而万物睹。',
    '虎啸生风，龙起生云。指同类的事物相感应。',
    '宣宗幸万寿山、玉澜堂，锡宴十五老臣……云龙鱼水，夫岂偶然。',
    '如同云与龙，鱼与水一样。比喻君臣相得',
    '互相不能容纳对方。指高职位官员之间的一种关系，在行使职权时彼此不一致。',
    '老师教得十分尽力，希望他继承自己的事业，再攀艺术高峰；学生非常刻苦，进步之快超出教师的逆料。于是，二者互为因果。',
    '原因和结果相互联系，相互转化。',
    '间或肆志风雅，率求名位相埒者，互为标榜，不复商榷于布衣之贱。',
    '标榜：夸耀。彼此之间互相吹嘘、颂扬。',
    '陈祗代允为侍中，与黄皓互为表里。',
    '甲为乙的外表，乙为甲的内里。比喻互相依存，互相接受。',
    '相互之间展开竞争或斗争，以取得优胜或领导地位。',
    '潘大娘说林老太婆的媳妇结识戏子，林老太婆说潘大娘偷和尚，彼此互剥痛疮。',
    '比喻互揭阴私。',
    '彼此互相推托，皆齐之不收，反遗之以与金人用。',
    '彼此之间互相推托，谁也不愿承担责任。',
    '甚至互相推托，以为能明哲。',
    '诿：也作“委”，推辞；推诿：把责任推给别人。彼此之间互相推托，谁也不愿承担责任。',
    '自是正直废放，邪枉炽结，海内希风之流，遂贡相标榜，指天下名士，为之称号。',
    '标榜：吹嘘，夸耀。互相称颂，互相吹嘘。多用贬义。',
    '天下之人，互相残杀。',
    '残：毁坏，伤害。彼此之间相互残害，各不相容。',
    '为之贾，以通其有无。',
    '通：往来。拿出自己多余的东西给对方主，与之进行交换，以得到自己所缺少的东西。',
    '汉·刘向《说苑·反质》',
    '用来讽刺那些思想保守，守着老一套，拒绝接受先进经验的人。',
    '有妫之后，将育于姜。五世其昌，并于正卿。八世之后，莫之与京。',
    '世：代；其：时间副词，交要。五世之后，子孙昌盛。旧时用于祝人新婚。',
    '他的五亲六眷，家理师徒，磕头摆把的，布满全屯。',
    '指各种关系的亲眷。',
    '两手、两膝和头一起着地。是佛教一种最恭敬的行礼仪式。比喻佩服到了极点。',
    '昔在长安醉花柳，五侯七贵同杯酒。',
    '泛指达官显贵。',
    '五侯九伯，女实征之，以夹辅周室。',
    '五侯：公、侯、伯、子、男五等诸侯；九伯：九州之长。泛指天下诸侯。',
    '语出唐·韩翃《寒食》诗：“日暮汉宫传蜡烛，轻烟散入五侯家。”旧俗寒食节禁火，而宫中传烛分火于五侯之家，贵宠可见。',
    '用以形容豪门权势的显赫景象。',
    '五光徘徊，十色陆离。',
    '形容色彩鲜艳，花样繁多。',
