    '毛色凋落的马。比喻年老体衰。',
    '师父，我受了菩萨戒行，断了五荤三厌，在我丈人家持斋把素，更不曾动荤，今日见了师父，我开了斋罢。',
    '五荤：佛教忌食的五种蔬菜，即大蒜、小蒜、兴渠、慈葱、茗葱；三厌：道教忌食的三种肉：即雁、狗、乌龟。泛指饮食的禁忌。',
    '观自在菩萨，行深船若波罗密多，时照见五蕴皆空，度一切苦厄。',
    '五蕴：佛家语，指色、受、想、行、识。众生由此五者积集而成身，故称五蕴。五蕴都没有了。指佛家修行的最高境界。',
    '凡人三百六十节，九窃，五藏六府。',
    '指体内全部器官。五藏：心、肺、脾、肝、肾。六府：大肠、小肠、胃、胆、膀胱、三焦。亦作“五脏六腑”。',
    '你也晓得，皇上家的钱都是要功归实用的，那里能由你五虚六耗，赚了许多。',
    '瑒祖奉，字世叔。才敏善讽诵，故世称‘应世叔读书，五行俱下。’',
    '五行文字一并看。形容读书速度快。',
    '五行八作，就没你这一行。',
    '你把那先天《周易》细回圈，将我那五行四柱从头算。',
    '五行：指金、木、水、火、土；四柱：指年、月、日、时。旧指命相家替人算命的根据。',
    '奉少聪明，自为童儿及长，凡所经履，莫不暗记。读书五行并下。',
    '梦里几回富贵，觉来依旧凄惶。今日是千年一遇，叩头莫五角六张。',
    '角、张：星宿名。形容七颠八倒。也比喻事情不顺利。',
    '长卿自以为五言长城，系用偏师攻之，虽老益壮。',
    '称誉善于作五言诗的好手。',
    '我满面通红地后躲，左右张望：‘别别，五讲四美。’',
    '五讲：讲文明、讲礼貌、讲卫生、讲秩序、讲道德；四美：指心灵美、语言美、行为美、环境美。指新时期人们行为准则。',
    '四体不勤，五谷不分，孰为夫子？',
    '五谷：通常指稻、黍、稷、麦、菽。指不参加劳动，不能辨别五谷。形容脱离生产劳动，缺乏生产知识。',
    '五谷不升，谓之大侵。',
    '庄稼不生长。指灾荒之年。',
    '当时文人墨士名公巨卿炫赫一时者，不知湮没多少，而诸匠之名，顾得不朽，所谓五谷不熟,不如稊稗者也。',
    '稊：象稗的草，结实如小米；稗：稗子。比喻条件素质再好，如果最后不能有所成就，那就还不如素质条件差的。',
    '是故风雨时节，五谷丰熟，社稷安宁。',
    '指年成好，粮食丰收。同“五谷丰登”。',
    '是故风雨时节，五谷丰登，社稷安宁。',
    '登：成熟。指年成好，粮食丰收。',
    '风雨以时，则五谷丰稔。',
    '五谷：指稻、黍、稷、麦、菽，泛指农作物；稔：指庄稼成熟。形容年成好。',
    '形容书读的非常多。',
    '比喻读书多，学识渊博。',
    '那窗外的孙杰却被三姊弄得如在五里云雾中。',
    '性好道术，能作五里雾。',
    '曲罢曾教善才服，妆成每被秋娘妒。五陵年少争缠头，一曲红绡不知数。',
    '指京都富豪子弟。',
    '结客五陵英少，脱手黄金一笑，霹雳应弓弦。',
    '指京都富豪子弟。同“五陵年少”。',
    '你直叩丹墀，夺得朝章，换却白衣 。觑面仪，比向日，相别之际，更有三千丈五陵豪气。',
    '指高门贵族的豪迈气概。',
    '今有五雀六燕，集称之衡，雀俱重，燕俱轻，一雀一燕交而处，衡适平。',
    '比喻双方轻重相差不多。',
    '他和婆姨用复员费做本钱逢集摆小摊的货箱子，被捣得五零二落，东一块西一块扔在院里。',
    '众公子带领人马一拥齐上，把各兵杀的五零四散，各自逃生。',
    '形容零星涣散。',
    '要是我从中赚一个钱，天上现在有云影，教我五雷轰顶。',
    '比喻不得好死。',
    '不以六律，不能正五音。',
    '五音：指宫、商、角、徵、羽五个音阶；六律：定乐器的标准。指古代音律。后也泛指音乐。',
    '形容色彩复杂或花样繁多。引伸为各色各样。',
    '我们要对这些～严加管理。',
    '形容不守规矩、不受管束的人。',
    '无不盖你亏心汉，今日把你分尸五马，远配千年。',
    '古代的一种酷刑，用五匹马分裂人的头和四肢，又称“四裂”。比喻硬把完整的东西分割得非常零碎。',
    '惟其中有五鬼闹判一语，不知所出；以问余，亦无以应也。',
    '许多小鬼戏弄判官。剧目名。旧时也比喻居上位者被对自己不满或轻蔑的人所戏弄。',
    '只为五黄六月，无人使唤，父母又年老，所以亲身来送。',
    '指阴历五、六月间天气最炎热的时候。',
    '如羊之跪乳，鸟之反哺，其乐将矢谁，视五鼎万钟若不能过之。',
    '指高官厚禄。',
    '夫攻形不如越，而攻心不如吴，而君臣上下少长贵贱毕呼霸王，臣窃以为犹之井中，而谓曰：‘我将为尔求火也。’',
    '在水井里去寻求火。比喻方法或方向不对，根本达不到目的。',
    '因井中视星，所见不过数星。',
    '从井里看天上的星星。比喻眼光短浅，见识狭隘。',
    '一切都是井井有序，和往常一样。',
    '有条理，有秩序。',
    '孝基条分理析，井井有方。',
    '形容有条理有办法。',
    '井井兮其有理也。',
    '井井：形容有条理。形容说话办事有条有理。',
    '女外理生计，内训孤儿，井井有法。',
    '有条理、有法度。',
    '形容整齐，有条有理。',
    '有条理，有秩序。同“井井有序”。',
    '直木先伐，甘井先竭。',
    '以：因为；甘：甜；竭：枯竭。甜水井由于取用的人多，会先枯干。比喻好的事物不能长久存在。',
    '井养而不穷也。',
    '穷：尽。把水井治理保护好，则水源不尽。比喻不断得到别人的恩惠。',
    '以言刚正之主不纳非贤，必须行洁才高而乃后用。故曰井冽寒泉食也。',
    '冽：清澈；寒：清冷。只有在井很洁净、泉水清冷明澈的情况下才喝水。即只喝干净凉爽的水。比喻刚正的君主任用德才兼备的人。',
    '井蛙不可以语于海者，拘于虚也。',
    '井底的蛙只能看到井口那么大的一块天。比喻见识狭窄的人。',
    '镜里看形见不难，水中捉月争拈得？',
    '捞：从液体中取物。从井底捞月亮。比喻做事白费力气，根本达不到目的。',
    '即井蛙。',
    '妾阅人多矣，皆是井底蛤蟆，未有中原麟凤。',
    '指井底的癞蛤蟆，比喻没有见识的人。',
    '井底引银瓶，银瓶欲上丝绳断；石上磨玉簪，玉簪欲成中央折。',
    '比喻前功尽弃。',
    '则你那自尊自贵无高下，真乃是井底鸣蛙。',
    '指井中之蛙。',
    '我和他‘井水不犯河水’，怎么就冲了他？',
    '比喻各管各的，互不相犯。',
    '井渫而不见食，犹人修已全洁而不见用。',
    '指井虽浚治，洁净清澈，但不被饮用。比喻洁身自持，而不为人所知。',
    '惧匏瓜之徒悬兮，畏井渫之莫食。',
    '比喻洁身自持，而不为人所知。同“井渫不食”。',
    '凡本年之事有所闻必归此匣，分月日先后次第之，井然有条，真可为法也。',
    '钜儒著述，皆有本原，不得以井管拘墟，轻相訾议也。',
    '比喻浅陋、片面的见识。',
    '（傅育）食禄数十年，秩奉尽赡给知友，妻子不免操井臼。',
    '井：汲水；臼：舂米。指亲自操作家务。',
    '家贫亲老，不择官而仕，亲操井臼。',
    '井：汲水；臼：舂米；躬：亲自；操：从事。指亲自操持家务。',
    '今既闻命，实饱于玄风，醉其真义也。吾向来井蛙醯鸡哉。',
    '醯鸡：昆虫名，即蠛蠓，常用以形容细小的东西。比喻眼界不广，见识浅薄。',
    '亘：横贯；亘古：从古至今；灭：绝灭。从古到今，永不绝灭。形容永久的生命力。',
    '条贯脉络，井井不乱，只今便在目前，而亘古亘今，颠扑不破。',
    '亘：横贯。指贯串古今，从古到今。',
    '从来稀有，亘古奇闻。',
    '亘古：从古代到现代；奇：稀有不常见的。从古到今很少听到或见到的事情。',
    '从来稀有，亘古新闻。',
    '亘古：从古代到现代。从古到今很少的事情。',
    '太青晚作《嘉莲》诗，七言今体至四百余首，亘古未有。',
    '亘古：人人有责从古代到现在。从古到今都不曾有过。',
    '真个是亘古未闻，于今罕有！',
    '指从古到今都没有听说的',
    '亘古通今，明鲜晦多。',
    '亘：横贯；通：贯通。指从古到今。',
    '只见一簇人亚肩叠背的围着一个汉子。',
    '前后的人肩背紧挨着。形容人多拥挤。',
    '武松在轿上看时，只见亚肩迭背，闹闹穰穰，屯街塞巷，都来看大虫。',
    '肩压肩，背挨背。形容人多拥挤。',
    '且秦以任刀笔之吏，吏争以亟疾苛察相高。',
    '指急剧猛烈，以苛刻烦琐为明察。',
    '若乃居安而不思危，寇至而不知惧，此谓燕巢于幕，鱼游于鼎，亡不待夕矣。',
    '亡：灭亡，死亡。待：等待。夕：傍晚。灭亡等不到傍晚。比喻很快就会灭亡。',
    '汉分王子弟，享国四百年。魏晋废之，亡不旋跬。',
    '犹亡不旋踵。形容时间极短。',
    '晋武帝削平吴蜀，任贤使能，容受直言，有明主之风，然而亡不旋踵。',
    '指迅速灭亡。不旋踵，来不及转脚跟。形容时间极短。',
    '杀人自生，亡人自存，经之所疾。',
    '亡：死亡；存：留存。牺牲别人保全自己。泛指毁掉别人成全自己的卑鄙自私的行为。',
    '亡命之徒，咸从赋役。',
    '指逃亡的人。也指冒险犯法，不顾性命的人。',
    '夫秦灭六国，楚最无罪。自怀王入秦 不反，楚人怜之至今，故楚南公曰‘楚虽三户，亡秦必楚’也。',
    '指不畏强暴，奋起推翻黑暗统治。',
    '亡国之主反此，乃自贤而少人。',
    '主：君主。亡国时的君主，即最后一代君王。',
    '将子有亡国之事、斧铖之诛而为此乎？',
    '事：事情，事件。使国家灭亡的事件。',
    '寡人虽亡国之余，不鼓不成列。',
    '余：余留。已灭亡国家留下来的后代。',
    '亡国之音不得至于庙，亡国之社不得见于天，亡国之器陈于廷，所以为戒。',
    '指象箸、玉杯之类的器皿，古代作为骄奢亡国的象征。',
    '此亡国之声，不可遂也。',
    '指淫靡的音乐。',
    '亡国之社，以为庙屏，戒也。',
    '已亡国家的祠社。古代天子将其作为亡国的象征，以自儆戒。',
    '夫骄君必好利，而亡国之臣必贪于财。',
    '使国家灭亡的臣子。现比喻对国家有损害的官员。',
    '故圣人为政，必先诛之，伪巧言以辅非而倾覆国家也。今子安取亡国之语而来乎？',
    '语：话语、言论。使国家灭亡的言论。',
    '国内之民将叛，四方之士不至，此乃亡国之道也。',
    '道：道路，途径。国家灭亡的途径。比喻执政者违背民意，不得人心。',
    '亡国之音哀以思，其民困。',
    '原指国家将亡，人民困苦，因此音乐也多表现为哀思的曲调，后多指颓靡淫荡的歌曲。',
    '亡国之大夫者，谓亡君之国，言不忠且无智也。',
    '指不忠不智的前朝遗臣。',
    '现在他们眼看就要当亡国奴了，除了反抗，再没有出路。',
    '指已经亡国或所在国土被侵占、受外国侵略者奴役的人。',
    '臣闻王主富民，霸主富武，亡国富库。',
    '亡：灭亡；国：国家；富：富足；库：国库。国家灭亡，国库富足。指为求国库富足，对百姓残酷压榨，横征暴敛，从而使国家灭亡。',
    '灭亡秦国的一定是楚国。指不畏强暴，奋起推翻黑暗统治。',
    '一人祝之，一国诅之，一祝不胜万诅，国亡不亦宜乎？祝其何罪？',
    '怨：埋怨；祝：太祝，旧时为执掌祭礼祝祷的官。旧指国家衰亡时，不从自身找原因，而去埋怨为国家祭祀祝祷的人。',
    '在如此的亡国灭种的紧急关头，国民党如果还因循上述的政策不愿迅速改变，将使抗日战争蒙受绝大的不利。',
    '国家灭亡，种族灭绝。指一个国家被彻底毁灭。',
    '国家覆灭、家庭毁灭。',
    '安其危而利其葘，乐其所以亡者。不仁而可与言，则何亡国败家之有？',
    '国家灭亡了，家庭破坏了。比喻给国家及个人造成极严重的后果。',
    '大军已驻乎心腹，鼎鱼幕燕，亡在旦夕。',
    '旦：早晨；夕：晚上。灭亡只是早晚的事情。',
    '亡戟得矛，可以归乎？',
    '比喻得到的和失去的相当，或有失有得。',
    '亡是公者，无是人也。',
    '亡：即无。指不存在的人或物。',
    '覆鹿遗蕉，亡猿灾木，非敌非寇，自倾自覆。',
    '比喻欲损人反而害己的行为。同“亡猿祸木”。',
    '唐大历中，有猴数百集古田杉林中，里人欲伐木杀之。中一老猴忽跃去近邻一家纵火焚屋。里人惧，亟走救火，于是群猴脱去。',
    '比喻欲损人反而害己的行为。',
    '秦无亡矢遗镞之费，而天下诸侯已困矣。',
    '损失箭和箭头。比喻军事上的细微损失。',
    '指不畏强暴，奋起推翻黑暗统治之事。',
    '富者田连阡陌，贫者亡立锥之地。',
    '亡：无；立锥：插锥子。没有插锥尖的一点地方。形容极其贫困。',
    '亡：丢失。叹：叹息。为丢失了羊而叹息。比喻探索学问，徘徊歧路，结果一无所得，空留遗憾。亦作“亡羊歧路”。',
    '亡羊而得牛，则莫不利失也。',
    '丢掉羊，得到牛。比喻损失小而收获大。',
    '大道以多歧亡羊，学者以多方丧生。',
    '见兔而顾犬，未为晚也；亡羊而补牢，未为迟也。',
    '亡：逃亡，丢失；牢：关牲口的圈。羊逃跑了再去修补羊圈，还不算晚。比喻出了问题以后想办法补救，可以防止继续受损失。',
    '杀匈奴亡魂丧胆，保家邦万载咸宁。',
    '形容惊慌恐惧到极点。',
    '哥哥你宽肺腑，休间阻，我教他亡魂丧魄，认个贤。',
    '饿的我肚里饥失魂丧魄，冻的我身上冷无颜落色。',
    '擅利淫刑之守，亢厉以为能。',
    '亢厉：极为严厉；能：才能。以严酷作为自己的才能。',
    '吉不能亢身，焉能亢宗？',
    '指性情高傲。',
    '俯无倨鵄之呼，仰无亢极之悔，人莫之识，邈矣辽哉',
    '亢：至高的；悔：灾祸。意为居高位的人要戒骄，否则会失败而后悔。后也形容倨傲者不免招祸。',
    '动朱唇，纡清扬，亢音高唱，为乐之方。',
    '亢：喉咙。放开喉咙，高声歌唱。',
    '上九，亢龙有悔。',
    '以故人人到母后跟前，交口同声，誉称晋王仁孝聪明，不似太子寡恩傲礼。',
    '犹言众口一词。所有的人都说同样的话。',
    '诸公要人，争欲令出我们下，交口荐誉之。',
    '诸公要人，争欲令出我门下，交口荐誉之。',
